                                                data2.Add(num2);
                                            }
                                            string PlanQty3 = ds2.Tables[2].Compute("SUM(PlanQty)", " TimeHour>=18 AND TimeHour<24").ToString();
                                            string HasQty3 = ds2.Tables[2].Compute("SUM(HasQty)", " TimeHour>=18 AND TimeHour<24").ToString();
                                            int.TryParse(PlanQty3, out num1);
                                            int.TryParse(HasQty3, out num2);
                                            data1.Add(num1);
                                            data2.Add(num2);

                                            serviceData.Add(new { data = data1 });
                                            serviceData.Add(new { data = data2 });
                                            dataRow["serviceData"] = serviceData;
                                        }

                                    }
                                }
                                msg = "读取成功";
                            }
                            else
                            {
                                msg = "没有接收到dicID";
                                result = false;
                            }
                        }
                        catch (Exception ex)
                        {
                            msg = ex.Message;
                            result = false;
                        }
                    }
                }
                catch (Exception ex)
                {
                    result = false;
                    msg = ex.Message;
                }
                if (result == false)
                {
                    ds2 = new DataSet();
                    ds2.Tables.Add(new DataTable());
                }

                int count = 0;
                try
                {
                    count = int.Parse(ds2.Tables[0].Rows[0][0].ToString());
                }
                catch (Exception ex)
                {

                }
                IsoDateTimeConverter timeFormat = new IsoDateTimeConverter();
                timeFormat.DateTimeFormat = "yyyy-MM-dd";

                return JsonConvert.SerializeObject(new
                {

                    data = ds2,//数据
                    result//返回标记
                           ,
                    msg//返回的信息
                           ,
                    count = count < ds2.Tables[0].Rows.Count ? ds2.Tables[0].Rows.Count : count //记录数
                }, timeFormat);
            }
        }

