        /// <summary>
        /// 下达到销售计划
        /// </summary>
        /// <returns></returns>
        public ApsLegacyJsonResult APSTOSalesPlan()
        {
            bool result = true;
            string msg = "";
            ApsLegacyJsonResult ApsLegacyJsonResult = new ApsLegacyJsonResult();
            try
            {



                JArray jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;
                if (jArray == null || jArray.Count == 0)
                {
                    msg = "未接受到数据，请确认是否为JSON格式";
                    result = false;
                    ApsLegacyJsonResult = base.FormResult(result, msg, null);
                }
                else
                {


                    Entities.Configuration.ValidateOnSaveEnabled = false;

                    SqlConnection connection = new SqlConnection(SqlHelper.MSSQLConnectionString);
                    connection.Open();

                    using (SqlTransaction tran = connection.BeginTransaction())
                    {
                        try
                        {
                            foreach (JObject jObject in jArray)
                            {

                                if (result)
                                {
                                    SqlParameter[] sqlParameters = new SqlParameter[3];
                                    sqlParameters[0] = new SqlParameter("@SalesOrderDetailID", jObject["SalesOrderDetailID"].ToString());
                                    sqlParameters[1] = new SqlParameter("@Result", SqlDbType.Bit);
                                    sqlParameters[2] = new SqlParameter("@Msg", SqlDbType.NVarChar, 500);
                                    sqlParameters[1].Direction = sqlParameters[2].Direction = ParameterDirection.Output;
                                    SqlHelper.ExecuteNonQuery(tran, "P_APS_TOSalesPlan", sqlParameters);
                                    result = sqlParameters[1].Value.ToString().ToLower() == "true";
                                    msg = sqlParameters[2].Value.ToString();


                                }
                                else
                                {
                                    tran.Rollback();
                                    break;
                                }

                            }

                            if (result)
                            {
                                SqlHelper.ExecuteNonQuery(tran, CommandType.Text, @"UPDATE A
SET A.LineNum = B.R * 10
FROM APS_SalesPlan A
left join(
SELECT  ROW_NUMBER() OVER(PARTITION BY A.SalesOrderDetailID ORDER by A.SalesPlanID) as R
, a.SalesPlanID
FROM APS_SalesPlan A
 ) b ON A.SalesPlanID = B.SalesPlanID");


                                tran.Commit();
                                msg = "成功下达到销售计划" + jArray.Count + "笔记录";
                            }



                        }
                        catch (Exception ex)
                        {
                            result = false;
                            msg = ex.Message;
                            // tran.Rollback();
                            ApsLegacyJsonResult = base.FormResult(result, msg, null);

                        }
                        finally
                        {

                            connection.Close();
                        }
                    }


                }

            }
            catch (Exception ex)
            {
                result = false;
                msg = ex.Message;

            }
            ApsLegacyJsonResult = base.FormResult(result, msg, null);
            return ApsLegacyJsonResult;
        }


