        public ApsLegacyJsonResult CheckLogin(string loginOut)
        {

            bool result = false;
            string msg = "";
            if (loginOut == "1")
            {
                Session.Clear();
                Response.Cookies.Clear();
            }
            try
            {


                if (dev_Account != null)
                {
                    result = true;
                    msg = "您好！" + dev_Account.Name;
                }
                else
                {
                    msg = "当前用户未登录";
                }



            }
            catch (Exception ex)
            {
                result = false;
                msg = ex.Message;
            }
            ApsLegacyJsonResult json = new ApsLegacyJsonResult();
            json.MaxJsonLength = int.MaxValue;
            json.Data = new
            {
                msg,
                result,
                href = "/login/login",
