                ,
                password = dev_Account == null ? "" : dev_Account.Pwd,
                OrganizeID = dev_Account == null ? "" : dev_Account.OrganizeID.ToString()
            };
            return json;
        }

        /// <summary>
        /// 五金APP手工计划添加查询
        /// </summary>
        /// <returns></returns>

        public string SearchMaterialByLine()
        {
            bool result = true;
            string msg = "";
            DataTable dataTable = null;
            try
            {



                JObject jObject = JsonConvert.DeserializeObject(BodyJson) as JObject;

                if (jObject == null || jObject.Count == 0)
                {
                    msg = "未接受到数据，请确认是否为JSON格式";
                    result = false;

                }
                else
                {

                    string processID = "";
                    if (jObject.ContainsKey("ProcessID"))
                    {
                        processID = jObject["ProcessID"].ToString();
                    }
                    if (!string.IsNullOrEmpty(processID))

                    {
                        try
                        {

                            string where = "";
                            dataTable = SqlHelper.ExecuteDataTable("SELECT Remark1,ProcessID FROM APS_Process where ProcessID='" + processID + "'");
                            if (dataTable.Rows.Count > 0)
                            {
                                string Remark1 = dataTable.Rows[0]["Remark1"].ToString();
                                //if (processID == "P202105221136042" || processID == "P202105191650312" || processID == "P2112240005" || processID == "P2112240006" || processID == "P2112240007")
                                //{//串线,P2112240005
                                // //P2112240006
                                // //P2112240007
                                //    where = " AND a2.MaterialName like '%串线%'";
                                //}
                                //else if (processID == "P202105221136303" || processID == "P2021052212112867")
                                //{//填粉
                                //    where = " AND a2.MaterialName like '%直管%'";
                                //}
                                if (!string.IsNullOrEmpty(Remark1))
                                {
                                    where = " AND a2.MaterialName like '%" + Remark1 + "%'";
                                }
                                if (string.IsNullOrEmpty(where))
                                {
                                    dataTable = SqlHelper.ExecuteDataTable(string.Format(@" 
  select  a2. MaterialID,a2.MaterialName,CASE WHEN A3.ProcessGroupID IS NULL THEN 0 ELSE 1 END AS ProcessCount
  ,A4.ProcessGroupName,a2.Extend15
  from   APS_Material  a2
  LEFT JOIN APS_ProcessGroupMaterial A3 ON A2.MaterialID=A3.MaterialID
  LEFT JOIN APS_ProcessGroup A4 ON A3.ProcessGroupID=A4.ProcessGroupID
  where a2.MaterialType='成品' AND  A2.MaterialName LIKE '%{0}%' {1}", jObject["MaterialName"].ToString(), where));
                                }
                                else
                                {
                                    dataTable = SqlHelper.ExecuteDataTable(string.Format(@" 
  select  a. MaterialID,a.Remark1 as MaterialName,CASE WHEN A3.ProcessGroupID IS NULL THEN 0 ELSE 1 END AS ProcessCount
  ,A4.ProcessGroupName,a2.Extend15
  from APS_MaterialBOM a
  inner join APS_Material a2 on a.MaterialID=a2.MaterialID
INNER JOIN APS_Material B ON A.BOMMasterID=B.MaterialID
  LEFT JOIN APS_ProcessGroupMaterial A3 ON A.MaterialID=A3.MaterialID
  LEFT JOIN APS_ProcessGroup A4 ON A3.ProcessGroupID=A4.ProcessGroupID
  where a.IsScheduling=1
 AND (  b.MaterialName LIKE '%{0}%') {1}", jObject["MaterialName"].ToString(), where));
                                }
                                if (dataTable.Rows.Count == 0)
                                {
                                    dataTable = SqlHelper.ExecuteDataTable(string.Format(@" 
  select  a2. MaterialID,a2.MaterialName,CASE WHEN A3.ProcessGroupID IS NULL THEN 0 ELSE 1 END AS ProcessCount
  ,A4.ProcessGroupName,a2.Extend15
  from   APS_Material  a2
  LEFT JOIN APS_ProcessGroupMaterial A3 ON A2.MaterialID=A3.MaterialID
  LEFT JOIN APS_ProcessGroup A4 ON A3.ProcessGroupID=A4.ProcessGroupID
  where   A2.MaterialName LIKE '%{0}%' ", jObject["MaterialName"].ToString()));
                                }

                            }
                            else
                            {
                                result = false;
                                msg = "工序不存在";
                            }


                        }
                        catch (Exception ex)
                        {
                            result = false;
                            msg = ex.Message;
                            // tran.Rollback();


                        }
                    }
                    else
                    {
                        result = false;
                        msg = "未提供工序";
                    }




                }

            }
            catch (Exception ex)
            {
                result = false;
                msg = ex.Message;

            }
            return JsonConvert.SerializeObject(new
            {


                result//返回标记
                           ,
                msg//返回的信息
                ,
                data = dataTable

            });
            return "";

        }



        /// <summary>
        /// 订单暂停
        /// </summary>
        /// <returns></returns>
        public ApsLegacyJsonResult SureParse()
        {
            bool result = true;
            string msg = "操作成功";
            try
            {


                SaveData();
                if (base.isAllOK)
                {
                    if (AppInfo.PushType == "6")
                    {//ut

                        string subject = "APS系统日计划暂停提醒";
                        string bodyContent = @"

";
                        string ProcessPlanID = "0";
                        JArray jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;
                        if (jArray == null)
                        {
                            msg = "未接收到数据，请确认是否为JSON格式";
                            result = false;
                        }
                        else
                        {
                            foreach (JObject jObject in jArray)
                            {
                                ProcessPlanID += "," + jObject["ProcessPlanID"].ToString();
                            }

                            DataSet ds = SqlHelper.ExecuteDataset(string.Format(@"
SELECT  A.[Account]
        ,B.Email
		,B.Name
  FROM [dbo].[Dev_SendEmail] A
  INNER JOIN Dev_Account B ON A.Account=B.Account
  WHERE A.Status=1 AND A.Remark1='日计划提醒'
 

select OrderNo
,MaterialName
,Qty
 
,PlanQty
,OweQty
,LineName
,HasQty ProcessHasQty
,Spec
,Remark1
,ProcessStatusName
,ModifiedByName
  from V_APS_ProcessPlan
where ProcessPlanID in({0})
", ProcessPlanID));
                            List<string> lstAddress = new List<string>();
                            try
                            {
                                if (ds.Tables[0].Rows.Count > 0 && ds.Tables[1].Rows.Count > 0)
                                {
                                    string names = "";
                                    foreach (DataRow dataRow in ds.Tables[0].Rows)
                                    {
                                        lstAddress.Add(dataRow["Email"].ToString());
                                        names += dataRow["Name"].ToString() + "，";
                                    }
                                    bodyContent += @"
<html>
<head>
<style type =""text/css"">
     
         .table,
    tr,
    td {
                                border: 1px solid #9e9d9d;
        border-collapse: collapse;
                                    text-align: center;
                                    padding: 3px 10px 3px 10px;
                                    font-size: 12px;
                                    font-weight: normal;
                            
                            }

                        tr:first-child {
                                background: #666677;
            color: #fff;
        }
</style>
</head>
<body>

亲爱的" + names + @"APS系统温馨提示,以下工单在日计划中被暂停或开启，请留意：
    <table class=""table"" cellpadding=""0"" cellspacing=""0"">
  <tr style=""background: #666677; color: #fff;"">
            <td>订单号</td>
            <td>产品</td>
   <td>规格</td>
    <td>订单数</td>
  <td>欠数</td>
    <td>状态</td>
     <td>拉线</td>
   
  
    <td>暂停/开启原因</td> 
  <td>操作人</td>
        </tr>";
                                    foreach (DataRow dataRow in ds.Tables[1].Rows)
                                    {
                                        bodyContent += string.Format(@"

  <tr>
            <td>{0}</td>
            <td>{1}</td>
       <td>{2}</td>

    <td>{3:G0}</td> 
   <td>{4:G0}</td> 
       <td>{5}</td>    
       <td>{6}</td>     
 <td>{7}</td>
  <td>{8}</td>
 
        </tr>
 ", dataRow["OrderNo"]
                    , dataRow["MaterialName"], dataRow["Spec"], dataRow["Qty"]
                    , dataRow["OweQty"], dataRow["ProcessStatusName"], dataRow["LineName"]
                    , dataRow["Remark1"], dataRow["ModifiedByName"]
                    );
                                    }
                                    bodyContent += @"</table></html>";
                                    Email.SendMail(lstAddress, subject, bodyContent);


                                }
                                systemLog.SaveLog(SystemLog.SystemLogType.邮件发送日志, "日计划报工提醒邮件发送成功，共" + ds.Tables[0].Rows.Count + "调记录", null, null);
                            }
                            catch (Exception ex)
                            {
                                systemLog.SaveLog(SystemLog.SystemLogType.邮件发送日志, "邮件发送失败:" + ex.Message, null, null);
                            }

                        }

                    }
                }
            }
            catch (Exception ex)
            {
                msg = ex.Message;
                result = false;
            }
            return base.FormResult(result, msg, null);
        }

