        /// <summary>
        ///返回细小工序异常
        /// </summary>
        /// <returns></returns>
        public string ReturnAbnormalData()
        {
            bool result = true;
            string msg = "";
            string code = "";
            DataTable ds = null;
            JArray jArray = null;
            try
            {

                jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;
                if (jArray == null)
                {
                    msg = "未接受到数据，请确认是否为JSON格式";
                    result = false;
                }
                else
                {
                    string TinyProcessIDs = "'-1'";
                    //第一步，循环所有的对象，获取工序拿到对应的异常原因  将每一行数据放进表内
                    foreach (JObject jObject in jArray)
                    {

                        TinyProcessIDs += ",'" + jObject["TinyProcessID"].ToString() + "'";
                    }
                    // 获取当前数据含有细小工序的所有异常
                    DataTable LIST = SqlHelper.ExecuteDataTable(@"select *  from  V_APS_AbnormalTinyProcess where TinyProcessID IN(" + TinyProcessIDs + ") ");

                    if (LIST != null)
                    {

                        foreach (JObject jObject in jArray)
                        {
                            DataRow[] dataRows = LIST.Select("TinyProcessID= '" + jObject["TinyProcessID"].ToString() + "'");//是否是这个条件
                            JArray jArray1 = new JArray();//childres是数组
                            foreach (DataRow d in dataRows)
                            {//循环数据行
                                JObject j = new JObject();//定义json对象
                                foreach (DataColumn column in LIST.Columns)
                                {//给所有的属性赋值
                                    j.Add(column.ColumnName, d[column].ToString());
                                }
                                jArray1.Add(j);//插入数组
                            }
                            jObject.Add("childrens", jArray1);//插入childrens

                        }


                        msg = "读取成功";

                    }
                }

            }
            catch (Exception ex)
            {
                msg = ex.Message;
                result = false;
            }

            return JsonConvert.SerializeObject(new
            {
                data = jArray,
                result//返回标记
                       ,
                msg//返回的信息 }

            });
        }

