        /// <summary>
        /// 返回班次配置
        /// </summary>
        /// <returns></returns>
        public string GetWorkTime()
        {
            bool result = true;
            string msg = "";
            ApsLegacyJsonResult ApsLegacyJsonResult = new ApsLegacyJsonResult();
            DataSet ds = new DataSet();
            DataTable dt = new DataTable();
            DataTable dtParent = new DataTable();
            ///最终返回的数组
            List<Dictionary<string, object>> listOrg = new List<Dictionary<string, object>>();
            JObject jObject = JsonConvert.DeserializeObject(BodyJson) as JObject;
            if (jObject == null)
            {
                msg = "未接收到数据，请确认是否为JSON格式";
                result = false;
            }
            else
            {
                try
                {
                    if (jObject.ContainsKey("dicID") == true)
                    {
                        int dicID = int.Parse(jObject["dicID"].ToString());
                        MSSQLCore mSSQLCore = new MSSQLCore(dicID, jObject, "");
                        mSSQLCore.GetSql();
                        String WorkingTimesID = "";
                        if (jObject.ContainsKey("WorkingTimesID"))
                        {
                            WorkingTimesID = jObject["WorkingTimesID"].ToString();
                        }
                        dt = SqlHelper.ExecuteDataTable("select *,86 as dicID from APS_WorkingTimes ");
                        GetDataSource(dt, mSSQLCore);
                        dtParent = SqlHelper.ExecuteDataTable("select * ,86 as dicID from APS_WorkingTimes where ParentWorkingTimesID is null or ParentWorkingTimesID = '' or ParentWorkingTimesID = '0' ");
                        if (!string.IsNullOrEmpty(WorkingTimesID))
                        {
                            ds = SqlHelper.ExecuteDataset(SqlHelper.MSSQLConnectionString, CommandType.Text, mSSQLCore.SQL);
                            ds.Tables[0].Columns.Add("dicID", typeof(int));
                            foreach (DataRow dataRow in ds.Tables[0].Rows)
                            {
                                dataRow["dicID"] = 86;
                            }
                        }
                        else
                        {
                            ds.Tables.Add(dtParent.Copy());
                        }
                        GetDataSource(ds.Tables[0], mSSQLCore);
                        try
                        {
                            Entities.Configuration.ValidateOnSaveEnabled = false;
                            {
                                try
                                {
                                    //循环顶级组织
                                    foreach (DataRow dr in ds.Tables[0].Rows)
                                    {
                                        Dictionary<string, object> keyValuePairs = new Dictionary<string, object>();
                                        //加入所有的列
                                        foreach (DataColumn dataColumn in dt.Columns)
                                        {
                                            keyValuePairs.Add(dataColumn.ColumnName, dr[dataColumn.ColumnName]);
                                        }

                                        //循环一行之后后，调用递归方法
                                        GetChildrenData(dt, (dr["WorkingTimesID"].ToString()), keyValuePairs, "ParentWorkingTimesID", "WorkingTimesID");
                                        //加入待返回的集合
                                        listOrg.Add(keyValuePairs);
                                    }
                                    msg = "读取菜单成功";
                                }
                                catch (Exception ex)
                                {
                                    result = false;
                                    msg = ex.Message;
                                    // tran.Rollback();
                                    ApsLegacyJsonResult = base.FormResult(result, msg, null);

                                }
                                finally
                                {

                                }
                            }


                        }
                        catch (Exception ex)
                        {
                            result = false;
                            msg = ex.Message;
                            ApsLegacyJsonResult = base.FormResult(result, msg, null);
                        }
                    }
                    else
                    {
                        msg = "没有接收到dicID";
                        result = false;
                    }
                }
                catch (Exception ex)
                {
                    msg = ex.Message;
                    result = false;
                }
            }
            string s = JsonConvert.SerializeObject(new
            {
                data = listOrg,
                count = listOrg.LongCount(),
                result//返回标记
                                     ,
                msg//返回的信息

            }); ;
            return s;
        }
