        public string GetOrderBomData()
        {
            bool result = true;
            string msg = "";
            ApsLegacyJsonResult ApsLegacyJsonResult = new ApsLegacyJsonResult();
            DataSet ds = new DataSet();
            //  DataTable dt = new DataTable();

            ///最终返回的数组
