                result = false;
            }
            else
            {
                try
                {
                    if (jObject.ContainsKey("dicID") == true)
                    {
                        int dicID = int.Parse(jObject["dicID"].ToString());
                        MSSQLCore mSSQLCore = new MSSQLCore(dicID, jObject, "");
                        mSSQLCore.Where = " and ParentID=0";
                        mSSQLCore.GetSql();
                        long OrderID = 0;
                        if (jObject.ContainsKey("OrderID"))
                        {
                            long.TryParse(jObject["OrderID"].ToString(), out OrderID);
                        }


                        if (OrderID > 0)
                        {
                            ds = SqlHelper.ExecuteDataset(SqlHelper.MSSQLConnectionString, CommandType.Text, mSSQLCore.SQL);
                            ds.Tables[0].Columns.Add("dicID", typeof(int));

                            V_APS_Order v_APS_Order = Entities.V_APS_Order.Where(m => m.OrderID == OrderID).FirstOrDefault();
                            if (v_APS_Order != null)
