                                DataRow dataRow = ds.Tables[0].NewRow();
                                foreach (var pro in v_APS_Order.GetType().GetProperties())
                                {
                                    if (ds.Tables[0].Columns.Contains(pro.Name))
                                    {
                                        try
                                        {
                                            dataRow[pro.Name] = pro.GetValue(v_APS_Order);
                                        }
                                        catch { }

                                    }
                                }
                                dataRow["OrderBOMID"] = 0;
                                dataRow["ParentID"] = -1;
                                ds.Tables[0].Rows.Add(dataRow);
                            }
                            else
                            {
                                msg = "工单不存在";
                                result = false;
                            }
                            foreach (DataRow dataRow in ds.Tables[0].Rows)
                            {
                                dataRow["dicID"] = 5021;
                            }
                        }
                        else
                        {

                            msg = "当前查询的条件没有工单";
                            result = false;
                        }
                        GetDataSource(ds.Tables[0], mSSQLCore);
                        try
                        {
                            Entities.Configuration.ValidateOnSaveEnabled = false;
                            {
                                try
                                {
                                    //循环顶级组织
                                    foreach (DataRow dr in ds.Tables[0].Select(" ParentID=-1"))
                                    {
                                        Dictionary<string, object> keyValuePairs = new Dictionary<string, object>();
                                        //加入所有的列
                                        foreach (DataColumn dataColumn in ds.Tables[0].Columns)
                                        {
                                            keyValuePairs.Add(dataColumn.ColumnName, dr[dataColumn.ColumnName]);
                                        }

                                        //循环一行之后后，调用递归方法
                                        GetOrgChildrenData(ds.Tables[0], (int.Parse(dr["OrderBOMID"].ToString())), keyValuePairs, "ParentID", "OrderBOMID");
                                        //加入待返回的集合
                                        listBom.Add(keyValuePairs);
                                    }
                                    msg = "数据读取成功";
                                }
                                catch (Exception ex)
                                {
                                    result = false;
                                    msg = ex.Message;
                                    // tran.Rollback();
                                    ApsLegacyJsonResult = base.FormResult(result, msg, null);

                                }
                                finally
                                {

                                }
                            }


                        }
                        catch (Exception ex)
                        {
                            result = false;
                            msg = ex.Message;
                            ApsLegacyJsonResult = base.FormResult(result, msg, null);
                        }
                    }
                    else
                    {
                        msg = "没有接收到dicID";
                        result = false;
                    }
                }
                catch (Exception ex)
                {
                    msg = ex.Message;
                    result = false;
                }
            }
            string s = JsonConvert.SerializeObject(new
            {
                data = listBom,
                count = listBom.LongCount(),
                result//返回标记
                                     ,
                msg//返回的信息

            }); ;
            return s;
        }
