        /// <summary>
        /// 递归获取组织
        /// </summary>
        /// <param name="dt">数据表</param>
        /// <param name="parentID">上级id</param>
        /// <param name="listOrg">当前的集合</param>
        private static void GetListOrgs(DataTable dt, int parentID, Dictionary<string, object> parentDictionary)
        {
            //当前上级的子集
            List<Dictionary<string, object>> list = new List<Dictionary<string, object>>();
            //循环当前传来的上级组织ID
            foreach (DataRow dr in dt.Select("RealParentID=" + parentID))
            {
                //当前行的字典，前端得到的是对象
                Dictionary<string, object> keyValuePairs = new Dictionary<string, object>();
                //加入所有的列
                foreach (DataColumn dataColumn in dt.Columns)
                {
                    keyValuePairs.Add(dataColumn.ColumnName, dr[dataColumn.ColumnName]);
                }

                list.Add(keyValuePairs);
                //循环一行之后后,重复调用自己
                GetListOrgs(dt, int.Parse(dr["OrganizeID"].ToString()), keyValuePairs);
            }
            //加入children
            parentDictionary.Add("children", list);
        }
