        /// <param name="field">上级字段名</param>
        /// <param name="ID">自身id</param>
        private static void GetChildrenData(DataTable dt, String parentCode, Dictionary<string, object> parentDictionary, String field, String ID)
        {
            //当前上级的子集
            List<Dictionary<string, object>> list = new List<Dictionary<string, object>>();
            //循环当前传来的上级组织ID
            foreach (DataRow dr in dt.Select("" + field + "='" + parentCode + "'"))
            {
                //当前行的字典，前端得到的是对象
                Dictionary<string, object> keyValuePairs = new Dictionary<string, object>();
                //加入所有的列
                foreach (DataColumn dataColumn in dt.Columns)
                {
                    keyValuePairs.Add(dataColumn.ColumnName, dr[dataColumn.ColumnName]);
                }

                list.Add(keyValuePairs);
                //循环一行之后后,重复调用自己
                GetChildrenData(dt, (dr[ID].ToString()), keyValuePairs, field, ID);
            }
            //加入children
            parentDictionary.Add("children", list);
        }
        #endregion


