        /// <summary>
        /// 通过零碎汇总 总包装数 今日工序计划数，昨日工序计划数
        /// </summary>
        /// <returns></returns>
        public string wjBoardData_1(string MFGOrganizeID)
        {
            bool result = false;
            string msg = "";
            string where = "";
            string where2 = "";
            string where3 = "";
            DataSet dataSet = null;
            if (!string.IsNullOrEmpty(MFGOrganizeID))
            {
                where = " AND MFGOrganizeID = " + MFGOrganizeID + " ";
                where2 = " AND Extend16 = " + MFGOrganizeID + " ";
                where3 = " AND OrganizeIDs like '%$" + MFGOrganizeID + "$%' ";
            }
            //分厂
            try
            {
                dataSet = SqlHelper.ExecuteDataset(SqlHelper.MSSQLConnectionString, CommandType.Text, string.Format(@"
SELECT TOP 7 CustomerName as name ,count(1) as value FROM V_APS_SalesOrderDetail group by CustomerName order by count(1) desc
select  isNull(sum(PlanQty),0)  as PlanQty,isNull(sum(ProducedQty),0) as ProducedQty ,isNull(sum(ConfirmQty),0) as ConfirmQty from V_APS_SalesPlanProcessMaterialDayHistory where PlanDay = cast( GETDATE() as date) {0}
select isNull(sum(PlanQty),0) as PlanQty,isNull(sum(ConfirmQty),0) as ConfirmQty,Cast(Isnull(Sum(ConfirmQty), 0) / Isnull(Sum(PlanQty), 1) * 100 AS DECIMAL(18, 2)) AS PlanQtyP from  V_APS_SalesPlanProcessMaterialDayTotal where FORMAT(PlanDay,'MM') = month(GETDATE()) {0}
select  ProcessName as name,isNull(sum(PlanQty),0)  as PlanQty, isNull(sum(ConfirmQty),0) as value from V_APS_SalesPlanProcessMaterialDayHistory where PlanDay = cast( GETDATE() as date) {0} group by ProcessName
select  ProcessName as name,isNull(sum(PlanQty),0)  as PlanQty, isNull(sum(ConfirmQty),0) as value from V_APS_SalesPlanProcessMaterialDayHistory where PlanDay = cast( GETDATE()-1 as date) {0} group by ProcessName

select count(1) as value,Extend9 as name from v_APS_Material where Extend9 is not null and Extend9 != '' {1} group by Extend9
select isNull(sum(StockQty),0) as value,Extend9 as name from V_WMS_Stock where Extend9 is not null and Extend9 != '' {1}  group by  Extend9

select LineName, isNull(sum(PlanQty),0)  as PlanQty,isNull(sum(ProducedQty),0) as ProducedQty,isNull(sum(ConfirmQty),0) as ConfirmQty ,cast(isNull(sum(ConfirmQty),0)/isNull(sum(PlanQty),0)*100 as decimal(18,2) )as PlanQtyP from V_APS_SalesPlanProcessMaterialDayHistory where PlanDay = cast( GETDATE()-1 as date) and LineName is not null and LineName != '' {0} GROUP BY LineName order by ConfirmQty desc

--今日报工审批
SELECT LineName,
       Count(1)                                              AS COUNT,
       Sum(CASE
             WHEN ApprovalStatus = '已完成' THEN 1
             ELSE 0
           END)                                              AS OnTimeNum,
       Cast(( Sum(CASE
                    WHEN ApprovalStatus = '已完成' THEN 1.0
                    ELSE 0.0
                  END) / Count(1) * 100 ) AS DECIMAL(18, 2)) AS Rate
		,Approvals
FROM   V_APS_MaterialReportDetail
WHERE  ProducedDate = Cast(Getdate() AS DATE)
       AND LineName IS NOT NULL
       AND LineName != ''
GROUP  BY LineName,Approvals
ORDER  BY Rate DESC 

select FORMAT(StartDate,'MM-dd') as StartDate,SUM(P1)/COUNT(1)*100 AS P1
FROM(
SELECT StartDate,ParentID,MIN(FormQty)/PlanQty as P1
FROM APS_OrderPlanMaterialForm
WHERE StartDate>=CAST(GETDATE() AS DATE) and StartDate<GETDATE()+7
GROUP BY StartDate,ParentID,PlanQty
) A GROUP BY FORMAT(StartDate,'MM-dd')


", where, where2, where3));

                result = true;
            }
            catch (Exception ex)
            {
                msg = ex.Message;
                result = false;
            }
            return JsonConvert.SerializeObject(new
            {

                data = dataSet,//数据
                result//返回标记
                 ,
                msg//返回的信息

            });
        }

