        public ApsLegacyJsonResult CheckYooseSSN()
        {
            bool result = false;
            string msg = "";
            ApsLegacyJsonResult ApsLegacyJsonResult = new ApsLegacyJsonResult();

            try
            {
                JObject jArray = JsonConvert.DeserializeObject(BodyJson) as JObject;
                if (jArray == null || jArray.Count == 0)
                {
                    msg = "未接受到数据，请确认是否为JSON格式";
                    result = false;
                }
                else
                {



                    string SSN = jArray["SSN"].ToString();


                    DateTime? EndDate = null;
                    int EffectiveDay = 7;

                    DataTable dtDetail1 = SqlHelper.ExecuteDataTable(string.Format(
                    @"SELECT EndDate,SSN FROM MES_SSN(NOLOCK) WHERE SSN = '{0}' AND (EndDate>=getdate() OR EndDate IS NULL)", SSN));


                    //数据处理
                    DataTable dtDetail = SqlHelper.ExecuteDataTable(string.Format(
                    @"SELECT EndDate,SSN,EffectiveDay FROM MES_SSN(NOLOCK) WHERE SSN = '{0}'", SSN));
                    DataRow[] dataRows = dtDetail.Select("SSN='" + SSN + "'");

                    if (dataRows.Length > 0)
                    {
                        if (dataRows[0]["EndDate"].ToString() != null)
                        {
                            DateTime EndDate1;
                            DateTime.TryParse(dataRows[0]["EndDate"].ToString(), out EndDate1);
                            EndDate = EndDate1;
                            EffectiveDay = (int)dataRows[0]["EffectiveDay"];
                        }

                        if (EffectiveDay == null)
                        {
                            EffectiveDay = 0;
                        }
                    }
                    if (dtDetail.Rows.Count > 0)
                    {
                        SqlHelper.ExecuteDataTable(string.Format(
                @"insert into MES_SSNScan (RequestDate,Status,SSN,Address) select getdate(),1,'{0}','{1}';
                ", SSN, Request.UserHostAddress));
                        DateTime today = DateTime.Now;
                        if (EndDate.HasValue)
                        {
                            SqlHelper.ExecuteDataTable(string.Format(
                @"update MES_SSN set EndDate=(getdate()+{1}),startdate=getdate(),SSNCount=isnull(SSNCount,0)+1 where SSN = '{0}'", SSN, EffectiveDay));
                        }
                        else
                        {
                            SqlHelper.ExecuteDataTable(string.Format(
                            @"update MES_SSN set SSNCount=isnull(SSNCount,0)+1 where SSN = '{0}'", SSN));

                        }
                    }

                    //判断跳转页面
                    if (dtDetail1.Rows.Count == null)
                    {
                        result = false;
                    }
                    else if (dtDetail1.Rows.Count >= 1)
                    {
                        result = true;

                    }



                }

            }
            catch (Exception ex)
            {
                result = false;
                msg = "数据操作失败,错误信息:" + ex.Message;
            }


            ApsLegacyJsonResult = base.FormResult(result, msg, null);
            return ApsLegacyJsonResult;
        }


