        /// <summary>
        /// 周生产计划循环行的信息
        /// </summary>
        /// <param name="dataRow"></param>
        public void setDetail7915(DataRow dataRow)
        {

            int planWeeks = 8;
            if (jObject["PlanWeeks"] != null && !string.IsNullOrWhiteSpace(jObject["PlanWeeks"].ToString()))
            {
                int.TryParse(jObject["PlanWeeks"].ToString(), out planWeeks);
            }

            for (int i = 0; i < planWeeks; i++)
            {
                DateTime dateTime = DateTime.Now.AddDays(i * 7);
                CultureInfo culture = CultureInfo.CurrentCulture;
                System.Globalization.Calendar calendar = culture.Calendar;
                int yearWeek = calendar.GetWeekOfYear(dateTime, CalendarWeekRule.FirstDay, DayOfWeek.Sunday);
                DataRow[] dataRows = DtDetail.Select("ProcessPlanID=" + dataRow["ProcessPlanID"] + " and YearWeek=" + yearWeek.ToString() + "");
                if (dataRows.Length > 0)
                {
                    dataRow["WK" + yearWeek.ToString()] = dataRows[0]["PlanQty"];
                }
            }
        }
