        public void setDetail11182(DataRow dataRow)
        {
            DateTime startDate = DateTime.Now;
            Dictionary<string, string> bColors = new Dictionary<string, string>();//背景颜色
            bool q1 = dataRow.Table.Columns.Contains("Q1");
            for (int i = 0; i < 30; i++)
            {
                DateTime dateTime = DateTime.Now.AddDays(i);
                string yearDay = string.Format("{0:yyyy-MM-dd}", dateTime);
                DataRow[] dataRows = DtDetail.Select("Code='" + dataRow["Code"] + "' AND Extend12='" + dataRow["Extend12"] + "' AND DemandDate='" + yearDay + "'");
                if (dataRows.Length > 0)
                {
                    yearDay = string.Format("{0:MM-dd}", dateTime);
                    int sumOweQty = Convert.ToInt32(dataRows[0]["SumOweQtyForDay"]);
                    if (q1)
                    {//包含Q1，其实也包含了OweQty3


                        int q1Value = Convert.ToInt32(dataRows[0]["Q1"]);
                        int oweQty3 = Convert.ToInt32(dataRows[0]["OweQty3"]);
                        //if (q1Value > 0)
                        //{
                        //    bColors.Add(yearDay, "#59F3BB"); // 蓝色
                        //}
                        if (q1Value < 0)
                        {
                            bColors.Add(yearDay, "#FB6C97"); // 红色
                        }
                        else if (q1Value * 0.5 >= Math.Abs(sumOweQty))
                        {
                            bColors.Add(yearDay, "#F5E61A"); // 黄色
                        }
                        //if (oweQty3 < 0)
                        //{
                        //    bColors.Add(yearDay, "#F5E61A"); // 黄色
                        //}

                        dataRow[yearDay] = string.Format("{0}({1})", sumOweQty, q1Value);
                    }
                    else
                    {
                        dataRow[yearDay] = string.Format("{0}", sumOweQty);
                    }
                }
            }
            dataRow["BColors"] = bColors;
        }
