            sqlParameters[1] = new SqlParameter("@Result", SqlDbType.Bit);//结果
            sqlParameters[2] = new SqlParameter("@Msg", SqlDbType.NVarChar, 500);//信息
            sqlParameters[1].Direction = sqlParameters[2].Direction = ParameterDirection.Output;
            SqlHelper.ExecuteNonQuery(SqlHelper.MSSQLConnectionString, "P_aps_toprocessplanv1", sqlParameters);
            result = sqlParameters[1].Value.ToString().ToLower() == "true";
