            //}
            ApsLegacyJsonResult = base.FormResult(result, msg, null);
            return ApsLegacyJsonResult;
        }
        /// <summary>
        /// 瑞能拆单
        /// </summary>
        /// <returns></returns>
        public ApsLegacyJsonResult InsertOrderWithSpiltQtysRN()
        {
            bool result = true;
            string msg = "";
            ApsLegacyJsonResult ApsLegacyJsonResult = new ApsLegacyJsonResult();
            try
            {
                JArray jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;
                if (jArray == null || jArray.Count == 0)
                {
                    msg = "未接受到数据，请确认是否为JSON格式";
                    result = false;
                }
                else
                {
                    int orderID = 0;

                    decimal totalSplitQty = 0;//总拆单数
                    decimal splitQty = 0;//单个拆单数
                    string dataSource = "拆单";
                    string tempMsg = "拆单成功！结果为原单数量修改为:";
                    //string spiltQtys = "";//拆出来的单的数量列表，排除原单，原单不需要执行插入
                    string sql = "";//拼接sql

                    foreach (JObject jObject in jArray)
                    {
                        if (!string.IsNullOrEmpty(jObject["OrderID"].ToString()) && orderID == 0)
                        {
                            int.TryParse(jObject["OrderID"].ToString(), out orderID);
                        }
                    }

                    if (orderID == 0)
                    {
                        msg = "未找到有效的工单";
                        result = false;
                    }

                    foreach (JObject jObject in jArray)
                    {
                        if (!string.IsNullOrEmpty(jObject["SplitQty"].ToString()))//拆单数量不为空
                        {
                            splitQty = 0;
                            //订单ID不为空，说明是旧的单，只需要进行计算拆单数
                            if (!string.IsNullOrEmpty(jObject["OrderID"].ToString()))
                            {
                                //spiltQtys += jObject["SplitQty"].ToString() + ",";

                                decimal.TryParse(jObject["SplitQty"].ToString(), out splitQty);
                                if (splitQty < 0)
                                {

                                    msg = "数量不能为负数";
                                    result = false;
                                }
                                totalSplitQty += splitQty;
                                tempMsg += jObject["SplitQty"].ToString() + "。";
                                sql += string.Format(@"UPDATE APS_Order SET    SplitQty = {0} WHERE  OrderID = {1};", splitQty, orderID);
                            }
                            //订单ID为空，说明是新的单，需要进行插入
                            else
                            {

                                decimal.TryParse(jObject["SplitQty"].ToString(), out splitQty);
                                if (splitQty < 0)
                                {

                                    msg = "数量不能为负数";
                                    result = false;
                                }

                                totalSplitQty += splitQty;
                                tempMsg += "新单数量：" + jObject["SplitQty"].ToString() + ";";
                                sql += string.Format(@"INSERT INTO [dbo].[APS_Order] (
                            [MFGOrganizeID],[OrderNo],[OrderDate],[Qty],[Price],[Currency],[ExchangeRate],[SaleTo],[DeliveryDate]
                             ,[SalesMan],[MaterialID],[OwnOrganizeID],[SystemID],[CustomerID],[ProducedQty],[ProductionStatus],[CompletionDate]
                             ,[StockOutQty],[Extend1],[Extend2],[Extend3],[Extend4],[Extend5],[Extend6],[Extend7],[Extend8],[Extend9],[Extend10]
                             ,[Extend11],[Extend12],[Extend13],[Extend14],[Extend15],[Extend16],[Extend17],[Extend18],[Extend19],[Extend20]
                             ,[Extend21],[CreatedBy],[CreatedByName],[ModifiedBy],[ModifiedByName],[CreatedOn],[ModifyedOn],[WorkFlowInstanceID]
                             ,[Status],[Remark1],[Remark2],[Describe1],[SourceOrderNo],[SourceOrderLineNo],[ERPStartDate],[ERPEndDate],[WorkOrderTypeID]
                             ,[WGT],[PickingStatus],[ParentOrderID],[CompletionQty],[ControlID],[FeedingQty],[ERPID],[TotalScheduingQty],[NoSehcduingQty]
                             ,[OweProducedQty],[CompletionStatus],[Volume],[UnPackagedQty],[PackagedQty],[ShipmentDay],[ActualDay],[ContainerQty]
                             ,[GroupCabinet],[SalesOrderDetailID],[ProcessGroupID],[FormRate],[Q1],[Q2],[Q3],[Q4],[Q5],[Q6],[Q7],[Q8],[Q9]
                             ,[Q10],[NoWorkHours],[NoSchedulingWeek],[Extend22],[Extend23],[LineNum],[QualifiedQty],[FormRate1],[FormRate2],[FormRate3]
                             ,[FormRate4],[FormRate5],[FormRate6],[D1],[D2],[D3],[D0],[D4],[D5],[D6],[FormRateBColor],[DefaultLineID]
                             ,[SplitQty],[DataSource],[SourceOrderID]
                        ) 
                        SELECT 
                            [MFGOrganizeID],[OrderNo],[OrderDate],[Qty],[Price],[Currency],[ExchangeRate],[SaleTo],[DeliveryDate]
                             ,[SalesMan],[MaterialID],[OwnOrganizeID],[SystemID],[CustomerID],[ProducedQty],[ProductionStatus],[CompletionDate]
                             ,[StockOutQty],[Extend1],[Extend2],[Extend3],[Extend4],[Extend5],[Extend6],[Extend7],[Extend8],[Extend9],[Extend10]
                             ,[Extend11],[Extend12],[Extend13],[Extend14],[Extend15],[Extend16],[Extend17],[Extend18],[Extend19],[Extend20]
                             ,[Extend21],'{4}', '{5}',[ModifiedBy],[ModifiedByName],[CreatedOn],[ModifyedOn],[WorkFlowInstanceID]
                             ,[Status],[Remark1],[Remark2],[Describe1],[SourceOrderNo],[SourceOrderLineNo],[ERPStartDate],[ERPEndDate],[WorkOrderTypeID]
                             ,[WGT],[PickingStatus],[ParentOrderID],[CompletionQty],[ControlID],[FeedingQty],[ERPID],[TotalScheduingQty],[NoSehcduingQty]
                             ,[OweProducedQty],[CompletionStatus],[Volume],[UnPackagedQty],[PackagedQty],[ShipmentDay],[ActualDay],[ContainerQty]
                             ,[GroupCabinet],[SalesOrderDetailID],[ProcessGroupID],[FormRate],[Q1],[Q2],[Q3],[Q4],[Q5],[Q6],[Q7],[Q8],[Q9]
                             ,[Q10],[NoWorkHours],[NoSchedulingWeek],[Extend22],[Extend23],[LineNum],[QualifiedQty],[FormRate1],[FormRate2],[FormRate3]
                             ,[FormRate4],[FormRate5],[FormRate6],[D1],[D2],[D3],[D0],[D4],[D5],[D6],[FormRateBColor],[DefaultLineID]
                             ,{0},'{1}',{2}
                        FROM APS_Order
                        WHERE OrderID = {3};", splitQty, dataSource, orderID, orderID, dev_Account.Account, dev_Account.Name);
                            }
                        }
                    }

                    // 移除最后一个逗号
                    //if (spiltQtys.EndsWith(","))
                    //{
                    //    spiltQtys = spiltQtys.TrimEnd(',');
                    //}

                    // 查找数据库中的 OrderID 对应的 SplitQty
                    DataTable dtDetail = SqlHelper.ExecuteDataTable(string.Format(
                    @"SELECT SplitQty FROM APS_Order(NOLOCK) WHERE OrderID = {0}", orderID));

                    decimal SplitQty = 0;

                    if (dtDetail.Rows.Count > 0)
                    {
                        decimal.TryParse(dtDetail.Rows[0]["SplitQty"].ToString(), out SplitQty);
                    }

                    // 比较 reSplitQty 和 totalSpiltQty
                    if (SplitQty != totalSplitQty)
                    {
                        msg = "可拆分数与拆分数量总和不一致,可拆分数量为：" + SplitQty;
                        result = false;
                    }
                    else
                    {
                        if (result)
                        {


                            // 定义数据库连接
                            SqlConnection connection = new SqlConnection(SqlHelper.MSSQLConnectionString);
                            connection.Open(); // 打开数据库
                                               // 定义事务
                            using (SqlTransaction tran = connection.BeginTransaction())
                            {
                                try
                                {
                                    SqlHelper.ExecuteNonQuery(tran, CommandType.Text, sql);
                                    tran.Commit();
                                }
                                catch (Exception ex)
                                {
                                    result = false;

                                    msg = ex.Message;
                                    tempMsg = tempMsg + '\n' + msg;
                                    // 代码异常，回滚事务
                                    tran.Rollback();
                                }
                                finally
                                {
                                    // 不管成功或失败，都要关闭数据库连接
                                    connection.Close();
                                }
                            }
                        }



                        msg = tempMsg;

                    }
                }
            }
            catch (Exception ex)
            {
                result = false;
                msg = "数据操作失败,错误信息:" + ex.Message;
            }

            ApsLegacyJsonResult = base.FormResult(result, msg, null);
            return ApsLegacyJsonResult;
        }



