        /// <summary>
        /// 保存SMT月计划
        /// </summary>
        /// <returns></returns>
        public string SaveData10130()
        {//
            bool result = false;
            string msg = "";

            try
            {

                jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;
                if (jArray == null)
                {
                    allMsg = "未接收到数据，请确认是否为JSON格式";
                    result = false;

                }
                else if (dev_Account == null)
                {
                    allMsg = "当前登录信息已经丢失，请刷新页面重新登录";
                    result = false;
                }

                else
                {
                    SaveData();
                    StringBuilder stringBuilder1 = new StringBuilder("DECLARE @COUNT INT;SET @COUNT=0;DECLARE @PlanMonthID BIGINT;");

                    DataTable dataTable = SqlHelper.ExecuteDataTable(@"SELECT ElectronicMainPlanID,PlanMonthID,PlanQty,YearMonth
FROM [APS_ElectronicMainPlanMonthForSMT]
where YearMonth>=FORMAT(getdate(),'yyyyMM')
 ");
                    int month = DateTime.Now.Month;
                    foreach (JObject obj in jArray)
                    {
                        for (int i = 0; i < 7; i++)
                        {
                            if (string.IsNullOrEmpty(obj["ElectronicMainPlanID"].ToString()))
                            {
                                continue;
                            }
                            DateTime dateTime = DateTime.Now.AddMonths(i);
                            string yearMonth = string.Format("{0:yyyyMM}", dateTime);
                            string planday = obj[yearMonth + "0"].ToString();
                            if (planday.ToString().IndexOf("/OADate(") == 0)
                            {
                                planday = planday.ToString().Replace("/OADate(", "").Replace(")/", "");
                                planday = System.DateTime.FromOADate(int.Parse(planday.ToString())).ToString("yyyy-MM-dd HH:mm:ss");
                            }
                            else
                            {

                                if (!string.IsNullOrEmpty(planday.ToString()))
                                {
                                    planday = planday.ToString().Replace("　", "");
                                }
                                if (StringHelper.IsNumber(planday.ToString()))
                                {
                                    planday = DateTime.Parse("1900-01-01").AddDays(int.Parse(planday)).AddDays(-2).ToString();
                                }
                            }
                            string lineID = obj[yearMonth + "1"].ToString();
                            string planqty = obj[yearMonth].ToString();
                            if (!string.IsNullOrEmpty(planqty))
                            {
                                stringBuilder1.Append(string.Format(@" SET @PlanMonthID = 0
                                SELECT @PlanMonthID=PlanMonthID FROM [APS_ElectronicMainPlanMonthForSMT](nolock) WHERE [ElectronicMainPlanID]='{7}'
                                AND YEARMONTH='{3}'
                                IF ISNULL(@PlanMonthID,0)=0
                                BEGIN
                                INSERT INTO [dbo].[APS_ElectronicMainPlanMonthForSMT]
                                           ([ElectronicMainPlanID]
                                           ,[SalesOrderDetailID]
                                           ,[MaterialID]
                                           ,[PlanQty]
                                           ,[PlanDay]
                                           ,[YearMonth]
                                           ,[Status]
                                           ,[CreatedBy]
                                           ,[CreatedByName]
                                           ,[ModifiedBy]
                                           ,[ModifiedByName]
                                           ,[CreatedOn]
                                           ,[ModifyedOn]
                                           ,[LineID]
                                 )
    
	                                SELECT A.ElectronicMainPlanID,A.[SalesOrderDetailID]
	                                ,A.MATERIALID,{1},{2},'{3}',1,'{4}','{5}','{4}','{5}',getdate(),getdate(),{6}
	                                FROM [dbo].[APS_ElectronicMainPlanForSMT] A
	                                WHERE [ElectronicMainPlanID]={0}
                                END
                                ELSE
                                BEGIN
	                                UPDATE [APS_ElectronicMainPlanMonthForSMT]
	                                SET [PlanQty]={1},[PlanDay]={2},[ModifyedOn]=GETDATE(),[ModifiedBy]='{4}',[ModifiedByName]='{5}',lineid={6}
	                                WHERE PlanMonthID=@PlanMonthID
                                END
                       ", obj["ElectronicMainPlanID"], string.IsNullOrEmpty(planqty) ? "null" : planqty
                         , string.IsNullOrEmpty(planday) ? "null" : "'" + planday + "'", yearMonth, dev_Account.Account, dev_Account.Name, string.IsNullOrEmpty(lineID) ? "null" : lineID, obj["ElectronicMainPlanID"]));

                            }
                            else
                            {
                                if (dataTable.Select("ElectronicMainPlanID=" + obj["ElectronicMainPlanID"] + " AND Yearmonth='" + yearMonth + "'").Length > 0)
                                {
                                    stringBuilder1.Append(string.Format(@"
	                                UPDATE [APS_ElectronicMainPlanMonthForSMT]
	                                SET [PlanQty]={1},[PlanDay]={2},[ModifyedOn]=GETDATE(),[ModifiedBy]='{4}',[ModifiedByName]='{5}',lineid={6}
	                                WHERE [ElectronicMainPlanID]='{7}' AND YEARMONTH='{3}'
                       ", obj["ElectronicMainPlanID"], string.IsNullOrEmpty(planqty) ? "null" : planqty
                     , string.IsNullOrEmpty(planday) ? "null" : "'" + planday + "'", yearMonth, dev_Account.Account, dev_Account.Name, string.IsNullOrEmpty(lineID) ? "null" : lineID, obj["ElectronicMainPlanID"]));
                                }
                            }
                        }
                    }

                    SqlHelper.ExecuteNonQuery(SqlHelper.MSSQLConnectionString, CommandType.Text, stringBuilder1.ToString());


                    result = true;
                    allMsg = "保存成功";

