        public void SetDt15210(ref DataTable dt)
        {



            //  dt.Columns.Add(new DataColumn("Lines", typeof(List<object>)));

            for (int i = 0; i < 10; i++)
            {
                DateTime dateTime = DateTime.Now.AddMonths(i);
                string label = "" + dateTime.Month + "月需求";
                string prop = string.Format("{0:yyyyMM}月需求", dateTime);
                dt.Columns.Add(prop, typeof(decimal));
                ElementColumn[0].Add(new ElementTableOuput() { label = label, prop = prop, width = "80", isEdit = false, ControlType = "textbox", visible = true }); ;
                //求和
                mSSQLCore.Dev_DictionaryFields.Add(new Dev_DictionaryField() { FooterType = "SUM", ParameterName = prop, DataType = "decimal", IsVisible = true });
                label = "" + dateTime.Month + "月排产";
                prop = string.Format("{0:yyyyMM}月排产", dateTime);
                dt.Columns.Add(prop, typeof(decimal));
                ElementColumn[0].Add(new ElementTableOuput() { label = label, prop = prop, width = "80", isEdit = false, ControlType = "textbox", visible = true });
                //求和
                mSSQLCore.Dev_DictionaryFields.Add(new Dev_DictionaryField() { FooterType = "SUM", ParameterName = prop, DataType = "decimal", IsVisible = true });
            }

            dt.Columns.Add("BColors", typeof(Dictionary<string, string>));
            DtDetail = SqlHelper.ExecuteDataTable(string.Format(@"
                SELECT FORMAT(RequestDate,'yyyyMM') AS YearMonth,SUM(QTY) as Qty,PONO as SalesOrderNo,Code
                FROM V_APS_BusinessOrderDetail
                  WHERE   Format(RequestDate, 'yyyyMM') >= Format(Getdate(), 'yyyyMM')
                           and IsPoDetailFinish=0
                GROUP BY FORMAT(RequestDate,'yyyyMM'),PONO,Code
                ", id));
            DtDetail1 = SqlHelper.ExecuteDataTable(string.Format(@"
             select * from [dbo].[V_APS_MOPlanToTrays]
