        /// <summary>
        /// 瑞能周计划 循环行
        /// </summary>
        /// <param name="dataRow"></param>
        public void setDetail15210(DataRow dataRow)
        {


            Dictionary<string, string> bColors = new Dictionary<string, string>();
            decimal SalesQty, Qty, MonthPlanQty;
            decimal.TryParse(dataRow["SalesQty"].ToString(), out SalesQty);
            decimal.TryParse(dataRow["Qty"].ToString(), out Qty);
            decimal.TryParse(dataRow["MonthPlanQty"].ToString(), out MonthPlanQty);
            if (SalesQty < Qty || SalesQty < MonthPlanQty)
            {
                bColors.Add("SalesQty", "#F16363");
            }
            if (MonthPlanQty > Qty)
            {
                bColors.Add("MonthPlanQty", "#F16363");
            }
            for (int i = 0; i < 10; i++)
            {
                string s1, s2, s3;



                DateTime dateTime = DateTime.Now.AddMonths(i);
                string yearMonth = string.Format("{0:yyyyMM}", dateTime);
                DataRow[] dataRows1 = DtDetail.Select("YearMonth='" + yearMonth + "' and SalesOrderNo='" + dataRow["SalesOrderNo"] + "' AND Code='" + dataRow["Code"] + "'");
                DataRow[] dataRows2 = DtDetail1.Select("YearMonth='" + yearMonth + "' and SalesOrderNo='" + dataRow["SalesOrderNo"] + "' AND Code='" + dataRow["Code"] + "'");
                if (dataRows2.Length > 0)
                {
                    s2 = string.Format("{0:G0}", dataRows2[0]["Qty"]);
                    if (!string.IsNullOrEmpty(s2))
                    {
                        dataRow[yearMonth + "月排产"] = s2;
                    }


                }
                if (dataRows1.Length > 0)
                {
                    s1 = string.Format("{0:G0}", dataRows1[0]["Qty"]);
                    if (!string.IsNullOrEmpty(s1))
                    {
                        dataRow[yearMonth + "月需求"] = s1;
                    }


                }

                bColors.Add(yearMonth + "月排产", "#F5FFC7");
            }
            dataRow["BColors"] = bColors;
        }

