        private void setDetail18287(DataRow dataRow)
        {
            Dictionary<string, string> bColors = new Dictionary<string, string>(); // 背景颜色
            for (int i = 0; i < 10; i++)
            {
                DateTime dateTime = DateTime.Now.AddMonths(i);
                string Month = string.Format("{0:yyyyMM}", dateTime);
                string YearMonth = string.Format("{0}年{1}月", dateTime.Year, dateTime.Month);
                DataRow[] dataRows1 = DtDetail.Select("YearMonth='" + Month + "' and SalesOrderNo='" + dataRow["PONO"] + "' AND Code='" + dataRow["Code"] + "'");
                DataRow[] dataRows2 = DtDetail1.Select("YearMonth='" + Month + "' and SalesOrderNo='" + dataRow["PONO"] + "' AND Code='" + dataRow["Code"] + "'");
                DataRow[] dataRows3 = DtDetail2.Select("YearMonth='" + Month + "' and SalesOrderNo='" + dataRow["PONO"] + "' AND Code='" + dataRow["Code"] + "'");
                int o1 = 0, e1 = 0;
                if (dataRows1.Length > 0 && dataRows1[0]["Qty"] != null)
                {
                    int.TryParse(dataRows1[0]["Qty"].ToString(), out o1);
                    // decimal.TryParse(rows[0]["C1"].ToString(), out c1);
                    dataRow[YearMonth + "A"] = dataRows1[0]["Qty"];
                    //  dataRow[day + "C"] = string.Format("{0:P2}", rows[0]["C1"]);
                }
                if (dataRows2.Length > 0 && dataRows2[0]["ReportQty"] != null)
                {
                    int.TryParse(dataRows2[0]["ReportQty"].ToString(), out e1);
                    dataRow[YearMonth + "B"] = dataRows2[0]["ReportQty"];
                }
                if (!(o1 == 0 && e1 == 0))
                {
                    dataRow[YearMonth + "C"] = o1 - e1;
                }
                if (dataRows3.Length > 0 && dataRows3[0]["Qty"] != null)
                {
                    dataRow[YearMonth + "D"] = dataRows3[0]["Qty"];
                }
                //bColors.Add(YearMonth + "A", "#74FFC0");
                //bColors.Add(YearMonth + "B", "#A6FFFF");
                bColors.Add(YearMonth + "D", "#FFFA9D");

            }
            dataRow["BColors"] = bColors;
        }
        /// <summary>
        /// 生产订单或急单更新
        /// </summary>
        /// <returns></returns>
        public string OrderUpdate()
        {
            bool result = false;
            string msg = "";

            try
            {



                JObject jObject = JsonConvert.DeserializeObject(BodyJson) as JObject;
                if (jObject == null)
                {
                    msg = "未接收到数据，请确认是否为JSON格式";
                    result = false;
                }
                else
                {


                    if (string.IsNullOrEmpty(jObject["OrderNo"].ToString()))
                    {
                        msg = "全部生产订单同步";
                        result = true;

                        SqlHelper.ExecuteNonQuery("truncate table APS_OrderUpdate");
                        SqlHelper.ExecuteNonQuery(SqlHelper.MSSQLConnectionString, "P_APS_OrderUpdate");
                    }
                    else
                    {

                        String sql;
                        SqlHelper.ExecuteNonQuery("truncate table APS_OrderUpdate");


                        string[] OrderNos = jObject["OrderNo"].ToString().Split(',');

                        foreach (string OrderNo in OrderNos)
                        {
                            if (!string.IsNullOrEmpty(OrderNo))
                            {
                                sql = string.Format(@"  
                                insert into APS_OrderUpdate(OrderNo) 
                                select '{0}'
    
                                ", OrderNo);
                                if (!string.IsNullOrEmpty(sql))
                                {
                                    SqlHelper.ExecuteNonQuery(sql);
                                }
                            }

                        }




                        msg = "急单处理同步";
                        result = true;
                        SqlHelper.ExecuteNonQuery(SqlHelper.MSSQLConnectionString, "P_APS_OrderUpdate");
                    }





                }




            }
            catch (Exception ex)
            {
                result = false;
                msg = ex.Message;

            }

            return JsonConvert.SerializeObject(new
            {

                result,
                msg = msg
            });
        }

