        /// <summary>
        /// 根据订单号生成APS订单
        /// </summary>
        /// <returns></returns>
        public string CopyOrderIntoAPS()
        {
            bool result = false;

            List<string> listOK = new List<string>();
            List<string> listError = new List<string>();
            WebApiResult webApiResult = new WebApiResult();
            string sql = "";
            try
            {

                jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;

                if (dev_Account == null)
                {
                    webApiResult.Msg = "当前登录信息已经丢失，请刷新页面重新登录";
                    result = false;
                }

                else if (jArray.Count == 0)
                {

                    webApiResult.Msg = "未接受到数据";
                    result = false;

                }
                else
                {

                    webApiResult.Result = true;
                    foreach (JObject jObject in jArray)
                    {
                        if (!string.IsNullOrEmpty(jObject["OrderID"].ToString()))
                        {

                            sql += $" EXEC P_APS_OrderCreate  {jObject["OrderID"].ToString()} ,'{dev_Account.Account}','{dev_Account.Name}';";
                            listOK.Add(jObject["OrderID"].ToString());
                        }
                    }

                    SqlHelper.ExecuteNonQuery(sql);
                }
            }
            catch (Exception ex)
            {
                webApiResult.Msg = ex.Message + ex.StackTrace;
            }


            return JsonConvert.SerializeObject(new
            {

                result = webApiResult.Result,
                msg = $"成功{listOK.Count},失败{listError.Count},成功订单：{listOK.ToJSON()},失败订单：{listError.ToJSON()}"
            });

        }
        /// <summary>
