                    result = false;
                }

                else if (jArray.Count == 0)
                {

                    webApiResult.Msg = "未接受到数据";
                    result = false;

                }
                else
                {

                    result = true;

                    foreach (JObject jObject in jArray)
                    {
                        webApiResult = await InterfaceSAP.PushMoProcess(jObject["OrderNo"].ToString(), jObject["Extend5"].ToString());
