                            selectOption = jObject["selectOption"].ToString();

                            jArray1 = jObject["dateRange"] as JArray;
                            dateRangeStart = DateTime.Parse(jArray1[0].ToString());
                            dateRangeEnd = DateTime.Parse(jArray1[1].ToString());

                            ISPlan = string.IsNullOrEmpty(jObject["ISPlan"].ToString()) ? 2 : int.Parse(jObject["ISPlan"].ToString());



                        }
                    }

                    stringBuilder.Append($";exec [P_aps_salesorderdetailplanlinescheduling] '{selectOption}','{dateRangeStart}','{dateRangeEnd}','{ISPlan}','{dev_Account.Account}'");
                    SqlHelper.ExecuteNonQuery(stringBuilder.ToString());
                    allMsg = "计算成功！";

                }
            }
            catch (Exception ex)
            {
                allMsg = ex.Message + ex.StackTrace;
            }


            return JsonConvert.SerializeObject(new
            {

                result,
                msg = allMsg
            });
        }

