        /// <summary>
        /// 生产管理计划循环行的时候触发
        /// </summary>
        /// <param name="dataRow"></param>
        public void setDetail14197(DataRow dataRow)
        {
            if (jObject["ERPStartDate"] == null)
            {
                return;
            }

            DateTime StartDate = DateTime.Now.Date;
            DateTime EndDate = DateTime.Now.Date;
            if (jObject["ERPStartDate"] != null)
            {
                JArray jArray = jObject["ERPStartDate"] as JArray;
                if (jArray != null)
                {

                    if (!string.IsNullOrEmpty(jArray[0].ToString()))
                    {
                        StartDate = DateTime.Parse(jArray[0].ToString());
                    }
                    if (jArray.Count > 1 && !string.IsNullOrEmpty(jArray[1].ToString()))
                    {
                        EndDate = DateTime.Parse(jArray[1].ToString());
                    }
                }

            }
            Dictionary<string, string> bColors = new Dictionary<string, string>();//背景颜色
            while (EndDate >= StartDate)
            {

                string day = string.Format("{0:MM/dd}", StartDate);
                string s = DtDetail.Compute("SUM(Hours)", "OrganizeName='" + dataRow["OrganizeName"] + "'  AND IsCloseCase='1' AND ERPStartDate='" + StartDate + "'").ToString();//订单用时,结案
                string s2 = DtDetail.Compute("SUM(Hours)", "OrganizeName='" + dataRow["OrganizeName"] + "'  AND   IsCloseCase='0' and  ERPStartDate='" + StartDate + "'").ToString();//订单用时,未结案
                string s1 = DtDetail1.Compute("SUM(TotalHours)", "OrganizeID='" + dataRow["OrganizeID"] + "'  AND WorkingDate='" + StartDate + "'").ToString();//当天排班

                decimal m, m2, total2;
                decimal.TryParse(s, out m);
                decimal.TryParse(s2, out m2);
                total2 = m + m2;
                if (total2 > 0)
                {
                    string rowValue = "";
                    if (m > 0)
                    {
                        rowValue += m;
                    }
                    if (m2 > 0)
                    {
                        rowValue += "(" + m2 + ")";
                    }
                    dataRow[day] = rowValue;
                    if (string.IsNullOrEmpty(s1))
                    {//当天不上班
                        bColors.Add(day, "#FB6D93");
                    }
                    else
                    {
                        if (decimal.Parse(s1) * 1.2M < total2 || total2 > 24)
                        //if (total2 > 13)
                        {//工时超过
                            bColors.Add(day, "#EF949F");
                        }
                        else if (decimal.Parse(s1) * 0.8M > total2)
                        //if (total2 < 8)
                        {//工时不足
                            bColors.Add(day, "#FFFF00");
                        }
                    }
                }
                else if (!string.IsNullOrEmpty(s1))
                {//有上班，但是没工时

                    //bColors.Add(day, "#F569F3");
                }

                StartDate = StartDate.AddDays(1);
            }
            dataRow["BColors"] = bColors;
        }
