        /// <summary>
        /// 计算开始日期
        /// </summary>
        /// <returns></returns>
        /// <summary>
        /// 计算开始日期
        /// </summary>
        /// <returns></returns>

        /// <summary>
        /// 计算开始日期
        /// </summary>
        /// <returns></returns>
        /// <summary>
        /// 计算开始日期
        /// </summary>
        /// <returns></returns>
        public string CalculationStartDate()
        {
            {
                bool result = true;
                string msg = "计算成功";
                DataSet ds = null;
                DataSet ds2 = null;
                try
                {

                    jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;
                    if (jArray != null)
                    {
                        bool isFirst = true;
                        DateTime d1 = DateTime.Now.Date, d2;
                        int rowIndex = 1;
                        string DefaultLineID = "0";
                        foreach (JObject jObject in jArray)
                        {
                            if (DefaultLineID.IndexOf(jObject["DefaultLineID"].ToString()) == -1)
                            {
                                DefaultLineID += "," + jObject["DefaultLineID"].ToString();
                            }
                        }
                        DataTable dataTable = SqlHelper.ExecuteDataTable($@"SELECT    WorkingDate,TotalHours,OrganizeID FROM APS_OrganizeWorkingTimesDetail(NOLOCK) WHERE WorkingDate>=CAST(GETDATE() AS DATE)
AND organizeid in(
 {DefaultLineID}
)");
                        Dictionary<DateTime, decimal> dayHours = new Dictionary<DateTime, decimal>();
                        foreach (JObject jObject in jArray)
                        {
                            if (jObject != null)
                            {
                                string orderNo = jObject["OrderNo"].ToString();
                                string newd1 = jObject["NewStartDate"].ToString();
                                string oldd1 = jObject["ERPStartDate"].ToString();

                                newd1 = StringHelper.GetJsDate(newd1);
                                oldd1 = StringHelper.GetJsDate(oldd1);

                                if (isFirst)
                                {
                                    isFirst = false;
                                    if (string.IsNullOrEmpty(newd1))
                                    {
                                        msg = $"第{rowIndex}行没有开始日期";
                                        result = false;
                                        break;
                                    }
                                    d1 = DateTime.Parse(newd1).Date;



                                }
                                decimal hours = 0;
                                decimal.TryParse(jObject["Hours"].ToString(), out hours);
                                bool flag = true;
                                bool isFirst2 = true;
                                while (flag)
                                {

                                    if (jObject["IgnoreSunday"].ToString().ToLower() == "true")
                                    {
                                        if (d1.DayOfWeek == DayOfWeek.Sunday)
                                        {
                                            d1 = d1.AddDays(1);
                                        }

                                    }

                                    if (string.IsNullOrEmpty(jObject["DefaultLineID"].ToString()))
                                    {
                                        result = false;
                                        msg = "没有硬拉体";
                                        break;
                                    }


                                    DataRow[] dataRows = dataTable.Select($"WorkingDate='{d1}' and OrganizeID=" + jObject["DefaultLineID"].ToString());
                                    if (d1 > DateTime.Now.AddDays(200))
                                    {
                                        result = false;
                                        msg = "读取排班超过了200天未找到记录，请检查排班是否正确";
                                        break;
                                    }
                                    if (dataRows.Length > 0)
                                    {
                                        decimal totalHours = decimal.Parse(dataRows[0]["TotalHours"].ToString());
                                        if (dayHours.ContainsKey(d1) == false)
                                        {
                                            dayHours.Add(d1, totalHours);
                                        }
                                        //当前时间足够
                                        // if (dayHours[d1] > hours)
                                        {
                                            jObject["NewStartDate"] = string.Format("{0:yyyy-MM-dd}", d1);
                                            jObject["NewEndDate"] = string.Format("{0:yyyy-MM-dd}", d1.AddDays(1));
                                            isFirst2 = false;


                                        }
                                        flag = false;

                                        decimal hoursPre = dayHours[d1];
                                        dayHours[d1] -= hours;
                                        if (dayHours[d1] < totalHours * 0.4m)
                                        {
                                            d1 = d1.AddDays(1);
                                            dataRows = dataTable.Select($"WorkingDate='{d1}' and OrganizeID=" + jObject["DefaultLineID"].ToString());

                                            if (dataRows.Length > 0)
                                            {
                                                totalHours = decimal.Parse(dataRows[0]["TotalHours"].ToString());

                                                dayHours.Add(d1, totalHours);
                                            }

                                            else
                                            {
                                                d1 = d1.AddDays(1);
                                            }


                                        }

                                    }
                                    else
                                    {
                                        d1 = d1.AddDays(1);
                                    }




                                }
                            }
                        }

                    }
                    else
                    {
                        msg = "未接收到数据";
                        result = false;
                    }

                }
