                });
            }
        }

        /// <summary>
        /// 注塑重算排期
        /// </summary>
        /// <returns></returns>
        public string CalculationStartDateForJS()
        {
            bool result = true;
            string msg = "计算成功";

            try
            {
                jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;

                if (jArray != null)
                {
                    DateTime startDate = DateTime.Now.Date;
                    DateTime endDate = DateTime.Now.Date;
                    DateTime APSDemandDate = DateTime.Now.Date;
                    DateTime apsDemandendDate = DateTime.Now.Date.AddDays(15);
                    string groupName = string.Empty;

                    // 用于存储开工日期的列表
                    List<DateTime> workDates = new List<DateTime>();

                    foreach (JObject jObject in jArray)
                    {
                        if (string.IsNullOrEmpty(groupName) && !string.IsNullOrEmpty(jObject["GroupName"].ToString()))
                        {
                            groupName = jObject["GroupName"].ToString();
                        }
                    }
                    // 获取正确的开工日期，排除了节假日
                    DataTable workingDatesTable = SqlHelper.ExecuteDataTable($@"
                SELECT DISTINCT WorkingDate
                FROM V_APS_OrganizeWorkingTimesDetail
                WHERE OrganizeID IN (
                    SELECT c.OrganizeID 
                    FROM APS_ProcessGroup a
                    INNER JOIN APS_ProcessGroupInfo b ON a.ProcessGroupID = b.ProcessGroupID
                    INNER JOIN APS_OrganizeProcessID c ON b.ProcessID = c.ProcessID
                    WHERE a.Remark1 = '注塑'
                )AND GroupName = '{groupName}'
                AND WorkingDate >= CAST(GETDATE() AS DATE)
                AND WorkingDate <= CAST(GETDATE()+200 AS DATE)
                ORDER BY WorkingDate");

                    // 将正确的开工日期添加到列表中
                    foreach (DataRow row in workingDatesTable.Rows)
                    {
                        DateTime workDate = Convert.ToDateTime(row["WorkingDate"]);
                        workDates.Add(workDate);
                    }
                    int jArrayCount = jArray.Count - workDates.Count;
                    // 遍历订单数据
                    foreach (JObject jObject in jArray)
                    {
                        if (jObject != null && !string.IsNullOrEmpty(jObject["APSDemandDate"].ToString()) && !string.IsNullOrEmpty(jObject["MachineID"].ToString()))
                        {
                            string orderNo = jObject["OrderNo"].ToString();

                            // 获取订单的需求日期
                            APSDemandDate = DateTime.Parse(jObject["APSDemandDate"].ToString()).Date;

                            // 找到对应的开始日期
                            startDate = workDates.FirstOrDefault();

                            //能找到开工日期
                            if (startDate != default(DateTime))
                            {
                                // 如果订单的 Extend11 字段的值包含REL，则标记该日期为已分配
                                if (jObject["Extend11"].ToString().Contains("REL"))
                                {
                                    DateTime targetDate = DateTime.Parse(jObject["NewStartDate"].ToString()).Date;
                                    if (workDates.Contains(targetDate))
                                    {
                                        workDates.Remove(targetDate);
                                    }
                                }
                                //如果APSDemandDate是15天以内，那么分配开始日期
                                else if (APSDemandDate <= apsDemandendDate)
                                {
                                    endDate = startDate.AddDays(1);// 设置结束日期为开始日期的后一天
                                                                   // 更新 JObject 中的开始日期和结束日期
                                    jObject["NewStartDate"] = string.Format("{0:yyyy-MM-dd}", startDate);
                                    jObject["NewEndDate"] = string.Format("{0:yyyy-MM-dd}", endDate);
                                    workDates.Remove(startDate);
                                }
                                //如果APSDemandDate是15天以外，并且APSDemandDate-3不在开工日期列表
                                else if (APSDemandDate > apsDemandendDate && !workDates.Contains(APSDemandDate.AddDays(-3)))
                                {
                                    endDate = startDate.AddDays(1);

                                    jObject["NewStartDate"] = string.Format("{0:yyyy-MM-dd}", startDate);
                                    jObject["NewEndDate"] = string.Format("{0:yyyy-MM-dd}", endDate);
                                    workDates.Remove(startDate);

                                }
                                //如果APSDemandDate是15天以外，并且APSDemandDate-3在开工日期列表
                                else if (APSDemandDate > apsDemandendDate && workDates.Contains(APSDemandDate.AddDays(-3)))
                                {
                                    startDate = APSDemandDate.AddDays(-3);
                                    endDate = startDate.AddDays(1);

                                    jObject["NewStartDate"] = string.Format("{0:yyyy-MM-dd}", startDate);
                                    jObject["NewEndDate"] = string.Format("{0:yyyy-MM-dd}", endDate);
                                    workDates.Remove(APSDemandDate.AddDays(-3));
                                }
                            }
                            else
                            {
                                // 如果没有找到开工日期，则标记为失败
                                result = false;
                                msg = jArrayCount + "条数据" + "未找到可用的开工日期";
                                break;
                            }
                        }
                    }
                }
                else
                {
                    msg = "未接收到数据";
                    result = false;
                }
            }
            catch (Exception ex)
            {
                result = false;
                msg = ex.Message;
            }

            return JsonConvert.SerializeObject(new
            {
                data = jArray, // 处理后的订单数据
                result, // 返回标记
                msg // 返回的信息
            });
        }

