        /// <summary>
        /// 登记异常按钮
        /// </summary>
        /// <returns></returns>
        public string RegisterPlanLine()
        {
            bool result = false;
            string msg = "";
            string sql = "";
            try
            {
                jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;

                if (dev_Account == null)
                {
                    msg = "当前登录信息已经丢失，请刷新页面重新登录";
                    result = false;
                }
                else if (jArray.Count == 0)
                {
                    msg = "未接受到数据";
                    result = false;
                }
                else
                {
                    string ids = "'0'";
                    string markStatus = string.Empty; // 默认是退回按钮
                    foreach (var j in jArray)
                    {
                        ids += ",'" + j["ID"].ToString() + "'";
                        if (markStatus == string.Empty) markStatus = j["MarkStatus"].ToString();
                    }
                    switch (markStatus)
                    {
                        case "登记异常":
                            sql = $"UPDATE APS_SalesOrderDetailPlanLine SET SubmitStatus = 1, Submitter = '{dev_Account.Name}', SubmitDate = GETDATE(), Weeks = 'WK' + CAST(DATEPART(WEEK, GETDATE()) AS VARCHAR(2)) WHERE ID IN ({ids})";
                            msg = "登记异常成功";
                            break;
                        case "退回异常":
                            sql = $"UPDATE APS_SalesOrderDetailPlanLine SET SubmitStatus = 0,SubmitDate=NULL,Weeks=NULL,Submitter=NULL," +
                                $"DCP=NULL,ItemCode=NULL,SupplierName=NULL,IssueSpec=NULL,IMCSpec=NULL,CompletionDate=NULL,DelayDate=NULL," +
                                $"LastDeliveryDate=NULL,KPIWaiver='否',CustomerFines=NULL,RemarkSpec=NULL,DutyUnit=NULL,ImpactLevel=NULL,DutyPerson=NULL WHERE ID IN ({ids})";
                            msg = "退回异常成功";
                            break;
                        case "登记免提报":
                            sql = $"UPDATE APS_SalesOrderDetailPlanLine SET SubmitStatus = 2 WHERE ID IN ({ids})";
                            msg = "登记免提报成功";
                            break;
                        case "退回免提报":
                            sql = $"UPDATE APS_SalesOrderDetailPlanLine SET SubmitStatus = 0 WHERE ID IN ({ids})";
                            msg = "退回免提报成功";
                            break;
                    }
                    SqlHelper.ExecuteNonQuery(sql);
                    result = true;
                }
            }
            catch (Exception ex)
            {
                result = false;
                msg = ex.Message + ex.StackTrace;
            }

            return JsonConvert.SerializeObject(new
            {
                result,
                msg
            });
        }
