                            sql = $"UPDATE APS_Order SET ProductionStatus = 22,ModifiedBy = '{dev_Account.Account}', ModifiedByName = '{dev_Account.Name}', ModifyedOn = GETDATE() WHERE OrderID IN ({ids})";
                            msg = "转手工排程成功";
                            break;
                        case "退回"://退回的时候将日计划进行删除
                            sql = $"UPDATE APS_Order SET ProductionStatus =CASE WHEN ProductionStatus = 22 THEN 21 ELSE 26 END,ModifiedBy = '{dev_Account.Account}', ModifiedByName = '{dev_Account.Name}', ModifyedOn = GETDATE() WHERE OrderID IN ({ids});DELETE FROM APS_DayPlan WHERE OrderID IN ({ids});";
                            msg = "退回成功";
