                    decimal SplitQty = 0;

                    if (dtDetail.Rows.Count > 0)
                    {
                        decimal.TryParse(dtDetail.Rows[0]["SplitQty"].ToString(), out SplitQty);
                    }

                    // 比较 reSplitQty 和 totalSpiltQty
                    if (SplitQty != totalSplitQty)
                    {
                        msg = "可拆分数与拆分数量总和不一致,可拆分数量为：" + SplitQty;
                        result = false;
                    }
                    else
                    {
                        if (result)
                        {


                            // 定义数据库连接
                            SqlConnection connection = new SqlConnection(SqlHelper.MSSQLConnectionString);
                            connection.Open(); // 打开数据库
                                               // 定义事务
                            using (SqlTransaction tran = connection.BeginTransaction())
                            {
                                try
                                {
                                    SqlHelper.ExecuteNonQuery(tran, CommandType.Text, sql);
                                    tran.Commit();
                                }
                                catch (Exception ex)
                                {
                                    result = false;
                                    msg = ex.Message;
                                    // 代码异常，回滚事务
                                    tran.Rollback();
                                }
                                finally
                                {
                                    // 不管成功或失败，都要关闭数据库连接
                                    connection.Close();
                                }
                            }
                        }



                        msg = tempMsg;

                    }
                }
            }
            catch (Exception ex)
            {
                result = false;
                msg = "数据操作失败,错误信息:" + ex.Message;
            }

            ApsLegacyJsonResult = base.FormResult(result, msg, null);
            return ApsLegacyJsonResult;
        }
        /// <summary>
