        /// <summary>
        /// 订单配套分析，按线显示
        /// </summary>
        /// <param name="dt"></param>
        public void SetDt14200(ref DataTable dt)
        {



            DateTime StartDate = DateTime.Now.Date;
            DateTime EndDate = DateTime.Now.AddDays(30);
            if (jObject["ERPStartDate"] != null)
            {
                JArray jArray = jObject["ERPStartDate"] as JArray;
                if (jArray != null)
                {

                    if (!string.IsNullOrEmpty(jArray[0].ToString()))
                    {
                        StartDate = DateTime.Parse(jArray[0].ToString());
                    }
                    if (jArray.Count > 1 && !string.IsNullOrEmpty(jArray[1].ToString()))
                    {
                        EndDate = DateTime.Parse(jArray[1].ToString());
                    }
                }

            }
            dt.Columns.Add("BColors", typeof(Dictionary<string, string>));
            DateTime d1 = StartDate;
            while (EndDate >= StartDate)
            {

                string day = string.Format("{0:MM/dd}", StartDate);

                dt.Columns.Add(day);


                ElementColumn[0].Add(new ElementTableOuput() { label = day, prop = day, width = "60", prop2 = string.Format("{0:yyyy-MM-dd}", StartDate), routerName = true, isEdit = true, ControlType = "textbox", extend3 = "P" });
                StartDate = StartDate.AddDays(1);

            }



            if (jObject["dataType"].ToString() == "0")
            {
                DtDetail = SqlHelper.ExecuteDataTable(string.Format(@"
SELECT DefaultLineName,SUM(Q3)/COUNT(1) AS F1
,ERPStartDate
 FROM V_APS_OrderForm
 WHERE ERPStartDate>='{0}'
 AND ERPStartDate<='{1}' {2}
 AND CompletionDate IS NULL   
 GROUP BY DefaultLineName,ERPStartDate
  ", d1, EndDate, mSSQLCore.ResultWhere));
            }
            else
            {
                DtDetail = SqlHelper.ExecuteDataTable(string.Format(@"
SELECT DefaultLineName,SUM(CASE WHEN Q3=1 THEN 1.0 ELSE 0 END)/COUNT(1.0) AS F1
,ERPStartDate
 FROM V_APS_OrderForm
 WHERE ERPStartDate>='{0}'
 AND ERPStartDate<='{1}' {2}
 AND CompletionDate IS NULL   
 GROUP BY DefaultLineName,ERPStartDate
  ", d1, EndDate, mSSQLCore.ResultWhere));
            }

            base.dataFooter = dt.Clone();

        }
        /// <summary>
        /// 订单配套分析,行循环
        /// </summary>
        /// <param name="dataRow"></param>
        public void setDetail14200(DataRow dataRow)
        {


            DateTime StartDate = DateTime.Now.Date;
            DateTime EndDate = DateTime.Now.Date.AddDays(30);
            if (jObject["ERPStartDate"] != null)
            {
                JArray jArray = jObject["ERPStartDate"] as JArray;
                if (jArray != null)
                {

                    if (!string.IsNullOrEmpty(jArray[0].ToString()))
                    {
                        StartDate = DateTime.Parse(jArray[0].ToString());
                    }
                    if (jArray.Count > 1 && !string.IsNullOrEmpty(jArray[1].ToString()))
                    {
                        EndDate = DateTime.Parse(jArray[1].ToString());
                    }
                }

            }

            Dictionary<string, string> bColors = new Dictionary<string, string>();//背景颜色
            while (EndDate >= StartDate)
            {

                string day = string.Format("{0:MM/dd}", StartDate);
                string s = DtDetail.Compute("MIN(F1)", "DefaultLineName='" + dataRow["DefaultLineName"] + "'    AND ERPStartDate='" + StartDate + "'").ToString();//订单用时,结案


                decimal m, m2, total2;
                decimal.TryParse(s, out m);



                if (!string.IsNullOrEmpty(s))
                {
                    dataRow[day] = string.Format("{0:P2}", m);
                    if (m == 0)
                    {//不齐套
                        bColors.Add(day, "#fadbdf");
                    }
                    else if (m == 1)
                    {//齐套
                        bColors.Add(day, "#00fa70");
                    }
                    else if (m < 1)
                    {//不齐套
                        bColors.Add(day, "#ffff00");
                    }
                }



                StartDate = StartDate.AddDays(1);
            }


            dataRow["BColors"] = bColors;
        }
