                string s4 = DtDetail.Compute("COUNT(O1)", "      ERPStartDate='" + StartDate + "'").ToString();//齐套率 
                decimal m1, m2, m3, m4;
                decimal.TryParse(s1, out m1);
                decimal.TryParse(s2, out m2);
                decimal.TryParse(s3, out m3);
                decimal.TryParse(s4, out m4);

                newRow[day + "A"] = s1;

                newRow[day + "B"] = s2;
                // newRow[day + "C"] = string.Format("{0:P2}", m3 / m4);






                StartDate = StartDate.AddDays(1);
            }

            base.dataFooter.Rows.Add(newRow);


        }


        /// <summary>
        /// 订单配套分析，按线显示
        /// </summary>
        /// <param name="dt"></param>
        public void SetDt14199(ref DataTable dt)
        {



            DateTime StartDate = DateTime.Now.Date;
            DateTime EndDate = DateTime.Now.AddDays(45);
            if (jObject["ERPStartDate"] != null)
            {
                JArray jArray = jObject["ERPStartDate"] as JArray;
                if (jArray != null)
                {

                    if (!string.IsNullOrEmpty(jArray[0].ToString()))
                    {
                        StartDate = DateTime.Parse(jArray[0].ToString());
                    }
                    if (jArray.Count > 1 && !string.IsNullOrEmpty(jArray[1].ToString()))
                    {
                        EndDate = DateTime.Parse(jArray[1].ToString());
                    }
                }

            }
            dt.Columns.Add("BColors", typeof(Dictionary<string, string>));
            DateTime d1 = StartDate;
            while (EndDate >= StartDate)
            {

                string day = string.Format("{0:MM/dd}", StartDate);

                dt.Columns.Add(day);


                ElementColumn[0].Add(new ElementTableOuput() { label = day, prop = day, width = "60", prop2 = day, isEdit = true, ControlType = "textbox", extend3 = "P" });
                StartDate = StartDate.AddDays(1);

            }
            string WorkShopName = "", OrganizeName = "";
            string lineID = "0";
            for (int i = 0; i < dt.Rows.Count; i++)
            {
                if (string.IsNullOrEmpty(WorkShopName))
                {
                    WorkShopName = dt.Rows[i]["WorkShopName"].ToString();
                }
                if (string.IsNullOrEmpty(OrganizeName))
                {
                    OrganizeName = dt.Rows[i]["OrganizeName"].ToString();
                }
                if (WorkShopName != dt.Rows[i]["WorkShopName"].ToString() && OrganizeName != dt.Rows[i]["OrganizeName"].ToString())
                {

                    DataRow dataRow = dt.NewRow();
                    dataRow["WorkShopName"] = WorkShopName;
                    dataRow["CompanyName"] = dt.Rows[i]["CompanyName"].ToString();
                    dataRow["OrganizeName"] = "合计";
                    dataRow["OrganizeID"] = 0;
                    dt.Rows.InsertAt(dataRow, i);

                    i++;
                    OrganizeName = dt.Rows[i]["OrganizeName"].ToString();
                    WorkShopName = dt.Rows[i]["WorkShopName"].ToString();
                }
                if (dt.Rows[i]["OrganizeID"].ToString() != "")
                {
                    lineID += "," + dt.Rows[i]["OrganizeID"].ToString();
                }
            }

            this.dataFooter = dt.Clone();

            DtDetail1 = SqlHelper.ExecuteDataTable(string.Format(@"
SELECT a.WorkingDate,
       a.OrganizeID,
       a.TotalHours,
       a.WorkingTimesID,
    
       A2.OrganizeName
	   ,A3.OrganizeName AS WorkShopName
FROM   APS_OrganizeWorkingTimesDetail A
       INNER JOIN Dev_Organize A2
               ON A.OrganizeID = A2.OrganizeID
	   INNER JOIN Dev_Organize A3 ON A2.ParentID=A3.OrganizeID
WHERE WorkingDate>='{0}' and WorkingDate<='{1}' AND A.OrganizeID in({2})", d1, EndDate, lineID));


            DtDetail = SqlHelper.ExecuteDataTable(string.Format(@"
SELECT ERPStartDate,
                         Sum(Hours)                         AS Hours,
SUM(QTY) as Qty,
                         A.DefaultLineName as OrganizeName,WorkShopName
                  FROM   V_APS_MOPlanStep1V2 A
                     left join(
					 select TeamName,WorkShopName from [V_Dev_OrganizeWithOrganizeTeam]
					 GROUP BY TeamName,WorkShopName
					 ) B ON A.DefaultLineName=B.TeamName
                  WHERE  A.CompletionDate IS NULL
                         
                 
                         AND ERPStartDate >= '{0}' and ERPStartDate<='{1}'
                  GROUP  BY ERPStartDate,
                            DefaultLineName,WorkShopName
  ", d1, EndDate));


        }
        /// <summary>
        /// 订单配套分析,行循环
        /// </summary>
        /// <param name="dataRow"></param>
        public void setDetail14199(DataRow dataRow)
        {


            DateTime StartDate = DateTime.Now.Date;
            DateTime EndDate = DateTime.Now.Date.AddDays(45);
            if (jObject["ERPStartDate"] != null)
            {
                JArray jArray = jObject["ERPStartDate"] as JArray;
                if (jArray != null)
                {

                    if (!string.IsNullOrEmpty(jArray[0].ToString()))
                    {
                        StartDate = DateTime.Parse(jArray[0].ToString());
                    }
                    if (jArray.Count > 1 && !string.IsNullOrEmpty(jArray[1].ToString()))
                    {
                        EndDate = DateTime.Parse(jArray[1].ToString());
                    }
                }

            }
            string viewType = "1";
            if (jObject.ContainsKey("viewType"))
            {
                viewType = jObject["viewType"].ToString();
            }
            Dictionary<string, string> bColors = new Dictionary<string, string>();//背景颜色
            int t1 = 0, t2 = 0, t3 = 0;
            while (EndDate >= StartDate)
            {

                string day = string.Format("{0:MM/dd}", StartDate);
                string s = "";
                //   string s2 = DtDetail.Compute("SUM(Hours)", "OrganizeName='" + dataRow["OrganizeName"] + "'  AND   IsCloseCase='0' and  ERPStartDate='" + StartDate + "'").ToString();//订单用时,未结案
                string s1 = "";
                string s2 = "";

                if (dataRow["OrganizeName"].ToString() == "合计")
                {
                    s = DtDetail.Compute("SUM(Hours)", "WorkShopName='" + dataRow["WorkShopName"] + "'    AND ERPStartDate='" + StartDate + "'").ToString();//订单用时,结案
                                                                                                                                                            //   string s2 = DtDetail.Compute("SUM(Hours)", "OrganizeName='" + dataRow["OrganizeName"] + "'  AND   IsCloseCase='0' and  ERPStartDate='" + StartDate + "'").ToString();//订单用时,未结案
                    s1 = DtDetail1.Compute("SUM(TotalHours)", "WorkShopName='" + dataRow["WorkShopName"] + "' AND WorkingDate='" + StartDate + "'").ToString();//当天排班
                    s2 = string.Format("{0:G0}", DtDetail.Compute("SUM(Qty)", " WorkShopName='" + dataRow["WorkShopName"] + "'     AND ERPStartDate='" + StartDate + "'"));//计划工时
                }
                else
                {
                    s = DtDetail.Compute("SUM(Hours)", "WorkShopName='" + dataRow["WorkShopName"] + "'  AND  OrganizeName='" + dataRow["OrganizeName"] + "'    AND ERPStartDate='" + StartDate + "'").ToString();//订单用时,结案
                                                                                                                                                                                                                 //   string s2 = DtDetail.Compute("SUM(Hours)", "OrganizeName='" + dataRow["OrganizeName"] + "'  AND   IsCloseCase='0' and  ERPStartDate='" + StartDate + "'").ToString();//订单用时,未结案
                    s1 = DtDetail1.Compute("SUM(TotalHours)", "OrganizeID='" + dataRow["OrganizeID"] + "'  AND WorkingDate='" + StartDate + "'").ToString();//当天排班
                    s2 = string.Format("{0:G0}", DtDetail.Compute("SUM(Qty)", "WorkShopName='" + dataRow["WorkShopName"] + "' and OrganizeName='" + dataRow["OrganizeName"] + "'    AND ERPStartDate='" + StartDate + "'"));//计划工时

                }

                decimal m, m1, m2, total2;
                decimal.TryParse(s, out m);
                decimal.TryParse(s1, out m1);
                total2 = m;
                if (total2 > 0)
                {

                    switch (viewType)
                    {
                        case "1"://工时
                            dataRow[day] = s;
                            break;
                        case "2"://负荷
                            dataRow[day] = string.Format("{0:P2}", m / (m1 == 0 ? 1 : m1));
                            break;
                        case "3"://数量
                            dataRow[day] = s2;
                            break;
                    }

                    if (m1 == 0)
                    {//当天不上班
                        bColors.Add(day, "#FB6D93");
                        t1++;
                    }
                    else
                    {
                        if (decimal.Parse(s1) * 1.2M < total2)
                        {//工时超过
                            bColors.Add(day, "#EF949F");
                            t1++;
                            t3++;
                        }
                        else if (decimal.Parse(s1) * 0.8M > total2)
                        {//工时不足
                            bColors.Add(day, "#FFFF00");
                            t2++;
                            t1++;
                        }
                    }
                }
                //else if (!string.IsNullOrEmpty(s1))
                //{//有上班，但是没工时

                //    //bColors.Add(day, "#F569F3");
                //}



                StartDate = StartDate.AddDays(1);
            }
            dataRow["S1"] = t1;
            dataRow["S2"] = t2;
            dataRow["S3"] = t3;
            dataRow["BColors"] = bColors;
        }
