            for (int i = 1; i <= 3; i++)
            {
                DateTime d1 = StartDate;
                var col = new ElementTableOuput() { label = "订单数量", prop = "A", width = "", prop2 = "A", isEdit = true, ControlType = "textbox", align = "center" };


                if (i == 1)
                {
                    col = new ElementTableOuput() { label = "订单数量", prop = "A", width = "", prop2 = "A", isEdit = true, ControlType = "textbox", align = "center" };
