                    col.children = new List<ElementTableOuput>();
                }
                else if (i == 3)
                {
                    col = new ElementTableOuput() { label = "人力需求", prop = "C", width = "", prop2 = "C", isEdit = true, ControlType = "textbox", align = "center" };
                    col.children = new List<ElementTableOuput>();
                }
                ElementColumn[0].Add(col);
                while (EndDate >= d1)
                {
                    string day = string.Format("{0:yyyyMM}", d1);
