    Qty,
    case when Capacity <> 0 then Qty / (Capacity * 26.0 * 10.0) else 0 end as CapacityDemand,
    [Hours] * StandardPeoples / (26.0 * 10.0) as LaborDemand,
	ERPStartDate,
    YearMonth
from
    V_APS_MOPlanStep1V2
where ERPStartDate>='{0}' and ERPStartDate<='{1}'", StartDate, EndDate));
        }

        /// <summary>
        /// 订单产能分析，行循环
        /// </summary>
        /// <param name="dt"></param>
        public void setDetail15217(DataRow dataRow)
        {
            DateTime StartDate = new DateTime(DateTime.Now.Year, DateTime.Now.Month, 1);
            DateTime EndDate = StartDate.AddMonths(3).AddDays(-1);

            if (jObject["ERPStartDate"] != null)
            {
                JArray jArray = jObject["ERPStartDate"] as JArray;
                if (jArray != null)
                {

                    if (!string.IsNullOrEmpty(jArray[0].ToString()))
                    {
                        StartDate = DateTime.Parse(jArray[0].ToString());
                    }
                    if (jArray.Count > 1 && !string.IsNullOrEmpty(jArray[1].ToString()))
                    {
                        EndDate = DateTime.Parse(jArray[1].ToString());
                    }
                }

            }

            Dictionary<string, string> bColors = new Dictionary<string, string>();//背景颜色

            for (int i = 1; i <= 3; i++)
            {
                DateTime d1 = StartDate;
                while (EndDate >= d1)
                {
                    string day = string.Format("{0:yyyyMM}", d1);
                    string s = string.Empty;

                    if (i == 1)
                    {
                        s = string.Format("{0:G0}", DtDetail.Compute("SUM(Qty)", "WorkCenter='" + dataRow["WorkCenter"] + "' AND YearMonth='" + day + "'"));
                        bColors.Add(day + i, "#fadbdf");
                    }
                    if (i == 2)
                    {
                        s = string.Format("{0:N3}", DtDetail.Compute("SUM(CapacityDemand)", "WorkCenter='" + dataRow["WorkCenter"] + "' AND YearMonth='" + day + "'"));
                        bColors.Add(day + i, "#88EAF9");
                    }
                    if (i == 3)
                    {
                        s = string.Format("{0:N3}", DtDetail.Compute("SUM(LaborDemand)", "WorkCenter='" + dataRow["WorkCenter"] + "' AND YearMonth='" + day + "'"));
                        bColors.Add(day + i, "#FFFF00");
                    }
                    decimal m;
                    decimal.TryParse(s, out m);
                    if (m != 0)
                    {
                        dataRow[day + i] = m;
                    }

                    d1 = d1.AddMonths(1);
                }
            }
            dataRow["BColors"] = bColors;
        }




