        /// <summary>
        /// 送货计划汇总，行循环
        /// </summary>
        /// <param name="dataRow"></param>
        public void setDetail17271(DataRow dataRow)
        {
            DateTime startDate = startDateMin;
            DateTime endDate = startDate.AddDays(30);
            if (jObject.ContainsKey("DynamicDate1"))
            {
                JArray jArray = jObject["DynamicDate1"] as JArray;
                if (!string.IsNullOrEmpty(jArray[0].ToString()))
                {
                    startDate = DateTime.Parse(jArray[0].ToString());
                    endDate = DateTime.Parse(jArray[1].ToString());
                }
            }

            Dictionary<string, string> bColors = new Dictionary<string, string>(); // 背景颜色
            string suplierCode = "";
            if (!string.IsNullOrEmpty(dataRow["SuplierCode"].ToString()) && dataRow["SuplierCode"].ToString().IndexOf(",") == -1)
            {
                suplierCode = " and SuplierCode='" + dataRow["SuplierCode"].ToString() + "'";
            }

            string oweQtySumstr = string.Format("{0:G0}", DtDetail.Compute("SUM(OweQty)", $"APSDemandDay >= '{startDate}' AND APSDemandDay <= '{endDate}' AND ItemCode='{dataRow["ItemCode"]}' AND Extend12='{dataRow["Extend12"]}'" + suplierCode));
            decimal oweQtySum;
            decimal.TryParse(oweQtySumstr, out oweQtySum);
            dataRow["分配送货"] = oweQtySum;

            while (startDate <= endDate)
            {
                string day = string.Format("{0:yyyy-MM-dd}", startDate);
                string s = string.Empty;

                s = string.Format("{0:G0}", DtDetail.Compute("SUM(OweQty)", "APSDemandDay='" + day + "' AND ItemCode='" + dataRow["ItemCode"] + "' AND Extend12 ='" + dataRow["Extend12"] + "'" + suplierCode));
                day = string.Format("{0:MM-dd}", startDate);
                decimal m;
                decimal.TryParse(s, out m);
                if (m != 0)
                {
                    dataRow[day] = m;
                }

                startDate = startDate.AddDays(1);
            }

            dataRow["BColors"] = bColors;
        }




