            }

        }
        /// <summary>
        /// SMT管理计划循环行的时候触发
        /// </summary>
        /// <param name="dataRow"></param>
        public void setDetail17273(DataRow dataRow)
        {
            DateTime startDate = DateTime.Now.Date;
            DateTime endDate = startDate.AddDays(30);
            if (jObject.ContainsKey("DynamicDate1"))
            {
                JArray jArray = jObject["DynamicDate1"] as JArray;
                if (!string.IsNullOrEmpty(jArray[0].ToString()))
                {
                    startDate = DateTime.Parse(jArray[0].ToString());
                    endDate = DateTime.Parse(jArray[1].ToString());
                }

            }
            Dictionary<string, string> bColors = new Dictionary<string, string>();//背景颜色
            while (endDate >= startDate)
            {

                string day = string.Format("{0:MM-dd}", startDate);
                string s1 = DtDetail.Compute("SUM(Hours)", "LineID='" + dataRow["LineID"] + "'AND PlanDay='" + startDate + "'").ToString();


                //string s = DtDetail.Compute("10.12423423", "LineID='" + dataRow["OrganizeID"] + "'AND PlanDay='" + startDate + "'").ToString();

                string s2 = DtDetail1.Compute("SUM(TotalHours)", "LineID='" + dataRow["LineID"] + "'  AND WorkingDate='" + startDate + "'").ToString();

                decimal m1, m2;
                decimal.TryParse(s1, out m1);
                decimal.TryParse(s2, out m2);
                string rowType = dataRow["RowType"].ToString();
                if (m2 > 0)
                {

                    //if (string.IsNullOrEmpty(s1))
                    //{//当天不上班
                    //    bColors.Add(day, "#FB6D93");
                    //}
                    //else
                    //{
                    //    if (m1 * 1.02M < m1)
                    //    {//工时超过
                    //        bColors.Add(day, "#EF949F");
                    //    }
                    //    else if (m1 * 0.8M > m1)
                    //    {//工时不足
                    //        bColors.Add(day, "#FFFF00");
                    //    }
                    //}
                    if (rowType == "1计划工时")
                    {
                        dataRow[day] = m1;
                    }
                    else if (rowType == "2出勤工时")
                    {
                        dataRow[day] = m2;
                    }
                    else if (rowType == "3负荷")
                    {
                        dataRow[day] = Math.Round(m1 / m2, 2);
                        if (m2 * 1.02M < m1)
                        {//工时超过
                            bColors.Add(day, "#EF949F");
                        }
                        else if (m2 * 0.8M > m1)
                        {//工时不足
                            bColors.Add(day, "#FFFF00");
                        }
                    }
                }
                else if (!string.IsNullOrEmpty(s1))
                {//有上班，但是没工时

                    //bColors.Add(day, "#F569F3");
                }


                startDate = startDate.AddDays(1);
            }
            dataRow["BColors"] = bColors;
        }
        /// <summary>
        /// 计划变更报表，按月
        /// </summary>
        /// <param name="dt"></param>
        public void SetDt19314(ref DataTable dt)
        {
            string extend3 = "";
            string yearMonth = "";
            string groupName = "";

            if (jObject.ContainsKey("Extend3") && jObject.ContainsKey("YearMonth") && jObject.ContainsKey("GroupName"))
            {
                extend3 = jObject["Extend3"].ToString();
                yearMonth = jObject["YearMonth"].ToString();
                groupName = jObject["GroupName"].ToString();

            }
            ;

            // 获取变更记录的统计数据
            DtDetail = SqlHelper.ExecuteDataTable(string.Format(@"
            SELECT A.CreatedByName,
            A.YearMonth,
            ISNULL(A.ChangeReason,'未填写原因') AS ChangeReason,
            Count(1)                     AS ChangeCount,
            ISNULL(A.Extend3,'无模块')   AS Extend3,
            A.GroupName
            FROM   APS_OrderPlanChange A 
            GROUP  BY A.CreatedByName,
            A.YearMonth,
            A.ChangeReason,
	        A.Extend3,
            A.GroupName"));

            // 获取所有的创建者名字
            DataTable createdByNames = SqlHelper.ExecuteDataTable(string.Format(
                @"SELECT CreatedByName FROM APS_OrderPlanChange WHERE Extend3  = '{0}' and YearMonth = '{1}' and GroupName = '{2}' GROUP BY CreatedByName", extend3, yearMonth, groupName));

            // 遍历创建者名字列表
            foreach (DataRow row in createdByNames.Rows)
            {
                string createdByName = row["CreatedByName"].ToString();
                dt.Columns.Add(createdByName);

                ElementColumn[0].Add(new ElementTableOuput()
                {
                    label = createdByName,
                    prop = createdByName,
                    width = "60",
                    prop2 = createdByName,
                    isEdit = true,
                    ControlType = "textbox"
                });
            }
        }

        /// <summary>
        /// 计划管理报表，按月
        /// </summary>
        /// <param name="dataRow"></param>
        public void setDetail19314(DataRow dataRow)
        {
            string extend3 = "";
            string yearMonth = "";
            string groupName = "";

            if (jObject.ContainsKey("Extend3") && jObject.ContainsKey("YearMonth") && jObject.ContainsKey("GroupName"))
            {
                extend3 = jObject["Extend3"].ToString();
                yearMonth = jObject["YearMonth"].ToString();
                groupName = jObject["GroupName"].ToString();

            }
            ;

            // 获取所有的创建者名字
            DataTable createdByNames = SqlHelper.ExecuteDataTable(string.Format(
                @"SELECT CreatedByName FROM APS_OrderPlanChange WHERE Extend3  = '{0}' and YearMonth = '{1}' and GroupName = '{2}' GROUP BY CreatedByName", extend3, yearMonth, groupName));


            // 遍历创建者名字列表
            foreach (DataRow row in createdByNames.Rows)
            {
                string createdByName = row["CreatedByName"].ToString();
                string filter = $"CreatedByName='{createdByName}' AND YearMonth='{dataRow["YearMonth"]}' AND ChangeReason='{dataRow["ChangeReason"]}' AND Extend3='{dataRow["Extend3"]}' AND GroupName = '{dataRow["GroupName"]}'";

                string s = DtDetail.Compute("SUM(ChangeCount)", filter).ToString();
                int m;
                int.TryParse(s, out m);
                dataRow[createdByName] = m;
            }
        }
        /// <summary>
        /// 计划变更报表，按天
