        /// <param name="dt"></param>
        public void SetDt19315(ref DataTable dt)
        {
            string extend3 = "";
            string groupName = "";
            int filterDays = 0;
            int filterType = 0;

            if (jObject.ContainsKey("Extend3") && jObject.ContainsKey("GroupName") && jObject.ContainsKey("ChangeDays") && jObject.ContainsKey("ChangeStatus"))
            {
                extend3 = jObject["Extend3"].ToString();
                groupName = jObject["GroupName"].ToString();
                filterDays = Convert.ToInt32(jObject["ChangeDays"].ToString());
                filterType = Convert.ToInt32(jObject["ChangeStatus"].ToString());

            }
            ;

            // 获取变更记录的统计数据
            string comparisonOperator = filterType == 0 ? ">=" : "<=";

            //以模块为单位
            DtDetail = SqlHelper.ExecuteDataTable(string.Format(@"
            SELECT 
                ISNULL(A.ChangeReason,'未填写原因') AS ChangeReason,
                ISNULL(Count(1),0)                  AS ChangeCount,
                ISNULL(A.Extend3,'无模块')          AS Extend3,
                A.GroupName,
                (SELECT Count(*)
                FROM   APS_OrderPlanChange A1
                WHERE  A1.Extend3 = A.Extend3 AND A1.GroupName = A.GroupName AND YearMonthDay {0} CAST(GETDATE() - {1} AS DATE))                                    AS TotalChangeCount,
                Case when (SELECT Count(*)
                                             FROM   APS_OrderPlanChange A1
                                             WHERE  A1.Extend3 = A.Extend3 AND A1.GroupName = A.GroupName AND YearMonthDay {0} CAST(GETDATE() - {1} AS DATE)) = 0 then 0 else Cast(Count(1) AS DECIMAL(18, 2)) / (SELECT Count(*)
                                             FROM   APS_OrderPlanChange A1
                                             WHERE  A1.Extend3 = A.Extend3 AND A1.GroupName = A.GroupName AND YearMonthDay {0} CAST(GETDATE() - {1} AS DATE)) end AS ChangeCountP
                FROM   APS_OrderPlanChange A 
                WHERE  YearMonthDay {0} CAST(GETDATE() - {1} AS DATE)
                GROUP  BY 
                A.ChangeReason,
                A.Extend3,
                A.GroupName,
                A.GroupName", comparisonOperator, filterDays));
            //以人为单位
            DtDetail1 = SqlHelper.ExecuteDataTable(string.Format(@"
            SELECT A.CreatedByName,
                ISNULL(A.ChangeReason,'未填写原因') AS ChangeReason,
