                ISNULL(A.Extend3,'无模块')          AS Extend3,
                A.GroupName
            FROM   APS_OrderPlanChange A 
            WHERE  YearMonthDay {0} CAST(GETDATE() - {1} AS DATE)
            GROUP  BY A.CreatedByName,
              A.ChangeReason,
              A.Extend3,
              A.GroupName", comparisonOperator, filterDays));


            dt.Columns.Add("ChangeCount", typeof(string)); // 
            dt.Columns.Add("TotalChangeCount", typeof(string)); // 
            dt.Columns.Add("ChangeCountP", typeof(string)); // 
            //ElementColumn[0].Insert(0, new ElementTableOuput() { label = "变更次数", prop = "变更次数", width = "80", prop2 = "变更次数", routerName = true, isEdit = false, ControlType = "textbox", extend3 = "P" });
            //ElementColumn[0].Insert(0, new ElementTableOuput() { label = "总次数", prop = "总次数", width = "80", prop2 = "总次数", routerName = true, isEdit = false, ControlType = "textbox", extend3 = "P" });
