            ElementColumn[0].Add(new ElementTableOuput() { label = "变更数", prop = "ChangeCount", width = "70", prop2 = "变更数", routerName = true, isEdit = false, ControlType = "textbox" });
            ElementColumn[0].Add(new ElementTableOuput() { label = "总数", prop = "TotalChangeCount", width = "60", prop2 = "总数", routerName = true, isEdit = false, ControlType = "textbox" });
            ElementColumn[0].Add(new ElementTableOuput() { label = "占比", prop = "ChangeCountP", width = "60", prop2 = "占比", routerName = true, isEdit = false, ControlType = "textbox" });

            // 获取所有的创建者名字
            DataTable createdByNames = SqlHelper.ExecuteDataTable(string.Format(
                @"SELECT CreatedByName FROM APS_OrderPlanChange WHERE Extend3  = '{0}' and GroupName = '{1}' and YearMonthDay {2} CAST(GETDATE() - {3} AS DATE) GROUP BY CreatedByName", extend3, groupName, comparisonOperator, filterDays));

            // 遍历创建者名字列表
            foreach (DataRow row in createdByNames.Rows)
            {
                string createdByName = row["CreatedByName"].ToString();
                dt.Columns.Add(createdByName);

                ElementColumn[0].Add(new ElementTableOuput()
                {
