                    prop = createdByName,
                    width = "60",
                    prop2 = createdByName,
                    isEdit = true,
                    ControlType = "textbox"
                });
            }
        }

        /// <summary>
        /// 计划管理报表，按天
        /// </summary>
        /// <param name="dataRow"></param>
        public void setDetail19315(DataRow dataRow)
        {
            string extend3 = "";
            string groupName = "";
            int filterDays = 0;
            int filterType = 0;

            if (jObject.ContainsKey("Extend3") && jObject.ContainsKey("GroupName") && jObject.ContainsKey("ChangeDays") && jObject.ContainsKey("ChangeStatus"))
            {
                extend3 = jObject["Extend3"].ToString();
                groupName = jObject["GroupName"].ToString();
                filterDays = Convert.ToInt32(jObject["ChangeDays"].ToString());
                filterType = Convert.ToInt32(jObject["ChangeStatus"].ToString());

            }
            ;
            string comparisonOperator = filterType == 0 ? ">=" : "<=";

            // 获取所有的创建者名字
            DataTable createdByNames = SqlHelper.ExecuteDataTable(string.Format(
                @"SELECT CreatedByName FROM APS_OrderPlanChange WHERE Extend3  = '{0}' and GroupName = '{1}' and YearMonthDay {2} CAST(GETDATE() - {3} AS DATE) GROUP BY CreatedByName", extend3, groupName, comparisonOperator, filterDays));

            string changeCount = string.Format("{0:G0}", DtDetail.Compute("SUM(ChangeCount)", $"ChangeReason='{dataRow["ChangeReason"]}' AND Extend3='{dataRow["Extend3"]}' AND GroupName = '{dataRow["GroupName"]}'"));
            string totalChangeCount = string.Format("{0:G0}", DtDetail.Compute("SUM(TotalChangeCount)", $"ChangeReason='{dataRow["ChangeReason"]}' AND Extend3='{dataRow["Extend3"]}' AND GroupName = '{dataRow["GroupName"]}'"));
            string changeCountP = string.Format("{0:P2}", DtDetail.Compute("SUM(ChangeCountP)", $"ChangeReason='{dataRow["ChangeReason"]}' AND Extend3='{dataRow["Extend3"]}' AND GroupName = '{dataRow["GroupName"]}'"));
            dataRow["ChangeCount"] = string.IsNullOrEmpty(changeCount) ? "0" : changeCount;
            dataRow["TotalChangeCount"] = string.IsNullOrEmpty(totalChangeCount) ? "0" : totalChangeCount;
            dataRow["ChangeCountP"] = changeCountP = string.IsNullOrEmpty(changeCountP) ? "0.00%" : changeCountP;

            // 遍历创建者名字列表
            foreach (DataRow row in createdByNames.Rows)
            {
                string createdByName = row["CreatedByName"].ToString();
                string filter = $"CreatedByName='{createdByName}'AND ChangeReason='{dataRow["ChangeReason"]}' AND Extend3='{dataRow["Extend3"]}' AND GroupName = '{dataRow["GroupName"]}'";

                string s = DtDetail1.Compute("SUM(ChangeCount)", filter).ToString();
                int m;
                int.TryParse(s, out m);
                dataRow[createdByName] = m;
            }
        }
