        /// <summary>
        /// 天宝成品预测计划
        /// </summary>
        /// <param name="dataRow"></param>
        public void setDetail19338(DataRow dataRow)
        {
            if (jObject.ContainsKey("DynamicDate1"))
            {
                JArray jArray = jObject["DynamicDate1"] as JArray;
                d1 = DateTime.Parse(jArray[0].ToString());
                d2 = DateTime.Parse(jArray[1].ToString());
            }
            else
            {
                d1 = DateTime.Parse(string.Format("{0:yyyy-MM-01}", DateTime.Now));
                d2 = DateTime.Parse(string.Format("{0:yyyy-MM-01}", d1.AddMonths(3)));
            }
            string groupName = dataRow["GroupName"].ToString();

            string MaterialID = dataRow["MaterialID"].ToString();
            string CustomerName = dataRow["CustomerName"].ToString();
            decimal Capacity = 0;
            decimal.TryParse(dataRow["Capacity"].ToString(), out Capacity);
            decimal StandardPeoples = 0;
            decimal.TryParse(dataRow["StandardPeoples"].ToString(), out StandardPeoples);
            decimal MachineSeconds = 0;
            decimal.TryParse(dataRow["MachineSeconds"].ToString(), out MachineSeconds);
            decimal Seconds = 0;
            decimal.TryParse(dataRow["Seconds"].ToString(), out Seconds);
            string Factory = dataRow["Extend12"].ToString();
            while (d1 < d2)
            {
                string yearMonth = string.Format("{0:yyyyMM}", d1);


                DataRow[] dataRows = DsDetail.Tables[0].Select("GroupName='" + groupName + "' AND MaterialID='" + MaterialID + "' and YearMonth='" + yearMonth + "' and CustomerName='" + CustomerName + "' AND Factory='" + Factory + "'");
                DataRow[] dataRows2 = DsDetail.Tables[2].Select("GroupName='" + groupName + "' AND LineName='成品预测' and YearMonth='" + yearMonth + "'");

                decimal planQty = 0;

                decimal ScheduleDays = 0;
                decimal TotalHours = 0;
                if (dataRows2.Length > 0)
                {
                    decimal.TryParse(dataRows2[0]["ScheduleDays1"].ToString(), out ScheduleDays);
                    decimal.TryParse(dataRows2[0]["TotalHours1"].ToString(), out TotalHours);
                    if (ScheduleDays == 0)
                        decimal.TryParse(dataRows2[0]["ScheduleDays"].ToString(), out ScheduleDays);
                    if (TotalHours == 0)
                        decimal.TryParse(dataRows2[0]["TotalHours"].ToString(), out TotalHours);
                    dataRow[yearMonth + "月工作天数"] = ScheduleDays;
                    dataRow[yearMonth + "日工作时数"] = TotalHours;
                }
                if (dataRows.Length > 0)
                {

                    decimal.TryParse(dataRows[0]["PlanQty"].ToString(), out planQty);
                    dataRow[yearMonth + ""] = Math.Round(planQty, 6);

                    if (planQty > 0 && Capacity > 0)
                    {
                        dataRow[yearMonth + "产能"] = Math.Round(planQty / Capacity, 6);
                    }
                    if (planQty > 0 && MachineSeconds > 0)
                    {
                        dataRow[yearMonth + "财务机器"] = Math.Round(planQty * MachineSeconds / 3600M, 6);
                    }
                    if (planQty > 0 && Seconds > 0)
                    {
                        dataRow[yearMonth + "财务人工"] = Math.Round(planQty * Seconds / 3600M, 6);
                    }
                    if (planQty > 0 && Capacity > 0 && StandardPeoples > 0)
                    {
                        dataRow[yearMonth + "计划人工"] = Math.Round(planQty / Capacity * StandardPeoples, 6);

                    }
                    if (planQty > 0 && Capacity > 0 && StandardPeoples > 0 && ScheduleDays > 0 && TotalHours > 0)
                    {

                        dataRow[yearMonth + "需人数"] = Math.Round((planQty / Capacity * StandardPeoples) / (ScheduleDays * TotalHours), 6);

                        dataRow[yearMonth + "拉体数"] = Math.Round(planQty / (Capacity * ScheduleDays * TotalHours), 6);
                        //dataRow[yearMonth + "需求人数"] = Math.Round((planQty / Capacity * StandardPeoples) / (ScheduleDays * TotalHours), 5);

                        //dataRow[yearMonth + "需求拉体数量"] = Math.Round(planQty / (Capacity * ScheduleDays * TotalHours), 5);
                    }


                }
                //if (dataRows2.Length > 0)
                //{
                //    decimal.TryParse(dataRows2[0]["Qty"].ToString(), out planQty);
                //    dataRow[d1.Month + "月实际"] = Math.Round(planQty, 0);
                //    if (planQty > 0 && Capacity > 0)
                //    {
                //        dataRow[d1.Month + "月实际拉体"] = Math.Round(planQty / (Capacity * 27 * 10), 2);
                //    }
                //    if (planQty > 0 && Capacity > 0)
                //    {
                //        dataRow[d1.Month + "月实际人力"] = Math.Round((planQty / Capacity * StandardPeoples) / (27 * 10), 2);
                //    }
                //}
                d1 = d1.AddMonths(1);
            }

        }
        /// <summary>
        /// 天宝预测计划的汇总
        /// </summary>
        /// <param name="dt"></param>
        public void SetDt19339(ref DataTable dt)
        {

            string dataFrom = (string)jObject["dataFrom"];
            string showFun = (string)jObject["showFun"];

            if (jObject.ContainsKey("DynamicDate1"))
            {
                JArray jArray = jObject["DynamicDate1"] as JArray;
