                d2 = DateTime.Parse(string.Format("{0:yyyy-MM-01}", d1.AddMonths(3)));
            }



            ElementColumn[0][0].label = "销售单位";



            //数量
            DateTime d3 = d1;

            string where = "";
            if (dataFrom == "数量")
            {
                where = " AND STEUS='PP01'";
                while (d3 < d2)
                {
                    string yearMonth = string.Format("{0:yyyyMM}", d3);
                    dt.Columns.Add(yearMonth + "月预测", typeof(decimal));
                    //dt.Columns.Add(d3.Month + "月实际", typeof(decimal));
                    //dt.Columns.Add(d3.Month + "月差异", typeof(decimal));
                    ElementColumn[0].Add(new ElementTableOuput() { label = d3.Month + "月预测", prop = yearMonth + "月预测", width = "80", prop2 = d3.Month + "月预测", isEdit = false, ControlType = "textbox", align = "center" });
                    //ElementColumn[0].Add(new ElementTableOuput() { label = d3.Month + "月实际", prop = d3.Month + "月实际", width = "80", prop2 = d3.Month + "月实际", isEdit = false, ControlType = "textbox", align = "center" });
                    //ElementColumn[0].Add(new ElementTableOuput() { label = d3.Month + "月差异", prop = d3.Month + "月差异", width = "80", prop2 = d3.Month + "月差异", isEdit = false, ControlType = "textbox", align = "center" });
                    d3 = d3.AddMonths(1);

                }
            }
            //拉体
            else if (dataFrom == "拉体")
            {
                where = " AND STEUS='PP01'";
                d3 = d1;
                while (d3 < d2)
                {

                    string yearMonth = string.Format("{0:yyyyMM}", d3);
                    dt.Columns.Add(yearMonth + "月需求拉体", typeof(decimal));
                    //dt.Columns.Add(d3.Month + "月实际拉体", typeof(decimal));
                    //dt.Columns.Add(d3.Month + "月差异", typeof(decimal));

                    ElementColumn[0].Add(new ElementTableOuput() { label = d3.Month + "月需求拉体", prop = yearMonth + "月需求拉体", width = "80", prop2 = d3.Month + "月预测拉体", isEdit = false, ControlType = "textbox", align = "center" });
                    //ElementColumn[0].Add(new ElementTableOuput() { label = d3.Month + "月实际拉体", prop = d3.Month + "月实际拉体", width = "80", prop2 = d3.Month + "月实际拉体", isEdit = false, ControlType = "textbox", align = "center" });
                    //ElementColumn[0].Add(new ElementTableOuput() { label = d3.Month + "月差异", prop = d3.Month + "月差异", width = "80", prop2 = d3.Month + "月差异", isEdit = false, ControlType = "textbox", align = "center" });
                    d3 = d3.AddMonths(1);
                }

            }
            //人力
            else if (dataFrom == "人力")
            {
                d3 = d1;
                while (d3 < d2)
                {
                    string yearMonth = string.Format("{0:yyyyMM}", d3);
                    dt.Columns.Add(yearMonth + "月需求人力", typeof(decimal));
                    //dt.Columns.Add(d3.Month + "月实际人力", typeof(decimal));
                    //dt.Columns.Add(d3.Month + "月差异", typeof(decimal));

                    ElementColumn[0].Add(new ElementTableOuput() { label = d3.Month + "月需求人力", prop = yearMonth + "月需求人力", width = "80", prop2 = d3.Month + "月预测人力", isEdit = false, ControlType = "textbox", align = "center" });
                    //ElementColumn[0].Add(new ElementTableOuput() { label = d3.Month + "月实际人力", prop = d3.Month + "月实际人力", width = "80", prop2 = d3.Month + "月实际人力", isEdit = false, ControlType = "textbox", align = "center" });
                    //ElementColumn[0].Add(new ElementTableOuput() { label = d3.Month + "月差异", prop = d3.Month + "月差异", width = "80", prop2 = d3.Month + "月差异", isEdit = false, ControlType = "textbox", align = "center" });
                    d3 = d3.AddMonths(1);
                }
            }
            DsDetail = SqlHelper.ExecuteDataset(string.Format($@"
       SELECT SalesDept,GroupName,YearMonth,Extend12,sum(Q1) AS Q1
,SUM(Q2) AS Q2 ,SUM(A.Q3) AS Q3,SalesDept,ProcessID,ProcessName
FROM   (SELECT A.SalesDept ,
               a.GroupName,
               b.YearMonth,
          
               A.Extend12,
               b.PlanQty AS Q1,
             
               b.PlanQty / ( a.Capacity * B.ScheduleDays * B.TotalHours ) AS Q2,
              
               ( B.PlanQty / A.Capacity * A.StandardPeoples ) / ( B.ScheduleDays * B.TotalHours ) AS Q3
			   ,ProcessID,ProcessName
        FROM   APS_ManualForecast a
               LEFT JOIN(SELECT Extend2,
                                A.GroupName,
                                A.MaterialID,
                                A.YearMonth,
                                Sum(PlanQty)                            AS PlanQty,
                                Factory,
                                Isnull(B.ScheduleDays1, B.ScheduleDays) AS ScheduleDays,
                                Isnull(B.TotalHours1, B.TotalHours)     AS TotalHours
                         FROM   [dbo].APS_ManualForecastDetail A
                                LEFT JOIN APS_OrganizeWorkingTimesForecast B
                                       ON A.GroupName = B.GroupName
                                          AND B.YearMonth = A.YearMonth AND A.Extend3+'预测'=b.LineName
                         GROUP  BY Extend2,
                                   A.GroupName,
                                   A.MaterialID,
                                   A.YearMonth,
                                   Factory,
                                   Isnull(B.ScheduleDays1, B.ScheduleDays),
                                   Isnull(B.TotalHours1, B.TotalHours))b
                      ON a.MaterialID = b.MaterialID
                         AND a.GroupName = b.GroupName
                         AND a.SalesDept = b.Extend2
                         AND a.Extend12 = b.Factory 
        WHERE  a.extend3 = '成品'
               AND a.FVersion = '10' " + where + @") A 
			   GROUP BY SalesDept,GroupName,YearMonth,Extend12,ProcessID,ProcessName
			   
			   
            ", ""));

        }

