        /// <summary>
        /// 天宝注塑预测计划行事件
        /// </summary>
        /// <param name="dataRow"></param>
        public void setDetail22348(DataRow dataRow)
        {
            if (dataRow["PurchaseType"].ToString() != "F")
            {

                if (jObject.ContainsKey("DynamicDate1"))
                {
                    JArray jArray = jObject["DynamicDate1"] as JArray;
                    d1 = DateTime.Parse(jArray[0].ToString());
                    d2 = DateTime.Parse(jArray[1].ToString());
                }
                else
                {
                    d1 = DateTime.Parse(string.Format("{0:yyyy-MM-01}", DateTime.Now));
                    d2 = DateTime.Parse(string.Format("{0:yyyy-MM-01}", d1.AddMonths(3)));
                }
                string groupName = dataRow["GroupName"].ToString();

                string MaterialID = dataRow["MaterialID"].ToString();

                decimal Capacity = 0;
                decimal.TryParse(dataRow["Capacity"].ToString(), out Capacity);
                decimal StandardPeoples = 0;
                decimal.TryParse(dataRow["StandardPeoples"].ToString(), out StandardPeoples);
                decimal MachineSeconds = 0;
                decimal.TryParse(dataRow["MachineSeconds"].ToString(), out MachineSeconds);
                decimal Seconds = 0;
                decimal.TryParse(dataRow["Seconds"].ToString(), out Seconds);
                string Factory = dataRow["Extend12"].ToString();
                decimal BaseQty;
                decimal.TryParse(dataRow["BaseQty"].ToString(), out BaseQty);
                while (d1 < d2)
                {
                    string yearMonth = string.Format("{0:yyyyMM}", d1);


                    DataRow[] dataRows = DsDetail.Tables[0].Select("GroupName='" + groupName + "' AND MaterialID='" + MaterialID + "' and YearMonth='" + yearMonth + "'  AND Factory='" + Factory + "'");

                    DataRow[] dataRows2 = DsDetail.Tables[1].Select("GroupName='" + groupName + "' AND LineName='注塑预测' and YearMonth='" + yearMonth + "'");

                    decimal planQty = 0;

                    decimal ScheduleDays = 0;
                    decimal TotalHours = 0;
                    if (dataRows2.Length > 0)
                    {
                        decimal.TryParse(dataRows2[0]["ScheduleDays1"].ToString(), out ScheduleDays);
                        decimal.TryParse(dataRows2[0]["TotalHours1"].ToString(), out TotalHours);
                        if (ScheduleDays == 0)
                            decimal.TryParse(dataRows2[0]["ScheduleDays"].ToString(), out ScheduleDays);
                        if (TotalHours == 0)
                            decimal.TryParse(dataRows2[0]["TotalHours"].ToString(), out TotalHours);
                        dataRow[yearMonth + "月工作天数"] = ScheduleDays;
                        dataRow[yearMonth + "日工作时数"] = TotalHours;
                    }

                    if (dataRows.Length > 0)
                    {
                        decimal.TryParse(dataRows[0]["PlanQty"].ToString(), out planQty);
                        dataRow[yearMonth + "预测"] = Math.Round(planQty, 0);

                        if (planQty > 0 && StandardPeoples > 0 && Capacity > 0)
                        {

                            dataRow[yearMonth + "产能"] = Math.Round(planQty / Capacity, 6);
                            dataRow[yearMonth + "计划人工工时"] = Math.Round(planQty / Capacity * StandardPeoples, 6);

                        }
                        if (planQty > 0 && Capacity > 0 && TotalHours > 0 && ScheduleDays > 0)
                        {
                            dataRow[yearMonth + "拉体数"] = Math.Round(planQty / (Capacity * ScheduleDays * TotalHours), 6);
                            dataRow[yearMonth + "需人数"] = Math.Round((planQty / Capacity * StandardPeoples) / (ScheduleDays * (TotalHours / 2.0M)), 6);//？？？？？？？？？？？？？？？？？？
                        }

                        if (planQty > 0 && Seconds > 0 && BaseQty > 0)
                        {

                            dataRow[yearMonth + "财务人工工时"] = Math.Round(planQty * Seconds / 3600m / BaseQty, 6);

                        }
                        if (planQty > 0 && MachineSeconds > 0 && BaseQty > 0)
                        {


                            dataRow[yearMonth + "财务机器工时"] = Math.Round(planQty * MachineSeconds / 3600m / BaseQty, 6);
                        }

                    }

                    d1 = d1.AddMonths(1);
                }
            }
        }





