        /// <summary>
        /// 天宝SMT预测计划
        /// </summary>
        /// <param name="dataRow"></param>
        public void setDetail22347(DataRow dataRow)
        {
            if (jObject.ContainsKey("DynamicDate1"))
            {
                JArray jArray = jObject["DynamicDate1"] as JArray;
                d1 = DateTime.Parse(jArray[0].ToString());
                d2 = DateTime.Parse(jArray[1].ToString());
            }
            else
            {
                d1 = DateTime.Parse(string.Format("{0:yyyy-MM-01}", DateTime.Now));
                d2 = DateTime.Parse(string.Format("{0:yyyy-MM-01}", d1.AddMonths(3)));
            }
            string groupName = dataRow["GroupName"].ToString();

            string MaterialID = dataRow["MaterialID"].ToString();

            decimal Capacity = 0;
            decimal.TryParse(dataRow["Capacity"].ToString(), out Capacity);
            decimal StandardPeoples = 0;
            decimal.TryParse(dataRow["StandardPeoples"].ToString(), out StandardPeoples);
            decimal MachineSeconds = 0;
            decimal.TryParse(dataRow["MachineSeconds"].ToString(), out MachineSeconds);
            decimal Seconds = 0;
            decimal.TryParse(dataRow["Seconds"].ToString(), out Seconds);
            decimal q1, q2, q3, q4, q5, q6;
            decimal.TryParse(dataRow["AI10"].ToString(), out q1);
            decimal.TryParse(dataRow["AI20"].ToString(), out q2);
            decimal.TryParse(dataRow["AI15"].ToString(), out q3);
            decimal.TryParse(dataRow["SM02"].ToString(), out q4);
            decimal.TryParse(dataRow["SM010"].ToString(), out q5);
            decimal.TryParse(dataRow["SM020"].ToString(), out q6);
            string Factory = dataRow["Extend12"].ToString();
            while (d1 < d2)
            {
                string yearMonth = string.Format("{0:yyyyMM}", d1);


                DataRow[] dataRows = DsDetail.Tables[0].Select("GroupName='" + groupName + "' AND MaterialID='" + MaterialID + "' and YearMonth='" + yearMonth + "'  AND Factory='" + Factory + "'");

                DataRow[] dataRows2 = DsDetail.Tables[1].Select("GroupName='" + groupName + "' AND LineName='SMT预测' and YearMonth='" + yearMonth + "'");

                decimal planQty = 0;

                decimal ScheduleDays = 0;
                decimal TotalHours = 0;
                if (dataRows2.Length > 0)
                {
                    decimal.TryParse(dataRows2[0]["ScheduleDays1"].ToString(), out ScheduleDays);
                    decimal.TryParse(dataRows2[0]["TotalHours1"].ToString(), out TotalHours);
                    if (ScheduleDays == 0)
                        decimal.TryParse(dataRows2[0]["ScheduleDays"].ToString(), out ScheduleDays);
                    if (TotalHours == 0)
                        decimal.TryParse(dataRows2[0]["TotalHours"].ToString(), out TotalHours);
                    dataRow[yearMonth + "月工作天数"] = ScheduleDays;
                    dataRow[yearMonth + "日工作时数"] = TotalHours;
                }

                if (dataRows.Length > 0)
                {
                    decimal.TryParse(dataRows[0]["PlanQty"].ToString(), out planQty);
                    dataRow[yearMonth + "预测"] = Math.Round(planQty, 0);


                    if (planQty > 0 && Capacity > 0)
                    {

                        dataRow[yearMonth + "产能"] = Math.Round(planQty / Capacity, 2);
                        dataRow[yearMonth + "计划人工工时"] = Math.Round(planQty / Capacity * StandardPeoples, 6);

                    }

                    if (planQty > 0 && q1 > 0 && TotalHours > 0 && ScheduleDays > 0)
                    {
                        dataRow[yearMonth + "卧式"] = Math.Round(planQty / (q1 * ScheduleDays * TotalHours), 6);
                    }
                    if (planQty > 0 && q2 > 0 && TotalHours > 0 && ScheduleDays > 0)
                    {

                        dataRow[yearMonth + "标准件立式"] = Math.Round(planQty / (q2 * ScheduleDays * TotalHours), 6);
                    }
                    if (planQty > 0 && q3 > 0 && TotalHours > 0 && ScheduleDays > 0)
                    {

                        dataRow[yearMonth + "立大跨距"] = Math.Round(planQty / (q3 * ScheduleDays * TotalHours), 6);
                    }
                    if (planQty > 0 && q4 > 0 && TotalHours > 0 && ScheduleDays > 0)
                    {

                        dataRow[yearMonth + "三星+三星"] = Math.Round(planQty / (q4 * ScheduleDays * TotalHours), 6);
                    }
                    if (planQty > 0 && q5 > 0 && TotalHours > 0 && ScheduleDays > 0)
                    {

                        dataRow[yearMonth + "YAMAHA"] = Math.Round(planQty / (q5 * ScheduleDays * TotalHours), 6);
                    }
                    if (planQty > 0 && q6 > 0 && TotalHours > 0 && ScheduleDays > 0)
                    {

                        dataRow[yearMonth + "并YAMAHA"] = Math.Round(planQty / (q6 * ScheduleDays * TotalHours), 6);
                    }
                    if (planQty > 0 && Seconds > 0)
                    {

                        dataRow[yearMonth + "财务人工工时"] = Math.Round(planQty * Seconds / 3600m, 6);

                    }
                    if (planQty > 0 && MachineSeconds > 0)
                    {


                        dataRow[yearMonth + "财务机器工时"] = Math.Round(planQty * MachineSeconds / 3600m, 6);
                    }
                }

                d1 = d1.AddMonths(1);
            }

        }
















