        SELECT YearMonth,
               MaterialID,
               MonthIssuedQty,
               AVGMonthIssuedQty,
               UniqueMonths
        FROM   APS_MaterialIssued;

        SELECT MaterialID,
               SUM(IssuedQty + FREPICKEDQTY - FGOODRETURNQTY - FINCDEFECTRETURNQTY - FPRCDEFECTRETURNQTY) / COUNT(DISTINCT YearMonth) AS ThreeMonthsIssuedQty0,
               SUM(IssuedQty + FREPICKEDQTY - FGOODRETURNQTY - FINCDEFECTRETURNQTY - FPRCDEFECTRETURNQTY) / {months} AS ThreeMonthsIssuedQty,
               COUNT(DISTINCT YearMonth) AS UniqueMonths
        FROM   APS_OrderBOM
        WHERE  YearMonth >= FORMAT(DATEADD(MONTH, -{months}, GETDATE()), 'yyyy-MM') AND YearMonth < FORMAT( GETDATE(),'yyyy-MM')
        GROUP  BY MaterialID 
    ", ""));

            DateTime d3 = d2;

            while (d3 < d1)
