        public void SetDt20342(ref DataTable dt)
        {

            // 获取变更记录的统计数据
            DsDetail = SqlHelper.ExecuteDataset(string.Format($@"
        SELECT OrderDateYear,
               SaleToName,
               CAST(Sum(TotalCounter)AS DECIMAL(18,2)) AS TotalCounter5
        FROM   V_APS_BusinessOrderDetail
		  WHERE IsFinish =0 AND Extend7 = '销售订单'
        GROUP  BY OrderDateYear,
                  SaleToName


 
SELECT OrderDateYear
        FROM   [V_APS_BusinessOrderDetail]
GROUP  BY OrderDateYear
ORDER  BY OrderDateYear  


SELECT UniqueMonths AS YearMonth,
       SaleToName,
       TotalCounter5
FROM   [V_APS_MonthShipmentPlan]
 

SELECT UniqueMonths AS YearMonth
FROM   V_APS_MonthShipmentPlan
WHERE TotalCounter5>0
Group  BY UniqueMonths
ORDER BY UniqueMonths"));
            // 创建一个临时列表保存年份的表头信息
            List<ElementTableOuput> yearColumns = new List<ElementTableOuput>();
