            ElementColumn[0].InsertRange(1, yearColumns);
            // 遍历月份
            foreach (DataRow row in DsDetail.Tables[3].Rows)
            {
                string yearMonth = row["YearMonth"].ToString();
                dt.Columns.Add(yearMonth);

                ElementColumn[0].Add(new ElementTableOuput()
                {
                    label = yearMonth,
                    prop = yearMonth,
                    width = "70",
                    prop2 = yearMonth,
                    isEdit = false,
                    ControlType = "textbox"
                });
            }


        }
