            {
                string yearMonth = row["YearMonth"].ToString();
                string filter = $"YearMonth='{yearMonth}' AND SaleToName='{dataRow["SaleToName"]}'";

                string s = DsDetail.Tables[2].Compute("SUM(TotalCounter5)", filter).ToString();
                decimal m;
                decimal.TryParse(s, out m);
                if (m > 0)
                {
                    dataRow[yearMonth] = m;
                }
            }



        }
        // 自定义方法，将月份数字转换为中文月份
        public string GetChineseMonth(int month)
        {
            switch (month)
            {
                case 1:
                    return "一月";
                case 2:
                    return "二月";
                case 3:
                    return "三月";
                case 4:
                    return "四月";
                case 5:
                    return "五月";
                case 6:
                    return "六月";
                case 7:
                    return "七月";
                case 8:
                    return "八月";
                case 9:
                    return "九月";
                case 10:
                    return "十月";
                case 11:
                    return "十一月";
                case 12:
                    return "十二月";
                default:
                    throw new ArgumentOutOfRangeException(nameof(month), "月份应在1到12之间。");
            }
        }



        /// <summary>
        /// 根据计算好的总排期，插入日计划
        /// </summary>
        /// <returns></returns>
        public string InsertProcessPlanByOrderID()
        {
            try
            {
                result = true;
                msg = "操作成功!";

                jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;

                if (dev_Account == null)
                {
                    allMsg = "当前登录信息已经丢失，请刷新页面重新登录";
                    result = false;
                }

                else if (jArray.Count == 0)
                {

                    allMsg = "未接受到数据";
                    result = false;
                }
                else
                {

                    SqlConnection connection = new SqlConnection(SqlHelper.MSSQLConnectionString);
                    connection.Open();
                    using (SqlTransaction tran = connection.BeginTransaction())
                    {
                        try
                        {
                            foreach (JObject jObject in jArray)
                            {

                                if (result)
                                {
                                    SqlParameter[] sqlParameters = new SqlParameter[3];
                                    sqlParameters[0] = new SqlParameter("@OrderID", jObject["OrderID"].ToString());
                                    sqlParameters[1] = new SqlParameter("@Result", SqlDbType.Bit);
                                    sqlParameters[2] = new SqlParameter("@Msg", SqlDbType.NVarChar, 500);
                                    sqlParameters[1].Direction = sqlParameters[2].Direction = ParameterDirection.Output;
                                    SqlHelper.ExecuteNonQuery(tran, "P_APS_InsertProcessPlanByOrderID", sqlParameters);
                                    result = sqlParameters[1].Value.ToString().ToLower() == "true";
                                    allMsg = sqlParameters[2].Value.ToString();


                                }
                                else
                                {
                                    tran.Rollback();
                                    break;
                                }

                            }

                            if (result)
                            {

                                SqlHelper.ExecuteNonQuery(tran, "P_APS_AfterInsertProcessPlanByOrderID");//为日计划分配序号

                                tran.Commit();

                                allMsg = "转入日计划共" + jArray.Count + "笔记录";
                            }



                        }
                        catch (Exception ex)
                        {
                            result = false;
                            allMsg = ex.Message;
                            // tran.Rollback();


                        }
                        finally
                        {

                            connection.Close();
                        }
                    }




                }
            }
            catch (Exception ex)
            {
                allMsg = ex.Message;
            }


            return JsonConvert.SerializeObject(new
            {

                result,
                msg = allMsg
            });


        }
        /// <summary>
        /// 天宝下达
        /// </summary>
        /// <returns></returns>
        public string CatchOrderByCode()
        {


            try
            {
                result = true;
                msg = "操作成功!";

                jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;

                if (dev_Account == null)
                {
                    msg = "当前登录信息已经丢失，请刷新页面重新登录";
                    result = false;
                }

                else if (jArray.Count == 0)
                {
                    msg = "未接受到数据";
                    result = false;
                }
                else
                {
                    //定义数据库连接
                    SqlConnection connection = new SqlConnection(SqlHelper.MSSQLConnectionString);
                    connection.Open();//打开数据库

                    //定义事务
                    using (SqlTransaction tran = connection.BeginTransaction())
                    {
                        try
                        {
                            string sql = "UPDATE APS_OrderPlanMaterialFormByItem  SET ModifyedOn=NULL,ModifiedBy=null where ModifiedBy='" + dev_Account.Account + "';   UPDATE APS_OrderPlanMaterialFormByItem SET ModifyedOn=GETDATE(),ModifiedBy='" + dev_Account.Account + "' WHERE ID IN(0";
                            string days = "0";
                            string ProcessGroupName = "";
                            foreach (JObject jObject in jArray)
                            {
                                sql += "," + jObject["ID"].ToString();
                                days = jObject["days"].ToString();
                                ProcessGroupName = jObject["ProcessGroupName"].ToString();
                            }
                            sql += ")";
                            SqlHelper.ExecuteNonQuery(tran, CommandType.Text, sql);
                            SqlParameter[] sqlParameters = new SqlParameter[5];
                            sqlParameters[0] = new SqlParameter("@Account", dev_Account.Account);
                            sqlParameters[1] = new SqlParameter("@days", days);
                            sqlParameters[2] = new SqlParameter("@ProcessGroupName", ProcessGroupName);



                            sqlParameters[3] = new SqlParameter("@Result", SqlDbType.Bit);
                            sqlParameters[4] = new SqlParameter("@Msg", SqlDbType.NVarChar, 500);
                            sqlParameters[3].Direction = sqlParameters[4].Direction = ParameterDirection.Output;
                            SqlHelper.ExecuteNonQuery(tran, "P_SelectOrderNOCalculation", sqlParameters);
                            result = sqlParameters[3].Value.ToString().ToLower() == "true";
                            msg = sqlParameters[4].Value.ToString();
                            if (result)
                            {
                                //提交事务
                                tran.Commit();

                                msg = "转入日计划共" + jArray.Count + "笔记录";
                            }
                            else
                            {
                                //存储过程执行失败，回滚事务，
                                tran.Rollback();
                            }
                        }
                        catch (Exception ex)
                        {
                            result = false;
                            msg = ex.Message;
                            //代码异常，回滚事务
                            tran.Rollback();
                        }
                        finally
                        {
                            //不管成功或失败，都要关闭数据库连接
                            connection.Close();
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                msg = ex.Message;
            }
            return JsonConvert.SerializeObject(new
            {
                result,
                msg = msg
            });
        }
