        /// </summary>
        /// <param name="dt"></param>
        public void SetDt17257(ref DataTable dt)
        {
            DateTime d1 = DateTime.Now.Date;
            DateTime d2 = d1.AddDays(30);
            if (jObject.ContainsKey("DynamicDate1"))
            {
                JArray jArray = jObject["DynamicDate1"] as JArray;
                if (!string.IsNullOrEmpty(jArray[0].ToString()))
                {
                    d1 = DateTime.Parse(jArray[0].ToString());
                    d2 = DateTime.Parse(jArray[1].ToString());
                }

            }

            dt.Columns.Add("BColors", typeof(Dictionary<string, string>));

            DtDetail = SqlHelper.ExecuteDataTable(string.Format(@"
           SELECT   [EID]
      ,[ID]
      ,[DataDay]
      ,[DataValue]
  FROM  [dbo].[APS_DeliveryControlPlanDetail]
 

            where DataDay>='{0}' and DataDay<='{1}'
", d1, d2));

            while (d2 >= d1)
            {
                string prop = string.Format("{0:MM-dd}", d1);
                dt.Columns.Add(prop, typeof(string));
                ElementColumn[0].Add(new ElementTableOuput() { label = prop, prop = prop, width = "200", prop2 = prop, routerName = true, isEdit = true, ControlType = "textbox", extend3 = "P" });
                d1 = d1.AddDays(1);
            }
        }

        /// <summary>
        /// 订单产能分析，行循环
        /// </summary>
        /// <param name="dt"></param>
        public void setDetail17257(DataRow dataRow)
        {
            DateTime d1 = DateTime.Now.Date;
            DateTime d2 = d1.AddDays(30);
            if (jObject.ContainsKey("DynamicDate1"))
            {
                JArray jArray = jObject["DynamicDate1"] as JArray;
                if (!string.IsNullOrEmpty(jArray[0].ToString()))
                {
                    d1 = DateTime.Parse(jArray[0].ToString());
                    d2 = DateTime.Parse(jArray[1].ToString());
                }

            }

            Dictionary<string, string> bColors = new Dictionary<string, string>();//背景颜色

            while (d2 >= d1)
            {
                //string day = string.Format("yyyy-MM-dd HH:mm:ss.fff", StartDate);
                string day = string.Format("{0:yyyy-MM-dd}", d1);
                string s = string.Empty;



                DataRow[] dataRows = DtDetail.Select("DataDay='" + day + "' AND ID=" + dataRow["ID"] + " ");
