        /// <summary>
        /// 根据订单计算BOM阶层的半成品需求
        /// </summary>
        /// <returns></returns>
        public string CalculationBOMDemandQty()
        {
            bool result = true;
            string msg = "计算成功";
            DataTable dtBom = null;
            try
            {

                jObject = JsonConvert.DeserializeObject(BodyJson) as JObject;

                if (jObject.ContainsKey("OrderNo"))
                {


                    string orderNo = jObject["OrderNo"].ToString();
                    decimal qty = 0;
                    string defaultLineName = "";
                    string WorkOrderTypeID = "";
                    string Extend12 = "";
                    string Code = jObject["Code"].ToString();
                    if (string.IsNullOrEmpty(orderNo))
                    {
                        result = false;
                        msg = "未提供成品订单";

                    }
                    else if (string.IsNullOrEmpty(Code))
                    {
                        result = false;
                        msg = "未提供成品料号";

                    }
                    else
                    {

                        dtBom = SqlHelper.ExecuteDataTable($@"SELECT Row_Number() over(order by a.code) as RowNumber, a.Code,B.Extend12,b.WorkOrderTypeID
, b.ERPStartDate - isnull(a.DaysInAdvance, 0) as ERPStartDate
, b.ERPEndDate - isnull(a.DaysInAdvance, 0) as ERPEndDate
, (Molecule / Denominator) * B.Qty-CASE WHEN ISNULL(B2.APSDemandQty2,0)<0 THEN 0 ELSE B2.APSDemandQty2 END  AS NewQty1
, B.SourceOrderNo
, B.SourceOrderLineNo
, B.DefaultLineName
, B.OrderNo
, '' AS MachineCode
,0 as Status
,'' as NewOrderNo
,'1' as IsNew
,'1' AS IsOK
,a.Spec
,B2.APSDemandQty2
,a.Molecule,a.Denominator,b.DefaultLineName,WorkOrderTypeID

FROM APS_MaterialBOMNew A
LEFT JOIN(
SELECT CODE,WERKS,SUM(APSDemandQty2) AS APSDemandQty2
FROM ERP_MD04Form
 
 GROUP BY CODE,WERKS
) B2 ON A.Code=B2.Code AND A.Factory=B2.WERKS
inner join APS_Order b on b.OrderNo = '{orderNo}' WHERE MasterCode='{Code}'  AND IsScheduling=1  ");

                    }

                }


            }
            catch (Exception ex)
            {
                result = false;
                msg = "数据操作失败,错误信息:" + ex.Message;
            }
            return JsonConvert.SerializeObject(new
            {
                data = dtBom,
                result,
                msg
            });
        }


