                                requestUser.ContentType = "application/json";
                                requestUser.Timeout = 1000 * 2;
                                // request.Headers = new WebHeaderCollection();

                                requestUser.Headers.Add("Authorization", token);




                                //  string s = JsonConvert.SerializeObject(body);
                                buffer = null;


                                requestUser.ContentLength = 0;

                                requestUser.GetRequestStream().Write(buffer, 0, buffer.Length);
                                response = (HttpWebResponse)requestUser.GetResponse();

                                using (StreamReader readerUser = new StreamReader(response.GetResponseStream(), Encoding.UTF8))
                                {

                                    res = readerUser.ReadToEnd();
                                    jObjectResult = JsonConvert.DeserializeObject(res) as JObject;

                                    if (jObjectResult.ContainsKey("account"))
                                    {
                                        account = jObjectResult["account"].ToString();



                                        var obj = V_Dev_Account.CheckDev_Account(account, "", AppInfo.AppCode, true);
                                        if (obj == null && !string.IsNullOrEmpty(account))
