        /// <summary>
        /// 联动排程自动拆单 
        /// </summary>
        /// <returns></returns>
        public string AutoSplitOrder()
        {
            jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;
            result = true;
            allMsg = "拆单成功";
            double totalQty = 0;
            int boxNum = 0;
            double TotalHours = 0;
            int DefaultLineID = 0;
            if (dev_Account == null)
            {
                allMsg = "当前登录信息已经丢失，请刷新页面重新登录";
                result = false;
            }

            else if (jArray.Count == 0)
            {

                allMsg = "未接受到数据";
                result = false;

            }
            else
            {

                JObject jToken = jArray.First() as JObject;
                double qty = int.Parse(jToken["Qty"].ToString());
                double.TryParse(jToken["TotalHours"].ToString(), out TotalHours);
                double Capacity = double.Parse(jToken["Capacity"].ToString());
                double planQty = Math.Ceiling(Capacity * TotalHours);
                DateTime startDate = DateTime.Parse(jToken["ERPStartDate"].ToString());
                int.TryParse(jToken["BoxNum"].ToString(), out boxNum);
                string groupName = jToken["GroupName"].ToString();
                string DefaultLineName = jToken["DefaultLineName"].ToString();
                DefaultLineName = DefaultLineName.Replace('，', ',');
                DateTime endDate = startDate;
                jToken["IsNew"] = "0";
                double SplitNum = 0;
                int dayQty = 0;
                int.TryParse(jToken["DayQty"].ToString(), out dayQty);
                int.TryParse(jToken["DefaultLineID"].ToString(), out DefaultLineID);
                if (!string.IsNullOrEmpty(jToken["SplitNum"].ToString()))
                {
                    SplitNum = double.Parse(jToken["SplitNum"].ToString());
                }

                if (SplitNum < qty && SplitNum > 0)
                {
                    //拆分的数量不等于原始订单数量，则把原单的最新数量更新
                    planQty = qty - SplitNum;

                }
                else
                {
                    //拆单数量等于原单数量


                    if (boxNum > 0)
                    {
                        planQty = Math.Ceiling(planQty / boxNum) * boxNum;

                    }

                }



                if (dayQty > 0)
                {
                    planQty = dayQty;
                }
                if (planQty > qty)
                {
                    planQty = qty;
                }
                jToken["NewQty1"] = planQty;
                int index = 10;
                jToken["seq"] = (index).ToString().PadLeft(4, '0');
                jArray = new JArray();

                qty -= planQty;

                string organizeCondition = DefaultLineID > 0 ? $"AND A.OrganizeID = {DefaultLineID}" : "";
                DataTable dtWork = SqlHelper.ExecuteDataTable($@"SELECT distinct  workingdate
FROM APS_OrganizeWorkingTimesDetail A
inner join dev_organize b on a.organizeid=b.organizeid and b.groupname='{groupName}'
WHERE WORKINGDATE>='{startDate}'
AND WORKINGDATE<=dateadd(day,120,'{startDate}')
{organizeCondition}");
                bool isFirst = true;
                while (qty > 0)
                {
                    bool isFirstLine = true;
                    foreach (string lineName in DefaultLineName.Split(','))
                    {
                        if (isFirst)
                        {//第一条记录是
                            isFirst = false;
                            jToken["DefaultLineName"] = lineName;
                            jArray.Add(jToken);
                            continue;

                        }
                        planQty = Math.Ceiling(Capacity * TotalHours);
                        if (boxNum > 0)
                        {
                            planQty = Math.Ceiling(planQty / boxNum) * boxNum;

                        }

                        if (dayQty > 0)
                        {
                            planQty = dayQty;
                        }
                        //if (qty < Capacity * 10)
                        //{
                        //    planQty = qty;
                        //}
                        if (planQty > qty)
                        {
                            planQty = qty;
                        }
                        if (planQty > 0)
                        {
                            JToken keyValuePairs = jToken.DeepClone();
                            keyValuePairs["NewQty1"] = int.Parse(planQty.ToString()).ToString();

                            keyValuePairs["IsNew"] = "1";
                            keyValuePairs["ERPStartDate"] = string.Format("{0:yyyy-MM-dd}", startDate);
                            // 获取下一个工作日
                            DataRow[] dataRows1 = dtWork.Select($"workingdate > '{startDate}'", "workingdate");
                            if (dataRows1.Length > 0)
                            {
                                // 找到了下一个有效的工作日
                                keyValuePairs["ERPEndDate"] = string.Format("{0:yyyy-MM-dd}", dataRows1[0]["workingdate"].ToString());
                            }
                            else
                            {
                                // 如果没有找到下一个工作日，fallback到当前 startDate
                                keyValuePairs["ERPEndDate"] = string.Format("{0:yyyy-MM-dd}", startDate.AddDays(1));
                            }
                            keyValuePairs["seq"] = (index).ToString().PadLeft(4, '0');
                            keyValuePairs["DefaultLineName"] = lineName;
                            //  keyValuePairs["MachineCode"] = keyValuePairs["MachineCode"].ToString();
                            jArray.Add(keyValuePairs);
                            qty -= planQty;
                            totalQty += planQty;
                        }


                    }
                    startDate = startDate.AddDays(1);
                    DataRow[] dataRows = dtWork.Select("workingdate>='" + startDate + "'", "workingdate");
                    if (dataRows.Length > 0)
                    {

                        startDate = DateTime.Parse(dataRows[0]["workingdate"].ToString());
                    }
                    index += 10;
                    endDate = startDate;

                    if (startDate.DayOfWeek == DayOfWeek.Sunday)
                    {
                        startDate = startDate.AddDays(1);
                    }

                }

            }
            return JsonConvert.SerializeObject(new
            {

                result,
                totalQty = string.Format("{0:G0}", totalQty),
                data = jArray,
                msg = allMsg
            }); ;
        }

        /// <summary>
        /// 注塑+SMT需求自动创单计算
        /// </summary>
        /// <returns></returns>
        public string AutoSplitOrderByCode()
        {
            jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;
            result = true;
            allMsg = "分析成功";
            double totalQty = 0;
            int boxNum = 0;
            double TotalHours = 0;
            JArray jArrayNew = new JArray();
            if (dev_Account == null)
            {
                allMsg = "当前登录信息已经丢失，请刷新页面重新登录";
                result = false;
            }

            else if (jArray.Count == 0)
            {

                allMsg = "未接受到数据";
                result = false;

            }
            else
            {
                int r = 0;

                foreach (JObject jObject in jArray)
                {
                    r++;
                    if (jObject["MachineCode"].ToString() == "")
                    {
                        allMsg = $"第{r}行未选则计数器";
                        result = false;
                        continue;
                    }

                    double qty = int.Parse(jObject["CreationQty"].ToString());
                    double.TryParse(jObject["TotalHours"].ToString(), out TotalHours);
                    double Capacity = double.Parse(jObject["Capacity"].ToString());
                    double planQty = Capacity * TotalHours;
                    DateTime startDate = DateTime.Parse(jObject["OweDay"].ToString());
                    startDate = startDate.AddDays(-4);
                    if (startDate < DateTime.Now.Date)
                    {
                        startDate = DateTime.Now.Date;
                    }
                    string DefaultLineName = jObject["DefaultLineName"].ToString();
                    DefaultLineName = DefaultLineName.Replace('，', ',');
                    DateTime endDate = startDate;
                    // jObject["IsNew"] = "1";




                    //if (planQty > qty)
                    //{
                    //    planQty = qty;
                    //}
                    //jObject["NewQty1"] = planQty;

                    //qty -= planQty;
                    //  jArray = new JArray();
                    int index = 10;
                    bool isFirst = true;
                    while (qty > 0)
                    {
                        bool isFirstLine = true;
                        foreach (string lineName in DefaultLineName.Split(','))
                        {

                            planQty = Math.Ceiling(Capacity * TotalHours);
                            if (boxNum > 0)
                            {
                                planQty = Math.Ceiling(planQty / boxNum) * boxNum;

                            }


                            //if (qty < Capacity * 10)
                            //{
                            //    planQty = qty;
                            //}
                            if (planQty > qty)
                            {
                                planQty = qty;
                            }
                            if (planQty > 0)
                            {
                                JToken keyValuePairs = jObject.DeepClone();
                                keyValuePairs["NewQty1"] = planQty;

                                keyValuePairs["IsNew"] = "1";
                                // if (index == 10)
                                {
                                    keyValuePairs["ERPStartDate"] = string.Format("{0:yyyy-MM-dd}", startDate);
                                }

                                keyValuePairs["ERPEndDate"] = string.Format("{0:yyyy-MM-dd}", startDate.AddDays(0));
                                keyValuePairs["seq"] = (index).ToString().PadLeft(4, '0');
                                keyValuePairs["DefaultLineName"] = lineName;
                                keyValuePairs["MachineCode"] = jObject["MachineCode"].ToString();
                                jArrayNew.Add(keyValuePairs);
                                qty -= planQty;
                                totalQty += planQty;
                            }


                        }
                        startDate = startDate.AddDays(1);
                        index += 10;
                        endDate = startDate;

                        if (startDate.DayOfWeek == DayOfWeek.Sunday)
                        {
                            startDate = startDate.AddDays(1);
                        }

                    }

                }
            }
            return JsonConvert.SerializeObject(new
            {

                result,
                totalQty = string.Format("{0:G0}", totalQty),
                data = jArrayNew,
                msg = allMsg
            }); ;
        }
