        /// <summary>
        /// 订单暂停/恢复
        /// </summary>
        /// <returns></returns>
        public string UpdateOrderStatusByOrderID()
        {
            bool result = true;
            string msg = "操作成功";
            string orderIds = "0";
            string productionStatus = string.Empty;
            try
            {
                jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;
                string strSQL = string.Empty;
                foreach (JObject jObject in jArray)
                {
                    if (!string.IsNullOrEmpty(jObject["OrderID"].ToString()) && !string.IsNullOrWhiteSpace(jObject["ProductionStatus"].ToString()))
                    {

                        // 订单状态 暂停：24，恢复：21
                        productionStatus = jObject["ProductionStatus"].ToString();
