        public void SetDt5610(ref DataTable dt)
        {

            if (jObject["DemandDate"] == null)
            {
                return;
            }

            DateTime startDate = Convert.ToDateTime(DateTime.Now.ToString("yyyy-MM-dd"));
            DateTime endDate = startDate.AddDays(5).AddDays(-1);
            string where = " 1=1 ";
            JArray jArray = jObject["DemandDate"] as JArray;
            if (jArray != null)
            {

                if (!string.IsNullOrEmpty(jArray[0].ToString()))
                {
                    startDate = DateTime.Parse(jArray[0].ToString());
                }
                if (jArray.Count > 1 && !string.IsNullOrEmpty(jArray[1].ToString()))
                {
                    endDate = DateTime.Parse(jArray[1].ToString());
                }
            }

            if (jObject["OweQty"] != null)
            {
                if (!string.IsNullOrEmpty(jObject["OweQty"].ToString()))
                {
                    if (jObject["OweQty"].ToString() == "0")
                    {
                        where += " and a.OweQty<0";
                    }
                }
            }

            if (jObject["OweQty"] != null)
            {
                if (!string.IsNullOrEmpty(jObject["OweQty"].ToString()))
                {
                    if (jObject["OweQty"].ToString() == "0")
                    {
                        where += " and a.OweQty<0";
                    }
                }
            }

            if (jObject["Code"] != null)
            {
                if (!string.IsNullOrEmpty(jObject["Code"].ToString()))
                {

                    where += " and a.Code like '%" + jObject["Code"].ToString() + "%'";

                }
            }

            if (jObject["MaterialName"] != null)
            {
                if (!string.IsNullOrEmpty(jObject["MaterialName"].ToString()))
                {

                    where += " and a.MaterialName like '%" + jObject["MaterialName"].ToString() + "%'";

                }
            }


            if (jObject["Spec"] != null)
            {
                if (!string.IsNullOrEmpty(jObject["Spec"].ToString()))
                {

                    where += " and a.Spec like '%" + jObject["Spec"].ToString() + "%'";

                }
            }


            if (jObject["Extend4"] != null)
            {
                if (!string.IsNullOrEmpty(jObject["Extend4"].ToString()))
                {

                    where += " and b.Extend4 = '" + jObject["Extend4"].ToString() + "'";

                }
            }

            if (jObject["Extend1"] != null)
            {
                if (!string.IsNullOrEmpty(jObject["Extend1"].ToString()))
                {

                    where += " and a.Extend1 = '" + jObject["Extend1"].ToString() + "'";

                }
            }










            dt = SqlHelper.ExecuteDataTable(string.Format(@"
            select a.Extend1,b.Extend4,a.MaterialID,a.Code,a.MaterialName,a.Spec,sum(a.DemandQty) DemandQty,sum(a.OweQty) OweQty,sum(a.OnloadQty) OnloadQty,sum(a.OncheckQty) OncheckQty ,(SELECT Sum(StockQty)
              FROM   V_WMS_StockForActive where MaterialID=a.MaterialID
              GROUP  BY MaterialID) as StockQty
from APS_OrderPlanMaterialForm  a
left join APS_Order b on a.orderid=b.orderid
where a.DemandDate>='{0}' and a.DemandDate<='{1}' and {2}
group by a.MaterialID,a.Code,a.MaterialName,a.Spec,b.Extend4,a.Extend1", startDate, endDate, where));


        }

        /// <summary>
