        public void SetDt25485(ref DataTable dt)
        {





            DateTime startDate = DateTime.Now.Date;
            DateTime endDate = startDate.AddDays(30);
            if (jObject.ContainsKey("DynamicDate1"))
            {
                JArray jArray = jObject["DynamicDate1"] as JArray;
