        /// <summary>
        /// 销售订单出货计划
        /// </summary>
        /// <param name="dataRow"></param>
        public void setDetail25485(DataRow dataRow)
        {
            DateTime startDate = DateTime.Now.Date;
            DateTime endDate = startDate.AddDays(30);
            if (jObject.ContainsKey("DynamicDate1"))
            {
                JArray jArray = jObject["DynamicDate1"] as JArray;
                if (!string.IsNullOrEmpty(jArray[0].ToString()))
                {
                    startDate = DateTime.Parse(jArray[0].ToString());
                    endDate = DateTime.Parse(jArray[1].ToString());
                }
            }

            Dictionary<string, string> bColors = new Dictionary<string, string>();
            DateTime currentDate = startDate;

            while (currentDate <= endDate)
            {
                string day = currentDate.ToString("yyyy-MM-dd");
                DataRow[] rows = DtDetail.Select("DeliveryDate='" + day + "' AND SalesOrderDetailID='" + dataRow["SalesOrderDetailID"] + "'");
                if (rows.Length > 0)
                {
                    dataRow[day] = rows[0]["Qty"];
                }

                currentDate = currentDate.AddDays(1);
            }

            dataRow["BColors"] = bColors;
        }
        public string SaveData125485()
        {
            bool result = false;
            string msg = "";
            List<string> errorMessages = new List<string>();

            try
            {
                JArray jArrayData = JsonConvert.DeserializeObject<JArray>(BodyJson);
                if (jArrayData == null)
                {
                    allMsg = "未接收到数据，请确认是否为JSON格式";
                    return JsonConvert.SerializeObject(new { result = false, msg = allMsg });
                }

                if (dev_Account == null)
                {
                    allMsg = "当前登录信息已经丢失，请刷新页面重新登录";
                    return JsonConvert.SerializeObject(new { result = false, msg = allMsg });
                }

                SaveData();

                // 1. 收集所有SalesOrderDetailID
                var salesOrderDetailIds = new List<string>();
                foreach (JObject obj in jArrayData)
                {
                    string salesOrderDetailID = obj["SalesOrderDetailID"]?.ToString();
                    if (!string.IsNullOrEmpty(salesOrderDetailID) && !salesOrderDetailIds.Contains(salesOrderDetailID))
                    {
                        salesOrderDetailIds.Add(salesOrderDetailID);
                    }
                }

                if (salesOrderDetailIds.Count == 0)
                {
                    allMsg = "未找到有效的SalesOrderDetailID";
                    return JsonConvert.SerializeObject(new { result = false, msg = allMsg });
                }

                string idList = string.Join(",", salesOrderDetailIds.Select(id => $"'{id.Replace("'", "''")}'"));

                // 2. 获取订单信息和现有计划
                DataTable orderInfo = SqlHelper.ExecuteDataTable($@"
SELECT [SalesOrderDetailID], [Qty], [SalesOrderNo]
FROM [V_APS_SalesOrderDetailForLine] 
WHERE SalesOrderDetailID IN ({idList})");

                DataTable existingPlans = SqlHelper.ExecuteDataTable($@"
SELECT [SalesOrderDetailID], [DeliveryDate], [Qty], [ID]
FROM [APS_SalesOrderDetailPlanLine]
WHERE DeliveryDate >= CAST(GETDATE() AS DATE)
  AND SalesOrderDetailID IN ({idList})");

                // 3. 构建字典用于快速查找
                var orderDict = new Dictionary<string, (decimal Qty, string SalesOrderNo)>();
                var existingPlanDict = new Dictionary<string, Dictionary<DateTime, (string ID, decimal Qty)>>();

                // 订单信息
                foreach (DataRow row in orderInfo.Rows)
                {
                    string salesOrderDetailID = row["SalesOrderDetailID"].ToString();
                    decimal qty = Convert.ToDecimal(row["Qty"]);
                    string salesOrderNo = row["SalesOrderNo"].ToString();
                    orderDict[salesOrderDetailID] = (qty, salesOrderNo);
                }

                // 现有计划
                foreach (DataRow row in existingPlans.Rows)
                {
                    string salesOrderDetailID = row["SalesOrderDetailID"].ToString();
                    DateTime deliveryDate = Convert.ToDateTime(row["DeliveryDate"]);
                    decimal qty = Convert.ToDecimal(row["Qty"]);
                    string id = row["ID"].ToString();

                    if (!existingPlanDict.ContainsKey(salesOrderDetailID))
                    {
                        existingPlanDict[salesOrderDetailID] = new Dictionary<DateTime, (string, decimal)>();
                    }
                    existingPlanDict[salesOrderDetailID][deliveryDate] = (id, qty);
                }

                // 4. 生成SQL和验证逻辑
                StringBuilder sqlBuilder = new StringBuilder();
                int recordCounter = 1;

                // 先为每个订单单独处理，避免交叉影响
                foreach (JObject obj in jArrayData)
                {
                    string salesOrderDetailID = obj["SalesOrderDetailID"]?.ToString();
                    if (string.IsNullOrEmpty(salesOrderDetailID))
                        continue;

                    // 检查订单是否存在
                    if (!orderDict.ContainsKey(salesOrderDetailID))
                    {
                        errorMessages.Add($"订单明细ID {salesOrderDetailID} 不存在");
                        continue;
                    }

                    var (orderQty, salesOrderNo) = orderDict[salesOrderDetailID];

                    // 获取该订单现有的所有计划（排除今天之前的）
                    decimal existingTotal = 0;
                    if (existingPlanDict.ContainsKey(salesOrderDetailID))
                    {
                        foreach (var kvp in existingPlanDict[salesOrderDetailID])
                        {
                            if (kvp.Key >= DateTime.Today)
                            {
                                existingTotal += kvp.Value.Item2; // 累加现有数量
                            }
                        }
                    }

                    // 提取JSON中的所有日期键（格式：yyyy-MM-dd）
                    var dateProperties = obj.Properties()
                        .Where(p => DateTime.TryParseExact(p.Name, "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out _))
                        .Select(p => new
                        {
                            Date = DateTime.ParseExact(p.Name, "yyyy-MM-dd", CultureInfo.InvariantCulture),
                            QtyStr = p.Value.ToString()
                        })
                        .Where(x => !string.IsNullOrEmpty(x.QtyStr))
                        .ToList();

                    // 创建一个临时字典来计算新总数
                    var updatedQuantities = new Dictionary<DateTime, decimal>();

                    foreach (var item in dateProperties)
                    {
                        if (decimal.TryParse(item.QtyStr, NumberStyles.Number, CultureInfo.InvariantCulture, out decimal qty))
                        {
                            updatedQuantities[item.Date] = qty;
                        }
                    }

                    // 重新计算更新后的总数量
                    decimal newTotal = 0;
                    foreach (var date in updatedQuantities.Keys)
                    {
                        // 如果该日期已有计划，用新值替换旧值
                        // 如果该日期没有计划，直接加新值
                        newTotal += updatedQuantities[date];
                    }

                    // 对于JSON中没有提到的日期，保留原有计划数量
                    if (existingPlanDict.ContainsKey(salesOrderDetailID))
                    {
                        foreach (var kvp in existingPlanDict[salesOrderDetailID])
                        {
                            DateTime existingDate = kvp.Key;
                            decimal existingQty = kvp.Value.Item2;

                            // 只保留今天及以后的日期，且JSON中没有提到这个日期
                            if (existingDate >= DateTime.Today && !updatedQuantities.ContainsKey(existingDate))
                            {
                                newTotal += existingQty;
                            }
                        }
                    }

                    // 检查总数是否超限
                    if (newTotal > orderQty)
                    {
                        decimal exceedAmount = newTotal - orderQty;
                        errorMessages.Add($"订单 {salesOrderNo} 的交货需求数量({newTotal})超过订单数量({orderQty})，超出{exceedAmount}");
                        continue;
                    }

                    // 处理每个日期的数据（验证通过后才生成SQL）
                    foreach (var item in dateProperties)
                    {
                        DateTime deliveryDate = item.Date;
                        string qtyStr = item.QtyStr;

                        if (!decimal.TryParse(qtyStr, NumberStyles.Number, CultureInfo.InvariantCulture, out decimal qty))
                        {
                            qty = 0;
                        }

                        // 检查该日期是否已有计划
                        bool exists = existingPlanDict.ContainsKey(salesOrderDetailID) &&
                                      existingPlanDict[salesOrderDetailID].ContainsKey(deliveryDate);

                        if (qty > 0)
                        {
                            if (!exists)
                            {
                                // 插入新记录
                                string newId = $"{DateTime.Now:yyyyMMddHHmmss}{recordCounter++:000}";
                                sqlBuilder.Append($@"
INSERT INTO [dbo].[APS_SalesOrderDetailPlanLine]
    ([ID], [SalesOrderDetailID], [DeliveryDate], [Qty], [Status], 
     [CreatedBy], [CreatedByName], [CreatedOn])
SELECT '{newId}', '{salesOrderDetailID}', '{deliveryDate:yyyy-MM-dd}', {qty}, 1,
       '{dev_Account.Account}', '{dev_Account.Name}', GETDATE()
WHERE NOT EXISTS (
    SELECT 1 FROM [APS_SalesOrderDetailPlanLine] 
    WHERE [SalesOrderDetailID] = '{salesOrderDetailID}' 
      AND [DeliveryDate] = '{deliveryDate:yyyy-MM-dd}'
);");
                            }
                            else
                            {
                                // 更新现有记录
                                string existingId = existingPlanDict[salesOrderDetailID][deliveryDate].Item1;
                                sqlBuilder.Append($@"
UPDATE [APS_SalesOrderDetailPlanLine]
SET [Qty] = {qty},
    [ModifyedOn] = GETDATE(),
    [ModifiedBy] = '{dev_Account.Account}',
    [ModifiedByName] = '{dev_Account.Name}'
WHERE [ID] = '{existingId}';");
                            }
                        }
                        else
                        {
                            // 数量为0或空，删除记录（如果存在的话）
                            sqlBuilder.Append($@"
DELETE FROM [APS_SalesOrderDetailPlanLine]
WHERE [SalesOrderDetailID] = '{salesOrderDetailID}'
  AND [DeliveryDate] = '{deliveryDate:yyyy-MM-dd}'
  AND [DeliveryDate] >= CAST(GETDATE() AS DATE);");
                        }
                    }
                }

                // 5. 执行SQL
                if (errorMessages.Count > 0)
                {
                    result = false;
                    allMsg = string.Join("；", errorMessages);
                }
                else if (sqlBuilder.Length > 0)
                {
                    try
                    {
                        // 方案A：使用现有SqlHelper的简单版本（无事务）
                        SqlHelper.ExecuteNonQuery(SqlHelper.MSSQLConnectionString, CommandType.Text, sqlBuilder.ToString());
                        result = true;
                        allMsg = "保存成功";
                    }
                    catch (Exception ex)
                    {
                        allMsg = "保存失败：" + ex.Message;
                        result = false;
                    }
                }
                else
                {
                    result = true;
                    allMsg = "没有需要保存的数据";
                }
            }
            catch (Exception ex)
            {
                allMsg = ex.Message;
                result = false;
            }

            return JsonConvert.SerializeObject(new
            {
                result,
                msg = allMsg
            });
        }
