            }


            try
            {
                StringBuilder sql = new StringBuilder();

                foreach (JObject obj in jArray)
                {
                    string code = obj["Code"]?.ToString() ?? "";


                    //不用判断了，先执行删除语句
                    sql.Append($@"DELETE A FROM APS_OrderPlanMaterialFormSaveInfo A INNER JOIN APS_Material B ON A.MaterialID = B.MaterialID Where A.DataSource = 'APS' AND B.Code = '{code}'");
                    //然后直接插
                    sql.Append($@"INSERT INTO APS_OrderPlanMaterialFormSaveInfo
                    (
                        MaterialID,
                        DataSource,
                        CreatedBy,
                        CreatedByName,
                        CreatedOn
                    )
                    SELECT A.MaterialID,
                        'APS',
                        '{dev_Account.Account}',
                        '{dev_Account.Name}',
                         GETDATE()
                        FROM APS_Material A   
                        Where  A.Code = '{code}'
                         ");
                }
                SqlHelper.ExecuteNonQuery(sql.ToString());

            }
            catch (Exception ex)
            {
                result = false;
                msg = "数据操作失败,错误信息:" + ex.Message;

            }
            ApsLegacyJsonResult = base.FormResult(result, msg, null);
            return ApsLegacyJsonResult;
        }
