                }
                else
                {
                    SaveData();
                    string workShopID = jArray[0]["WorkShopID"].ToString();
                    string processPartName = jArray[0]["ProcessPartName"].ToString();
                    string flag = jArray[0]["Flag"].ToString();
                    string type = jArray[0]["Type"].ToString();
                    SqlParameter[] sqlParameters = new SqlParameter[6];
                    sqlParameters[0] = new SqlParameter("@WorkShopID", workShopID);//车间
                    sqlParameters[1] = new SqlParameter("@ProcessPartName", processPartName);//工段名称
                    sqlParameters[2] = new SqlParameter("@Flag", flag);//标记状态，0代表只有半成品，1代表成和半成品混用
                    sqlParameters[3] = new SqlParameter("@Type", type);//操作方式，0重排，1排产
                    sqlParameters[4] = new SqlParameter("@Result", SqlDbType.Bit);//结果
                    sqlParameters[5] = new SqlParameter("@Msg", SqlDbType.NVarChar, 500);//信息
                    sqlParameters[4].Direction = sqlParameters[5].Direction = ParameterDirection.Output;
                    SqlHelper.ExecuteNonQuery(SqlHelper.MSSQLConnectionString, "P_APS_CalculateProcessPlan", sqlParameters);
                    result = sqlParameters[4].Value.ToString().ToLower() == "true";
