        /*
         * EK 马来欠料页面 生成调拨单按钮
         * 生成调拨单
         */
        public string K3ColudTransferDirect()
        {
            bool result = true;
            string msg = "数据处理完成";
            List<K3.BillEntryItem> items = new List<K3.BillEntryItem>();
            KingdeeResponse response = null;
            try
            {
                jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;

                if (jArray == null || jArray.Count == 0)
                {
                    msg = "未接受到数据，请确认是否为JSON格式";
                    result = false;
                }
                else
                {
                    var itemDict = new Dictionary<string, K3.BillEntryItem>();
                    foreach (JObject jObject in jArray)
                    {
                        var warehouseCode = jObject["WarehouseCode"]?.ToString()?.Trim();
                        var materialId = jObject["Code"]?.ToString()?.Trim();
                        var oweQtyStr = jObject["MalaysiaOweQty2"]?.ToString()?.Trim();
                        var Codekey = warehouseCode + "_" + materialId;
                        if (string.IsNullOrEmpty(warehouseCode) ||
                            string.IsNullOrEmpty(materialId) ||
                            string.IsNullOrEmpty(oweQtyStr) ||
                            !double.TryParse(oweQtyStr, out double oweQty) ||
                            oweQty == 0.0)
                        {
                            continue;
                        }

                        if (itemDict.TryGetValue(Codekey, out K3.BillEntryItem existingItem))
                        {
                            // 已存在，累加数量
                            existingItem.FQty += oweQty;
                        }
                        else
                        {
                            // 不存在，新建
                            itemDict[Codekey] = new K3.BillEntryItem
                            {
                                FSrcStockId = warehouseCode,
                                FDestStockId = "M999",
                                FMaterialId = materialId,
                                FQty = oweQty
                            };
                        }
                    }
                    items = itemDict.Values.ToList();

                    var groups = items.GroupBy(x => x.FSrcStockId);

                    foreach (var group in groups)
                    {
                        //Console.WriteLine($"仓库ID: {group.Key}");
                        //foreach (var item in group)
                        //{
                        //}

                        //Console.WriteLine($"    物料: {item.FMaterialId}");
                        response = K3.TransferDirect(group.ToList());
                        var ResponseStatus = response.Result.ResponseStatus;
                        if (ResponseStatus.IsSuccess)
                        {
                            ResponseStatus.SuccessEntitys.ForEach(m => msg += "  仓库:" + group.Key + " 物料:" + string.Join(",", group.ToList().Select(x => x.FMaterialId)) + " 操作成功。");
                        }
                        else
                        {
                            result = false;
                            //msg = "操作失败，错误信息：";
                            //ResponseStatus.Errors.ForEach(m => msg += m.Message + ";");
                            ResponseStatus.Errors.ForEach(m => msg += "  仓库:" + group.Key + " 物料:" + string.Join(",", group.ToList().Select(x => x.FMaterialId)) + " 操作失败:" + m.Message);
                        }
                    }

                }
            }
            catch (Exception ex)
            {
                result = false;
                msg = "数据操作失败,错误信息:" + ex.Message;
            }
            return JsonConvert.SerializeObject(new { result, msg, response, items });
        }

        /*
         * EK  备料计划页面---订单下达按钮
         * 订单下达
         * */
        public string orderToStart()
        {
            bool result = true;
            string msg = "数据处理成功";
            string orderNos = "";
            KingdeeResponse response = null;
            try
            {
                jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;

                if (jArray == null || jArray.Count == 0)
                {
                    msg = "未接受到数据，请确认是否为JSON格式";
                    result = false;
                }
                else
                {
                    //“'A','B','C'”
                    orderNos = string.Join("','", jArray.Select(j => j["OrderNo"].ToString()));
                    if (orderNos.Length > 0)
                    {
                        orderNos = "'" + orderNos + "'";
                    }
                    response = K3.ToStart(orderNos);
                    var ResponseStatus = response.Result.ResponseStatus;
                    if (ResponseStatus.IsSuccess)
                    {
                        msg = "操作成功";
                    }
                    else
                    {
                        result = false;
                        msg = "操作失败，错误信息：";
                        ResponseStatus.Errors.ForEach(m => msg += m.Message + ";");
                    }
                }
            }
            catch (Exception ex)
            {
                result = false;
                msg = "数据操作失败,错误信息:" + ex.Message;
            }
            return JsonConvert.SerializeObject(new { result, msg, response, orderNos });
        }

        /*
          EK 组柜按钮  传上来柜号自动生成柜号
         */
        public string PalletAddCabinetNo()
        {
            bool result = false;
            string msg = "";
            string detailMsg = "";
            try
            {
                // === 1. 解析输入 BodyJson ===
                if (string.IsNullOrWhiteSpace(BodyJson))
                    throw new ArgumentException("输入数据为空");

                var jArray = JsonConvert.DeserializeObject(BodyJson) as JArray
                             ?? throw new ArgumentException("数据格式异常：不是有效的 JSON 数组");

                var PalletNos = jArray
                    .OfType<JObject>()
                    .Select(j => j["PalletNo"]?.ToString()?.Trim())
                    .Where(code => !string.IsNullOrEmpty(code))
                    .Distinct()
                    .ToList();

                // === 3. 生成柜号 ===
                string CabinetNo = SqlHelper.GetKeyValue("柜号", "GH", "02");

                SqlHelper.ExecuteNonQuery(
                string.Format(@"
                  UPDATE A
                  SET A.CabinetNo = '{0}'
                  FROM [dbo].[WMS_Pallet] A
                  WHERE A.PalletNo IN ('{1}')
                     ",
                    CabinetNo,
                    string.Join("','", PalletNos))
                );
                result = true;
                msg = "组柜成功！";
                detailMsg = "组柜成功，柜号为：" + CabinetNo;
            }
            catch (ArgumentException ex)
            {
                result = false;
                detailMsg = $"参数错误: {ex.Message}";
            }
            catch (Exception ex)
            {
                result = false;
                detailMsg = $"系统异常: {ex.Message}";
            }
            return JsonConvert.SerializeObject(new
            {
                result,
                msg,
                detailMsg
            });
        }

        /*
         * EK 推送栈板信息到OA
        */
        public string PalletPushOA()
        {
            bool result = false;
            string msg = "";
            string detailMsg = "";
            string oaResponse = "";
            object requestBodyObj = null;
            string requestBodyJson = "";
            try
            {
                // === 1. 解析输入 BodyJson ===
                if (string.IsNullOrWhiteSpace(BodyJson))
                    throw new ArgumentException("输入数据为空");

                var jArray = JsonConvert.DeserializeObject(BodyJson) as JArray
                             ?? throw new ArgumentException("数据格式异常：不是有效的 JSON 数组");

                var CabinetNos = jArray
                    .OfType<JObject>()
                    .Select(j => j["CabinetNo"]?.ToString()?.Trim())
                    .Where(code => !string.IsNullOrEmpty(code))
                    .Distinct()
                    .ToList();

                if (!CabinetNos.Any())
                {
                    msg = "未找到有效的柜号";
                    throw new ArgumentException("未找到有效的柜号");
                }
                if (CabinetNos.Count > 1)
                {
                    msg = "一次只能推送一个柜号";
                    throw new ArgumentException("一次只能推送一个柜号");
                }

                // === 2. 查询栈板数据 === 按照柜号排序
                string sqlPallet = $@"
                    SELECT PalletNo, CabinetNo,Remark1,FORMAT(EstimatedShippingDate, 'yyyy-MM-dd') AS EstimatedShippingDate,ShipmentMode,IsDangerous,BoxNo
                    FROM V_WMS_Pallet 
                    WHERE NoticeNo IS NULL AND Status = 1 AND CabinetNo IN ('{string.Join("','", CabinetNos)}')
                    ORDER BY CabinetNo
                 ";  //查找未被下通知的柜号  

                DataTable palletTable = SqlHelper.ExecuteDataTable(sqlPallet);

                if (palletTable.Rows.Count == 0)
                {
                    throw new InvalidOperationException("上传的柜号中，未找到符合条件的栈板数据");
                }
                //查询柜号下的所有栈板列表
                List<string> palletNoList = palletTable.AsEnumerable()
                                    .Select(row => row.Field<string>("PalletNo"))
                                    .ToList();

                //校验wms的条码状态 是否卡住  直接在后台校验
                string sqlReel = $@"
                  SELECT Reel_Code,REEL_STATUS,REEL_STATUS_NAME
                  FROM   Openquery(WMSTEST, 'select * from  V_PALLET_REEL  ') AS A
                  where A.pallet_no in ('{string.Join("','", palletNoList)}')
                  and reel_status!=1
                 ";

                DataTable ReelCodeTable = SqlHelper.ExecuteDataTable(sqlReel);

                if (ReelCodeTable.Rows.Count > 0)
                {
                    List<string> ReelCodeList = ReelCodeTable.AsEnumerable()
                        .Select(row => row.Field<string>("Reel_Code"))
                        .ToList();
                    msg = "条码状态异常,条码如下:" + string.Join(",", ReelCodeList);
                    var ReelCodeTableList = ReelCodeTable.AsEnumerable().Select(row =>
                        ReelCodeTable.Columns.Cast<DataColumn>().ToDictionary(
                            col => col.ColumnName,
                            col => row[col]
                        )
                    ).ToList();
                    throw new InvalidOperationException("条码状态异常:" + ReelCodeTableList.ToJSON());//记录详细状态
                }

                //msg = "已主动结束运行！！！";
                //throw new InvalidOperationException("已主动结束运行！！！" + palletNoList.ToJSON());

                // === 新增：从结果中提取“实际有栈板的柜号”（去重）===
                var validCabinetNos = palletTable.AsEnumerable()
                    .Select(row => row.Field<string>("CabinetNo"))
                    .Where(c => !string.IsNullOrEmpty(c))
                    .Distinct()
                    .ToList();

                // === 3. 生成通知单号 ===
                string billNo = SqlHelper.GetKeyValue("栈板", "ZB", "02");

                // === 4. 构造 mainData 和 detailData ===
                var mainData = new[]
                    {
                        new { fieldName = "tzdh", fieldValue = billNo },
                        new { fieldName = "tzsj",     fieldValue = DateTime.Now.ToString("yyyy-MM-dd") },
                        new { fieldName = "hjhg",     fieldValue = validCabinetNos.Count.ToString() },// 只统计有栈板的柜子
                        new { fieldName = "zgh",     fieldValue = string.Format(@"'{0}'",string.Join("','",validCabinetNos))},// 只统计有栈板的柜子
                        new { fieldName = "hjzb",     fieldValue = palletTable.Rows.Count.ToString() },
                        new { fieldName = "tzr",     fieldValue = dev_Account.Name }//这边的APS用户名作为通知人 溯源
                    };

                // 构造 detailData（每个栈板一行）
                var workflowRecords = palletTable.AsEnumerable()
                    .Select(row =>
                    {
                        string palletNo = row.Field<string>("PalletNo") ?? "";
                        string cabinetNo = row.Field<string>("CabinetNo") ?? "";
                        string Remark1 = row.Field<string>("Remark1") ?? "";
                        string EstimatedShippingDate = row.Field<string>("EstimatedShippingDate") ?? "";
                        string ShipmentMode = row.Field<string>("ShipmentMode") ?? "";
                        string IsDangerous = row.Field<string>("IsDangerous") ?? "";
                        string BoxNo = row.Field<string>("BoxNo") ?? "";
                        return new
                        {
                            workflowRequestTableFields = new[]
                            {
                                new { fieldName = "zbh", fieldValue = palletNo },
                                new { fieldName = "gh",  fieldValue = cabinetNo },
                                new { fieldName = "zbsl", fieldValue = "1" },
                                new { fieldName = "bz",  fieldValue = Remark1 },
                                new { fieldName = "yqchsj",  fieldValue = EstimatedShippingDate },
                                new { fieldName = "chfs",  fieldValue = ShipmentMode },
                                new { fieldName = "sfwxp",  fieldValue = IsDangerous },
                                new { fieldName = "xh",  fieldValue = BoxNo }
                            }
                        };
                    })
                    .ToArray();

                var detailData = new[]
                {
                    new
                    {
                        tableDBName = "formtable_main_571_dt1",
                        workflowRequestTableRecords = workflowRecords
                    }
                };

                // === 5. 构造完整请求体 ===
                requestBodyObj = new
                {
                    requestName = "马来物料组柜完成通知",
                    workflowId = 858,
                    mainData,
                    detailData
                };

                //暂时保留，后面可能有用
                //string pemPublicKey = @"-----BEGIN PUBLIC KEY-----
                //MIIBIjANBgkqhkiG9w0BAQEFAAOCAQ8AMIIBCgKCAQEAppH1v79PU7272esoD+iB
                //GhmJ+Zprs6HF0/n9B01oCRv63+Mo52oMj4gp1PuufvPaqmgFBJ0o9fcLU7PPVjj4
                //2qnzJ+sjHf9l7Yrq8YKhsxh52Zlbd0zQCtzGPCgUcvV0leOvdS3GmDsU5lcmA0ek
                //IEyPDQqDUAKqSWVho/YlJ7edtcm0Ho+6SQszOtAHvqoEqfZgyxQ5/Wurb/NbFgz4
                //j5fKRn21+aa2pULeG8jLzSKgO//2HyVzP4t/s05+RLjEbaH7MAhAyL9uCLfrRhq2
                //CmECxm90C8lRglnUO4getUG/9fRByVQKBgA5oxs4v8Rc/h2h0PR1LK/WJT0XcNIc
                //fwIDAQAB
                //-----END PUBLIC KEY-----";
                //string plainText = "9910";
                //// 1. 转为 .NET XML 公钥
                //string xmlPublicKey = FW.E9.Service.Service.RSAConvert.RSAPublicKeyJava2DotNet(pemPublicKey);
                //// 2. 直接用 XML 加密
                //using (var rsa = new RSACryptoServiceProvider())
                //{
                //    rsa.FromXmlString(xmlPublicKey);
                //    byte[] cipher = rsa.Encrypt(Encoding.UTF8.GetBytes(plainText), false);
                //    Console.WriteLine(Convert.ToBase64String(cipher));
                //}

                //return JsonConvert.SerializeObject(new { requestBodyObj, CabinetNos, palletTable, dev_Account });

                requestBodyJson = JsonConvert.SerializeObject(requestBodyObj);

                // === 6. 调用 OA 接口（使用 Task.Run 防止 ASP.NET 死锁）===
                oaResponse = Task.Run(async () =>
                {
                    using (var httpClient = new HttpClient())
                    {
                        //http:"//192.168.1.126:8889"
                        httpClient.BaseAddress = new Uri(AppInfo.OAUrl);
                        httpClient.Timeout = TimeSpan.FromSeconds(900);

                        const string appid = "ekoaapi";
                        const string secret = "";

                        // --- 获取 token ---
                        using (var tokenReq = new HttpRequestMessage(HttpMethod.Post, "/api/ec/dev/auth/applytoken"))
                        {
                            tokenReq.Headers.Add("appid", appid);
                            tokenReq.Headers.Add("secret", secret);
                            var tokenResp = await httpClient.SendAsync(tokenReq);
                            tokenResp.EnsureSuccessStatusCode();

                            var tokenJson = await tokenResp.Content.ReadAsStringAsync();

                            JObject tokenObj;
                            try
                            {
                                tokenObj = JObject.Parse(tokenJson);
                            }
                            catch (JsonReaderException ex)
                            {
                                throw new InvalidOperationException($"获取 token 返回非 JSON 响应: {ex.Message}", ex);
                            }

                            if (!(tokenObj["status"]?.Value<bool>() == true) || tokenObj["code"]?.ToString() != "0")
                                throw new InvalidOperationException($"获取 token 失败: {tokenObj["msg"]?.ToString() ?? "未知错误"}");

                            string token = tokenObj["token"]?.ToString();
                            if (string.IsNullOrEmpty(token))
                                throw new InvalidOperationException("获取到的 token 为空");

                            // --- 发送主请求（JSON Body）---
                            var mainReq = new HttpRequestMessage(HttpMethod.Post, "/api/workflow/paService/doCreateRequest")
                            {
                                Content = new StringContent(requestBodyJson, Encoding.UTF8, "application/json")
                            };

                            mainReq.Headers.Add("token", token);
                            mainReq.Headers.Add("appid", appid);
                            //userid使用固定经过RSA加密的13342  加密密钥为上面的
                            mainReq.Headers.Add("userid", "");

                            var resp = await httpClient.SendAsync(mainReq);
                            resp.EnsureSuccessStatusCode();
                            return await resp.Content.ReadAsStringAsync();
                        }
                    }
                }).GetAwaiter().GetResult();

                JObject oaResponseObj = JObject.Parse(oaResponse);

                JToken codeToken;
                if (!oaResponseObj.TryGetValue("code", out codeToken) ||
                    codeToken?.Type != JTokenType.String ||
                    codeToken.Value<string>() != "SUCCESS")
                {
                    throw new InvalidOperationException("发送请求失败Code：" + codeToken);
                }
                // === 7. 成功 ===
                //更新数据表通知单数据
                SqlHelper.ExecuteNonQuery(
                    string.Format(@"
                    UPDATE A
                    SET    A.NoticeNo = '{0}'
                    FROM   [dbo].[WMS_Pallet] A
                    WHERE  A.CabinetNo in ('{1}') 
                    ",
                    billNo,
                    string.Join("','", validCabinetNos)
                    )
                );
                //记录成功消息
                result = true;
                msg = string.Format("柜号推送成功,柜号:'{0}'", string.Join("','", validCabinetNos));
                detailMsg = msg;
            }
            catch (ArgumentException ex)
            {
                result = false;
                detailMsg = $"参数错误: {ex.Message}";
            }
            catch (InvalidOperationException ex)
            {
                result = false;
                detailMsg = $"业务失败: {ex.Message}";
            }
            catch (HttpRequestException ex)
            {
                result = false;
                detailMsg = $"网络请求失败: {ex.Message}";
            }
            catch (Exception ex)
            {
                result = false;
                detailMsg = $"系统异常: {ex.Message}";
            }

            if (!result)
            {
                msg = "柜号推送失败！！" + msg;
                //进行日志记录
                systemLog.SaveLog(SystemLog.SystemLogType.接口推送失败, "EK的推送OA_失败：原因：" + detailMsg + "，请求体：" + requestBodyJson + "，返回参数：" + oaResponse, null, null);
            }
            else
            {
                //记录日志
                systemLog.SaveLog(SystemLog.SystemLogType.接口推送, "EK的推送OA_成功：详情：" + detailMsg + "，请求体：" + requestBodyJson + "，返回参数：" + oaResponse, null, null);
            }

            return JsonConvert.SerializeObject(new
            {
                result,
                msg
            });
        }

        /*
         * EK 推送栈板信息到WMS
        */
        public string PalletPushWMS()
        {
            bool result = false;
            string msg = "";
            var results = new List<dynamic>(); // 存储每次请求的结果
            string WMSStatus = "";//wms状态  更新情况
            try
            {
                // 1. 解析输入 JSON
                if (string.IsNullOrWhiteSpace(BodyJson))
                    throw new ArgumentException("输入数据为空");

                var jArray = JsonConvert.DeserializeObject(BodyJson) as JArray
                             ?? throw new ArgumentException("数据格式异常");

                var CabinetNos = jArray
                    .OfType<JObject>()
                    .Select(j => j["CabinetNo"]?.ToString()?.Trim())
                    .Where(code => !string.IsNullOrEmpty(code))
                    .Distinct()
                    .ToList();

                if (!CabinetNos.Any())
                {
                    msg = "未找到有效的柜号!";
                    throw new ArgumentException("未找到有效的柜号（CabinetNo）");
                }
                if (CabinetNos.Count > 1)
                {
                    msg = "一次只能推送一个柜号";
                    throw new ArgumentException("一次只能推送一个柜号");
                }
                // 2. 查询柜号下--》栈板数据
                string sqlPallet = $@"
                    SELECT PalletNo, CabinetNo ,ShippingDate,ShippingCompanyCode,ShippingNo
                    FROM WMS_Pallet 
                    WHERE Status = 1 AND ISNULL(WMSStatus,0)!=1 AND CabinetNo IN ('{string.Join("','", CabinetNos)}')";

                DataTable palletTable = SqlHelper.ExecuteDataTable(sqlPallet);

                if (palletTable.Rows.Count == 0)
                {
                    msg = "所提供的柜号，没有找到未推送WMS的栈板";
                    throw new ArgumentException("所提供的柜号，没有栈板（PalletNo）");
                }

                //查询柜号下的所有栈板列表
                List<string> palletNoList = palletTable.AsEnumerable()
                                    .Select(row => row.Field<string>("PalletNo"))
                                    .ToList();

                //校验wms的条码状态 是否卡住  直接在后台校验
                string sqlReel = $@"
                  SELECT Reel_Code,REEL_STATUS,REEL_STATUS_NAME
                  FROM   Openquery(WMSTEST, 'select * from  V_PALLET_REEL  ') AS A
                  where A.pallet_no in ('{string.Join("','", palletNoList)}')
                  and reel_status!=1
                 ";

                DataTable ReelCodeTable = SqlHelper.ExecuteDataTable(sqlReel);

                if (ReelCodeTable.Rows.Count > 0)
                {
                    List<string> ReelCodeList = ReelCodeTable.AsEnumerable()
                        .Select(row => row.Field<string>("Reel_Code"))
                        .ToList();
                    msg = "条码状态异常,条码如下:" + string.Join(",", ReelCodeList);
                    var ReelCodeTableList = ReelCodeTable.AsEnumerable().Select(row =>
                        ReelCodeTable.Columns.Cast<DataColumn>().ToDictionary(
                            col => col.ColumnName,
                            col => row[col]
                        )
                    ).ToList();
                    throw new InvalidOperationException("条码状态异常:" + ReelCodeTableList.ToJSON());//记录详细状态
                }

                //msg = "已主动结束运行！！！";
                //throw new InvalidOperationException("已主动结束运行！！！" + palletNoList.ToJSON());


                // 3. 构建字典：CabinetNo -> List<PalletNo>
                var cabinetToPallets = new Dictionary<string, List<string>>();
                Dictionary<string, string[]> cabinetToShippingInfo = new Dictionary<string, string[]>();
                foreach (DataRow row in palletTable.Rows)
                {
                    string palletNo = row["PalletNo"] == DBNull.Value ? "" : row["PalletNo"].ToString();
                    string cabinetNo = row["CabinetNo"] == DBNull.Value ? "" : row["CabinetNo"].ToString();

                    if (cabinetNo == "" || palletNo == "")
                        continue;

                    // 如果是第一次遇到这个 CabinetNo，记录发货信息
                    if (!cabinetToPallets.ContainsKey(cabinetNo))
                    {
                        cabinetToPallets[cabinetNo] = new List<string>();

                        string shippingDate = row["ShippingDate"] == DBNull.Value ? "" : row["ShippingDate"].ToString();
                        string companyCode = row["ShippingCompanyCode"] == DBNull.Value ? "" : row["ShippingCompanyCode"].ToString();
                        string shippingNo = row["ShippingNo"] == DBNull.Value ? "" : row["ShippingNo"].ToString();

                        cabinetToShippingInfo[cabinetNo] = new string[3] { shippingDate, companyCode, shippingNo };
                    }

                    cabinetToPallets[cabinetNo].Add(palletNo);
                }
                // 5. 发送请求http://192.168.1.206:42731
                //AppInfo.WMSUrl
                string wmsUrl = AppInfo.WMSUrl + "/Picking/AutoGG";
                using (var httpClient = new HttpClient())
                {
                    httpClient.Timeout = TimeSpan.FromSeconds(900);//这个接口速度较慢，时间需要调整
                    //分批次 发送请求
                    foreach (var kvp in cabinetToPallets)
                    {
                        string containerNo = kvp.Key;
                        var palletNos = kvp.Value;
                        string[] info = cabinetToShippingInfo[containerNo];
                        string ShipmentDate = info[0];
                        string ShippingCompany = info[1];
                        string ShipmentNo = info[2];

                        var payload = new
                        {
                            ContainerNo = containerNo,
                            PalletNos = palletNos.ToArray(),
                            ShipmentDate,
                            ShippingCompany,
                            ShipmentNo,
                            ApsOperator = dev_Account.Name
                        };

                        var content = new StringContent(JsonConvert.SerializeObject(payload), Encoding.UTF8, "application/json");

                        bool success = false;
                        string responseText = "";
                        string errorMsg = "";
                        string billNo = "";

                        try
                        {
                            var response = httpClient.PostAsync(wmsUrl, content).GetAwaiter().GetResult();
                            responseText = response.Content.ReadAsStringAsync().GetAwaiter().GetResult();

                            // 1. HTTP 错误？
                            if (!response.IsSuccessStatusCode)
                                throw new InvalidOperationException($"HTTP {response.StatusCode}: {response.ReasonPhrase}");

                            // 2. 响应为空？
                            if (string.IsNullOrWhiteSpace(responseText))
                                throw new InvalidOperationException("WMS 返回空响应");

                            // 3. 解析 JSON
                            JObject jsonResponse = JObject.Parse(responseText);

                            // 4. 检查业务状态
                            JToken statusToken;
                            if (!jsonResponse.TryGetValue("status", out statusToken) ||
                                statusToken.Type != JTokenType.Boolean ||
                                !statusToken.Value<bool>())
                            {
                                string msgFromServer = jsonResponse["msg"]?.ToString()?.Trim() ?? "未提供具体原因";
                                throw new InvalidOperationException($"业务失败: {msgFromServer}");
                            }
                            //获取销售单号
                            JToken dataToken;
                            if (jsonResponse.TryGetValue("data", out dataToken) && dataToken != null && dataToken.Type == JTokenType.Object)
                            {
                                var dataObj = (JObject)dataToken;
                                JToken billNoToken = dataObj["BillNo"]; // 或 "BillNo"
                                if (billNoToken != null && billNoToken.Type == JTokenType.String)
                                {
                                    billNo = billNoToken.Value<string>().Trim();
                                }
                            }
                            // 5. 成功
                            success = true;
                            errorMsg = "";
                        }
                        catch (JsonReaderException ex)
                        {
                            success = false;
                            errorMsg = "json转换错误";
                        }
                        catch (InvalidOperationException ex)
                        {
                            // 这是我们主动抛出的“业务/流程异常”
                            success = false;
                            errorMsg = ex.Message; // 精准错误信息
                        }
                        catch (Exception ex)
                        {
                            // 网络、超时、DNS 等系统级异常
                            success = false;
                            errorMsg = $"请求异常: {ex.Message}";
                        }

                        // 记录本次结果
                        results.Add(new
                        {
                            Success = success,
                            billNo,
                            ContainerNo = containerNo,
                            WMSDetail = responseText,
                            APSDetail = errorMsg,
                            PushWMSBody = payload
                        });
                    }
                }

                // 6. 汇总判断：只要有一次失败，整体 result = false（按需调整）
                result = results.All(r => r.Success);
                // 提取成功和失败的柜号
                var successContainers = results.Where(r => r.Success).Select(r => r.ContainerNo).ToList();
                var billNoS = results.Where(r => r.Success).Select(r => r.billNo).ToList();
                var failContainers = results.Where(r => !r.Success).Select(r => r.ContainerNo).ToList();

                if (successContainers.Count == results.Count)
                {
                    msg = $"柜号('{string.Join("','", successContainers)}')推送成功,生成销售单号:'{string.Join("','", billNoS)}'";
                }
                else if (failContainers.Count == results.Count)
                {
                    msg = $"柜号('{string.Join("','", failContainers)}')推送失败";
                }
                else
                {
                    msg = $"柜号：('{string.Join("','", successContainers)}')推送成功，('{string.Join("','", failContainers)}')推送失败,生成销售单号:'{string.Join("','", billNoS)}'";
                }
                //进行日志记录
                if (result)
                {
                    systemLog.SaveLog(SystemLog.SystemLogType.接口推送, msg + ",处理过程的数据results：" + JsonConvert.SerializeObject(results), null, null);
                }
                else
                {
                    systemLog.SaveLog(SystemLog.SystemLogType.接口推送失败, msg + "，处理过程的数据results：" + JsonConvert.SerializeObject(results), null, null);
                }
                //更新状态wms推送状态
                if (successContainers.Count > 0)
                {
                    try
                    {
                        SqlHelper.ExecuteNonQuery(
                        string.Format(@"
                        UPDATE A
                        SET    A.WMSStatus = 1
                        FROM   [dbo].[WMS_Pallet] A
                        WHERE  A.CabinetNo in ('{0}')
                        ",
                        string.Join("','", successContainers)
                        ));
                    }
                    catch (Exception ex)
                    {
                        WMSStatus = "更新失败" + ex.Message;
                    }
                }
                // 返回详细结果
                return JsonConvert.SerializeObject(new
                {
                    result,
                    msg
                }, Formatting.None);
            }
            catch (Exception ex)
            {
                //进行日志记录
                systemLog.SaveLog(SystemLog.SystemLogType.接口推送失败, "EK的推送WMS_失败：" + ex.Message, null, null);
                result = false;
                msg = "柜号推送WMS失败！" + msg;
                return JsonConvert.SerializeObject(new
                {
                    result = false,
                    msg
                });
            }
        }
        #endregion


