        /// <summary>
        /// 重排日计划
        /// </summary>
        /// <returns></returns>
        /// <summary>
        /// 重排日计划
        /// </summary>
        /// <returns></returns>
        public string ReseDayPlanFromProcessgGroup()
        {
            bool result = true;
            string msg = "操作成功";

            try
            {
                jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;

                if (jArray == null || jArray.Count == 0)
                {
                    msg = "未接受到数据，请确认是否为JSON格式";
                    result = false;
                }
                else
                {

                    List<string> list = new List<string>();
                    string sql = "";
                    string ids = "0";
                    string v = "V0";
                    foreach (JObject jObject in jArray)
                    {
                        if (!string.IsNullOrEmpty(jObject["ProcessPlanID"].ToString()))
                        {

                            ids += "," + jObject["ProcessPlanID"].ToString();
                        }
                        if (!string.IsNullOrEmpty(jObject["ProcessGroupID"].ToString()))
                        {
                            if (list.Contains(jObject["ProcessGroupID"].ToString()) == false)
                            {
                                list.Add(jObject["ProcessGroupID"].ToString());
                            }

                        }
                        if (jObject.ContainsKey("V") && !string.IsNullOrEmpty(jObject["V"].ToString()))
                        {
                            v = jObject["V"].ToString();
                        }

                    }



                    sql = " UPDATE APS_ProcessPlan SET Extend2='待重排' where ProcessPlanID IN(" + ids + ");";


                    SaveData();
                    if (!string.IsNullOrEmpty(sql))
                    {
                        SqlHelper.ExecuteNonQuery(sql);
                        foreach (string ProcessGroupID in list)
                        {
                            SqlParameter[] sqlParameters = new SqlParameter[1];
                            sqlParameters[0] = new SqlParameter("@ProcessGroupID", ProcessGroupID);//工艺ID

                            SqlHelper.ExecuteNonQuery(SqlHelper.MSSQLConnectionString, "P_APS_ToProcessPlanFromMaterialForm" + v, sqlParameters);

                        }

                    }
                }
            }
            catch (Exception ex)
            {
                result = false;
                msg = "数据操作失败,错误信息:" + ex.Message;
            }
            return JsonConvert.SerializeObject(new
            {

                result,
                msg
            }); ; ;
        }

