        public void setDetai17243(DataRow dataRow)
        {
            if (jObject["YearMonth"] == null)
            {
                return;
            }

            DateTime StartDate = Convert.ToDateTime(DateTime.Now.Year + "-" + DateTime.Now.Month + "-01");
            DateTime EndDate = StartDate.AddMonths(1).AddDays(-1);
            if (jObject["YearMonth"] != null)
            {
                if (jObject["YearMonth"].ToString() != "")
                {
                    StartDate = getDateYearMonth(jObject["YearMonth"].ToString());
                    EndDate = StartDate.AddMonths(1).AddDays(-1);
                }






            }

            decimal totalCalculateQty, totalPlanQty, TolalPurQty, SupplierMatch;
            totalCalculateQty = 0;
            totalPlanQty = 0;
            TolalPurQty = 0;
            string b = DtDetail1.Compute("SUM(CalculateQty)", " Code='" + dataRow["Code"] + "'").ToString();//预测订单数量
            decimal.TryParse(b, out totalCalculateQty);

            string c = DtDetail2.Compute("SUM(POQty)", " Code='" + dataRow["Code"] + "'").ToString();//采购需求数量
            decimal.TryParse(c, out TolalPurQty);

            SupplierMatch = 1;
            decimal.TryParse(dataRow["SupplierMatch"].ToString(), out SupplierMatch);
            if (SupplierMatch == 0)
            {
                SupplierMatch = 1;
            }

            Dictionary<string, string> bColors = new Dictionary<string, string>();//背景颜色
            while (EndDate >= StartDate)
            {

                string day = string.Format("{0:yyyy-MM-dd}", StartDate);
                string s = DtDetail.Compute("SUM(Qty)", " Code='" + dataRow["Code"] + "'  AND DeliveryDate='" + StartDate + "'").ToString();//月初正式出货数量


                decimal m, total2;
                decimal n, total1;
                decimal.TryParse(s, out m);



                total2 = m;
                if (total2 > 0)
                {
                    string rowValue = "";
                    if (m > 0)
                    {

                        rowValue += Math.Round(m * SupplierMatch, 2).ToString("0.#####");


                        totalPlanQty += m;

                    }

                    dataRow[day] = rowValue;

                }



                StartDate = StartDate.AddDays(1);
            }

            totalPlanQty = Math.Round(totalPlanQty, 2);

            dataRow["totalCalculateQty"] = totalCalculateQty;
            dataRow["totalPlanQty"] = totalPlanQty;
            dataRow["totalPlanQtyDiff"] = totalPlanQty - totalCalculateQty;
            dataRow["TolalPurQty"] = TolalPurQty;
            dataRow["TolalPurQtyDiff"] = TolalPurQty - totalPlanQty;

            dataRow["SupplierMatchQty"] = Math.Round(totalPlanQty * SupplierMatch, 2);



        }



