        public void setDetail17246(DataRow dataRow)
        {
            if (jObject["YearMonth"] == null)
            {
                return;
            }
            string YearMonth = jObject["YearMonth"].ToString();
            DateTime StartDate = Convert.ToDateTime(DateTime.Now.Year + "-" + DateTime.Now.Month + "-01");
            DateTime EndDate = Convert.ToDateTime(DateTime.Now.Year + "-" + DateTime.Now.AddMonths(1).Month + "-01").AddDays(-1);
            YearMonth = string.Format("{0:yyyyMM}", StartDate);
            if (jObject["YearMonth"] != null)
            {
                if (jObject["YearMonth"].ToString() != "")
                {
                    StartDate = getDateYearMonth(jObject["YearMonth"].ToString());
                    EndDate = StartDate.AddMonths(1).AddDays(-1);
                    YearMonth = jObject["YearMonth"].ToString();
                }
            }
            Dictionary<string, string> fColors = new Dictionary<string, string>();//字体颜色

            //合计
            //decimal TotalQty;
            //string n = DtDetail.Compute("SUM(OrderQty)", "CustomerID=" + dataRow["CustomerID"] + "  AND MaterialID=" + dataRow["MaterialID"] + "").ToString();//每天订单数量
            //decimal.TryParse(n, out TotalQty);
            //dataRow["TotalQty"] = TotalQty;

            while (EndDate >= StartDate)
            {

                string day = string.Format("{0:yyyy-MM-dd}", StartDate);
                string s = DtDetail.Compute("SUM(OrderQty)", "  MaterialID=" + dataRow["MaterialID"] + "  AND RequestDate='" + StartDate + "'").ToString();//每天订单数量
                string s1 = DtDetail.Compute("SUM(OweQty)", "  MaterialID=" + dataRow["MaterialID"] + "  AND RequestDate='" + StartDate + "'").ToString();//每天欠数

                decimal m, total2, m1;
                decimal.TryParse(s, out m);
                decimal.TryParse(s1, out m1);

                total2 = Math.Abs(m);
                if (total2 > 0)
                {
                    string rowValue = "";

                    if (m > 0 && m1 >= 0)
                    {
                        rowValue = m.ToString("G0");
                        fColors.Add(day, "#0536E8");
                    }
                    else
                    {
                        rowValue = m.ToString("G0") + "(" + m1.ToString("G0") + ")";
                        fColors.Add(day, "#FF0000");
                    }

                    dataRow[day] = rowValue;
                    dataRow["FColors"] = fColors;
                }

                StartDate = StartDate.AddDays(1);
            }

        }
