            ,b.Code
		   ,b.MaterialName
		   ,1
		   ,'{0}'
		   ,'{1}'
		   ,GETDATE()
		   ,case when B.MaterialID is null then '错误' else '正常' end
		   ,case when B.MaterialID is null then '产品不存在' else NULL end
,'{3:yyyyMM}',{4},'{5}',{6}
		   FROM  Dev_Account A(nolock)
		   left join APS_Material  B(nolock) ON (B.MaterialName='{2}' or B.Code='{2}')
