            ", dev_Account.Account, dev_Account.Name, MaterialName, d, StringHelper.ReplaceSqlValue(viewSort), keyValue, jObject.ContainsKey("Customer") ? StringHelper.ReplaceSqlValue(jObject["Customer"].ToString()) : "NULL", jObject["YearMonth"].ToString()));
