        public string[] SplitString(string inputStr, int splitLength)
        {
            //计算分割的段数
            int numberOfsplits = (int)Math.Ceiling((double)inputStr.Length / splitLength);

            //分割字符串
            string[] outputStr = new string[numberOfsplits];
            for (int i = 0; i < numberOfsplits; i++)
            {
                int startIndex = i * splitLength;
                int length = Math.Min(splitLength, inputStr.Length - startIndex);
                outputStr[i] = inputStr.Substring(startIndex, length);
            }

            return outputStr;
        }
        /// <summary>
        /// 排班计划
        /// </summary>
        /// <param name="dt"></param>
        public void SetDt17274(ref DataTable dt)
        {

            if (jObject["StartDate"] == null || jObject["EndDate"] == null)
            {
                return;
            }

            DateTime startDate = Convert.ToDateTime(jObject["StartDate"].ToString());
            DateTime endDate = Convert.ToDateTime(jObject["EndDate"].ToString());

            dt.Columns.Add("BColors", typeof(Dictionary<string, string>));

            DateTime d1 = startDate;


            while (startDate <= endDate)
            {

                //string label = string.Format("{0:MM-dd}({1})", startDate, System.Globalization.CultureInfo.CurrentCulture.DateTimeFormat.GetDayName(startDate.DayOfWeek).Replace("星期", ""));
                string label = string.Format("{0:MM-dd}", startDate);
                string prop = string.Format("{0:yyyy-MM-dd}", startDate);
                dt.Columns.Add(prop);

                ElementColumn[0].Add(new ElementTableOuput() { label = label, prop = prop, width = "60", isEdit = false, ControlType = "textbox" });
                startDate = startDate.AddDays(1);
            }



            DtDetail = SqlHelper.ExecuteDataTable(string.Format(@"
            SELECT *
            FROM   V_APS_OrganizeWorkingTimesDetail 
            WHERE WorkingDate>='{0}' and WorkingDate<='{1}'", d1, endDate));


        }
        /// <summary>
        /// 排班计划
        /// </summary>
        /// <param name="dataRow"></param>
        public void setDetail17274(DataRow dataRow)
        {
            if (jObject["StartDate"] == null || jObject["EndDate"] == null)
            {
                return;
            }

            if (jObject["radioLabel"] == null)
            {
                return;
            }

            string lableType = jObject["radioLabel"].ToString();

            DateTime StartDate = Convert.ToDateTime(jObject["StartDate"].ToString());
            DateTime EndDate = Convert.ToDateTime(jObject["EndDate"].ToString());


            Dictionary<string, string> bColors = new Dictionary<string, string>();//背景颜色


            while (EndDate >= StartDate)
            {


                string day = string.Format("{0:yyyy-MM-dd}", StartDate);
                DataRow[] dr = DtDetail.Select("OrganizeID=" + dataRow["OrganizeID"] + "   AND WorkingDate='" + StartDate + "'");
                if (dr.Length > 0)
                {
                    if (lableType == "工时")
                    {
                        dataRow[day] = dr[0]["WorkHour"];
                    }
                    else if (lableType == "人数")
                    {
                        dataRow[day] = dr[0]["Peoples"];
                    }
                    else if (lableType == "总工时")
                    {
                        dataRow[day] = dr[0]["TotalHours"];
                    }
                    else if (lableType == "班次")
                    {
                        dataRow[day] = dr[0]["WorkingTimesName"];
                    }
                    else if (lableType == "剩余工时")
                    {
                        dataRow[day] = dr[0]["RemainingHours"];
                    }
                }

                StartDate = StartDate.AddDays(1);
            }

        }
