        /// 报工
        /// </summary>
        /// <returns></returns>
        public string InsertDayProduction()
        {
            bool result = true;
            string msg = "操作成功";
            if (dev_Account != null)
            {

                try
                {
                    jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;
                    string DayPlanIDs = "0";

                    foreach (JObject jObject in jArray)
                    {
                        DayPlanIDs += "," + jObject["DayPlanID"].ToString();

                    }
                    DataTable dataTable = SqlHelper.ExecuteDataTable($@"SELECT  DayProductionID,DayPlanID
  FROM  [dbo].[APS_DayProduction]
  where DayPlanID in(
  {DayPlanIDs}
  )
");
                    SqlConnection connection = new SqlConnection(SqlHelper.MSSQLConnectionString);
                    connection.Open();
                    using (SqlTransaction tran = connection.BeginTransaction())
                    {
                        try
                        {

                            foreach (JObject jObject in jArray)
                            {
                                string DayPlanID = jObject["DayPlanID"].ToString();
                                DataRow[] dataRows = dataTable.Select("DayPlanID=" + DayPlanID);
                                if (dataRows.Length == 0)
                                {

                                }
                                else
                                {
                                    jObject["DayProductionID"] = dataRows[0]["DayProductionID"].ToString();
                                }
                                base.SaveDB(jObject, ref msg, tran, "", "");
                            }
                            tran.Commit();
                        }
                        catch (Exception ex)
                        {
                            result = false;
                            msg = ex.Message;
                            tran.Rollback();
                        }
                        finally
                        {

                            connection.Close();
                        }

                    }

                }
                catch (Exception ex)
                {
                    result = false;
                    msg = "数据操作失败,错误信息:" + ex.Message;
                }
