        /// <param name="dt"></param>
        public void SetDt18288(ref DataTable dt)
        {
            DateTime startDate = DateTime.Now.Date;
            DateTime endDate = startDate.AddDays(6);
            if (jObject.ContainsKey("DynamicDate1"))
            {
                JArray jArray = jObject["DynamicDate1"] as JArray;
                if (!string.IsNullOrEmpty(jArray[0].ToString()))
                {
                    startDate = DateTime.Parse(jArray[0].ToString());
                    endDate = DateTime.Parse(jArray[1].ToString());
                }
            }

            dt.Columns.Add("BColors", typeof(Dictionary<string, string>));

            //dt.Columns.Add("分配送货", typeof(decimal)); // 增加动态分配送货
            //作为第一个元素插入，可以在页面上属性属性配置用固定来将数据库的字段放在前面
            //ElementColumn[0].Add(new ElementTableOuput() { label = "分配送货", prop = "分配送货", width = "80", prop2 = "分配送货", routerName = true, isEdit = false, ControlType = "textbox", extend3 = "P" });

            DtDetail = SqlHelper.ExecuteDataTable(string.Format(@"
            SELECT SuplierName,Extend12,ItemCode,APSDemandDay,OweQty
            FROM [APS_DeliveryData]
            where APSDemandDay>='{0}' and APSDemandDay<='{1}'", startDate, endDate));

            while (endDate >= startDate)
            {


                // 获取中文格式的星期几
                string chineseDayOfWeek = GetChineseDayOfWeek(startDate);

                string prop = string.Format("{0:MM-dd}", startDate);
                dt.Columns.Add(prop, typeof(string));
                ElementColumn[0].Add(new ElementTableOuput() { label = prop + "(" + chineseDayOfWeek + ")", prop = prop, width = "80", prop2 = prop, routerName = true, isEdit = false, ControlType = "textbox", extend3 = "P" });
                startDate = startDate.AddDays(1);
            }
        }
        static string GetChineseDayOfWeek(DateTime date)
        {
            switch (date.DayOfWeek)
            {
                case DayOfWeek.Monday:
                    return "一";
                case DayOfWeek.Tuesday:
                    return "二";
                case DayOfWeek.Wednesday:
                    return "三";
                case DayOfWeek.Thursday:
                    return "四";
                case DayOfWeek.Friday:
                    return "五";
                case DayOfWeek.Saturday:
                    return "六";
                case DayOfWeek.Sunday:
                    return "日";
                default:
                    throw new ArgumentOutOfRangeException();
            }
        }
