        private void SetDt19293(ref DataTable dt)
        {
            DateTime startDate = DateTime.Now.Date;
            DateTime endDate = startDate.AddDays(6);
            //  dt.Columns.Add(new DataColumn("Lines", typeof(List<object>)));
            dt.Columns.Add("BColors", typeof(Dictionary<string, string>));
            dt.Columns.Add("FColors", typeof(Dictionary<string, string>));
            for (int i = 1; i < 8; i++)
            {
                DateTime dateTime = DateTime.Now.AddDays(i - 1);

                string YearMonth = string.Format("{0:yyyy-MM-dd}", dateTime);
                dt.Columns.Add(YearMonth + "不齐套");
                dt.Columns.Add(YearMonth + "齐套");
                dt.Columns.Add("T" + i + "齐套率");


                var col = new ElementTableOuput() { label = YearMonth, prop = YearMonth, width = "180", prop2 = YearMonth, isEdit = true, ControlType = "textbox", align = "center" };
                col.children = new List<ElementTableOuput>();
                col.children.Add(new ElementTableOuput() { label = "不齐套", prop = YearMonth + "不齐套", width = "60", prop2 = YearMonth, isEdit = true, ControlType = "textbox" });
                col.children.Add(new ElementTableOuput() { label = "齐套", prop = YearMonth + "齐套", width = "60", prop2 = YearMonth, isEdit = true, ControlType = "textbox" });
                col.children.Add(new ElementTableOuput() { label = "T" + i + "齐套率", prop = "T" + i + "齐套率", width = "60", prop2 = YearMonth, isEdit = true, ControlType = "textbox" });

                ElementColumn[0].Add(col);
            }


            DtDetail = SqlHelper.ExecuteDataTable(string.Format(@"
        select b.OrganizeName as lineName,a.DefaultLineID as lineID,a.PlanStartDate as StartDate,
         count(*) OrderFormRate,
         SUM(CASE WHEN a.FormRate8 = '100.00%' THEN 1 ELSE 0 END) AS Form,

         SUM(CASE WHEN a.FormRate8 <> '100.00%' THEN 1 ELSE 0 END) AS UnForm,
          Format(SUM(CASE WHEN a.FormRate8 = '100.00%' THEN 1.0 ELSE 0.0 END)/count(*),'P0') as FormRate
        from APS_Order a 

        LEFT JOIN Dev_Organize b on a.DefaultLineID = b.OrganizeID
        LEFT JOIN Dev_Organize c on c.OrganizeID = b.ParentID
        where  a.status = 1 and CompletionStatus = 0 and a.DefaultLineID is not null
        
   and a.PlanStartDate>='{0}' and a.PlanStartDate<='{1}'
    group by b.OrganizeName,a.DefaultLineID,a.PlanStartDate
    ", startDate, endDate));


        }

        private void setDetail19293(DataRow dataRow)
        {
            Dictionary<string, string> bColors = new Dictionary<string, string>(); // 背景颜色
            Dictionary<string, string> fColors = new Dictionary<string, string>(); // 字体颜色
            for (int i = 1; i < 8; i++)
            {
                string S1 = null;
                DateTime dateTime = DateTime.Now.AddDays(i - 1);
                string YearMonth = string.Format("{0:yyyy-MM-dd}", dateTime);
                DataRow[] dataRows1 = DtDetail.Select("StartDate='" + YearMonth + "'and LineID='" + dataRow["LineID"] + "'");

                if (dataRows1.Length > 0)
                {

                    dataRow[YearMonth + "齐套"] = dataRows1[0]["Form"];
                    dataRow[YearMonth + "不齐套"] = dataRows1[0]["UnForm"];
                    dataRow["T" + i + "齐套率"] = dataRows1[0]["FormRate"];
                    S1 = dataRows1[0]["FormRate"].ToString();
                }
                fColors.Add(YearMonth + "齐套", "#2400D9");
                fColors.Add(YearMonth + "不齐套", "#F20707");


                if (S1 == "100%")
                {
                    bColors.Add("T" + i + "齐套率", "#07F413");
                }
                else
                {
                    bColors.Add("T" + i + "齐套率", "#FDFF80");
                }


            }
            dataRow["BColors"] = bColors;
            dataRow["FColors"] = fColors;
        }

