        private void setDetail7868(DataRow dataRow)
        {
            Dictionary<string, string> bColors = new Dictionary<string, string>(); // 背景颜色
                                                                                   //Dictionary<string, string> fColors = new Dictionary<string, string>(); // 字体颜色

            decimal count = (decimal)jObject["count"];
            DateTime date = (DateTime)jObject["date"];
            int factory = (int)jObject["factory"];



            decimal StockQty = 0;
            decimal QPA = 0;
            decimal.TryParse(dataRow["QPA"].ToString(), out QPA);
            int POPeriod = (int)dataRow["POPeriod"];
            decimal OweQty = 0;
            //int factory = 1;

            if (factory == 0)
            {
                StockQty = (decimal)dataRow["UsableQty1"];
                dataRow["StockQty"] = StockQty;

                ;
            }
            if (factory == 1)
            {
                StockQty = (decimal)dataRow["UsableQty2"];
                dataRow["StockQty"] = StockQty;

            }

            dataRow["DemandQty"] = QPA * count;

            OweQty = StockQty - (QPA * count);


            if (OweQty >= 0)
            {
                dataRow["OweQty"] = 0;
                dataRow["Explain"] = "库存满足";
            }
            else
            {
                dataRow["OweQty"] = OweQty;
                dataRow["Explain"] = "需要采购";
            }

            //DateTime dateTime = date.AddDays(POPeriod);
            dataRow["POPeriod1"] = POPeriod;
            if (OweQty < 0)
            {

                bColors.Add("POPeriod1", "#F20707");
            }


            dataRow["BColors"] = bColors;
            //dataRow["FColors"] = fColors;
            //dataRow["DemandQty"] = 1;

            //dataRow["OweQty"] = 0;


            //dataRow["PCDeliveryDate"] = 1;
        }
