        /// <summary>
        /// 需求计划业务计划
        /// </summary>
        /// <param name="dt"></param>
        public void SetDt23350(ref DataTable dt)
        {




            //滚动周

            DateTime today = DateTime.Now;  // 获取当前日期
            DateTime firstDayOfMonth = new DateTime(today.Year, today.Month, 1); // 获取当前月的第一天
            DateTime startOfWeek = today.AddDays(-(int)today.DayOfWeek + (int)DayOfWeek.Monday);  // 计算本周周一的日期

            if (startOfWeek < firstDayOfMonth)
            {
                startOfWeek = firstDayOfMonth;
            }
            DateTime SqlStartDate = startOfWeek;
            for (int i = 0; i < 5; i++)
            {





                DateTime endOfWeek = new DateTime(startOfWeek.Year, startOfWeek.Month, DateTime.DaysInMonth(startOfWeek.Year, startOfWeek.Month)); //月末日期




                DateTime dateTime = DateTime.Now.AddDays(i);
                string label = string.Format("{2}月预测提货金额（元）\n{0:MM/dd}~{1:MM/dd}", startOfWeek, endOfWeek, startOfWeek.Month);
                string prop = string.Format("{0:yyyy-MM-dd}", startOfWeek);
                dt.Columns.Add(prop, typeof(decimal));
                ElementColumn[0].Add(new ElementTableOuput() { label = label, prop = prop, width = "130", isEdit = false, ControlType = "textbox" });
                mSSQLCore.Dev_DictionaryFields.Add(new Dev_DictionaryField { DictionaryID = 23350, ValidType = "P2410160001", ParameterName = prop });
                //求和
                mSSQLCore.Dev_DictionaryFields.Add(new Dev_DictionaryField() { FooterType = "SUM", ParameterName = prop, DataType = "decimal", IsVisible = true });
                startOfWeek = endOfWeek.AddDays(1);
            }


            DateTime startDate1 = today.AddDays(-(int)today.DayOfWeek + (int)DayOfWeek.Monday);  // 计算本周周一的日期

            DtDetail = SqlHelper.ExecuteDataTable(string.Format(@"SELECT  a.SalesOrderDetailID
		,sum(a.Qty*
		b.PeoplePrice) as TotalPrice
		,a.YearMonth
    FROM APS_SalesOrderDetailPlanLine a
	LEFT JOIN [dbo].[V_APS_SalesOrderDetailDeliver3] b
	on a.SalesOrderDetailID = b.SalesOrderDetailID
	LEFT JOIN PWS_ResignBill c
	on 1=1
	where StartDate >= (SELECT MAX(WeekDate) FROM APS_WeekDate)
	group by a.SalesOrderDetailID,a.YearMonth", string.Format("{0:yyyy-MM-dd}", SqlStartDate)));




        }
