        /// <summary>
        /// 需求计划保存
        /// </summary>
        public string SaveDataDemandPlan()
        {
            bool result = false;
            string msg = "";

            try
            {
                jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;
                if (jArray == null)
                {
                    allMsg = "未接收到数据，请确认是否为JSON格式";
                    result = false;

                }
                else if (dev_Account == null)
                {
                    allMsg = "当前登录信息已经丢失，请刷新页面重新登录";
                    result = false;
                }

                else
                {
                    SaveData();
                    result = true;


                    //int dicID = int.Parse(jObject["dicID"].ToString());






                    foreach (JObject obj in jArray)
                    {




                        DateTime today = DateTime.Now;  // 获取当前日期
                        DateTime todayMonday = today.AddDays(-(int)today.DayOfWeek + (int)DayOfWeek.Monday);
                        DayOfWeek todayOfWeek = today.DayOfWeek;
                        DayOfWeek todayMondayOfWeek = todayMonday.DayOfWeek;


                        for (int j = 0; j < 24; j++)
                        {
                            if (string.IsNullOrEmpty(obj["SalesOrderDetailID"].ToString()))
                            {
                                continue;
                            }


                            DateTime WeeklyMonday = today.AddDays(-(int)today.DayOfWeek + (int)DayOfWeek.Monday);
                            DayOfWeek WeeklyMondayOfWeek = WeeklyMonday.DayOfWeek;

                            DateTime startOfWeek;
                            if ((int)today.DayOfWeek != 0)
                            {
                                startOfWeek = today.AddDays(-(int)today.DayOfWeek + (int)DayOfWeek.Monday);  // 计算本周周一的日期
                            }
                            else
                            {
                                startOfWeek = today.AddDays(-6);
                            }
                            DateTime endOfWeek = startOfWeek.AddDays(6);  // 计算本周周日的日期


                            DateTime lastDayOfMonth = new DateTime(today.Year, today.Month, DateTime.DaysInMonth(today.Year, today.Month)); //月末日期

                            DateTime firstDayOfMonth = new DateTime(today.Year, today.Month, 1); // 获取当前月的第一天
                                                                                                 //本周初
                            if (startOfWeek < firstDayOfMonth)
                            {
                                startOfWeek = firstDayOfMonth;
                            }
                            //本周末
                            if (endOfWeek > lastDayOfMonth)
                            {
                                endOfWeek = lastDayOfMonth;
                            }

                            today = endOfWeek.AddDays(1);

                            //if (!(todayOfWeek != DayOfWeek.Monday && todayMonday == WeeklyMonday))
                            //{
                            String WeekStartDate = string.Format("{0:yyyy-MM-dd}", startOfWeek);
                            if (!string.IsNullOrEmpty(obj[WeekStartDate].ToString()))
                            {
                                decimal Qty = (decimal)obj[WeekStartDate];
                                SqlParameter[] sqlParameters = new SqlParameter[8];
                                sqlParameters[0] = new SqlParameter("@SalesOrderDetailID", obj["SalesOrderDetailID"].ToString());
                                sqlParameters[1] = new SqlParameter("@Result", SqlDbType.Bit);
                                sqlParameters[2] = new SqlParameter("@Msg", SqlDbType.NVarChar, 500);
                                sqlParameters[3] = new SqlParameter("@StartDate", startOfWeek);
                                sqlParameters[4] = new SqlParameter("@EndDate", endOfWeek);
                                sqlParameters[5] = new SqlParameter("@Qty", Qty);
                                sqlParameters[6] = new SqlParameter("@Account", dev_Account.Account);
                                sqlParameters[7] = new SqlParameter("@Name", dev_Account.Name);
                                sqlParameters[1].Direction = sqlParameters[2].Direction = ParameterDirection.Output;
                                SqlHelper.ExecuteNonQuery(SqlHelper.MSSQLConnectionString, "P_APS_ForecastWeeklyQty", sqlParameters);
                                result = sqlParameters[1].Value.ToString().ToLower() == "true";
                                allMsg = sqlParameters[2].Value.ToString();
                            }
                            else
                            {

                                string sql = string.Format(@"delete from  APS_SalesOrderDetailPlanLine where  SalesOrderDetailID =  '{0}' and  StartDate = '{1}';", obj["SalesOrderDetailID"].ToString(), WeekStartDate);
                                SqlHelper.ExecuteNonQuery(SqlHelper.MSSQLConnectionString, CommandType.Text, sql);

                            }
                            //}
                        }





























                    }








                }
            }
            catch (Exception ex)
            {
                allMsg = ex.Message;
                result = false;

            }


            return JsonConvert.SerializeObject(new
            {

                result,
                msg = allMsg
            });
        }





