        /// <summary>
        /// 月度接单明细
        /// </summary>
        /// <param name="dt"></param>
        public void SetDt23365(ref DataTable dt)
        {

            int YearTime = 0;
            int MonthTime = 0;
            string YearMonth = null;
            DateTime today = DateTime.Now;  // 获取当前日期

            if (jObject.ContainsKey("YearTime") == true && jObject.ContainsKey("MonthTime") == true)
            {
                if (!string.IsNullOrEmpty(jObject["YearTime"].ToString()) && !string.IsNullOrEmpty(jObject["MonthTime"].ToString()))
                {
                    YearTime = int.Parse(jObject["YearTime"].ToString());
                    MonthTime = int.Parse(jObject["MonthTime"].ToString());


                }
                else
                {
                    YearTime = today.Year;
                    MonthTime = today.Month;

                }

            }
            else
            {
                YearTime = today.Year;
                MonthTime = today.Month;

            }
            YearMonth = string.Format("{0}-{1}", YearTime.ToString(), MonthTime.ToString("D2"));
            DateTime StartDate = new DateTime(YearTime, MonthTime, 1); // 获取当前月的第一天
            DateTime EndDate = new DateTime(YearTime, MonthTime, DateTime.DaysInMonth(YearTime, MonthTime)); //月末日期


            while (StartDate <= EndDate)
            {










                DateTime dateTime = DateTime.Now.AddDays(1);
                string label = string.Format("{0:MM月dd日}", StartDate);
                string prop = string.Format("{0:yyyy-MM-dd}", StartDate);
                dt.Columns.Add(prop, typeof(string));
                ElementColumn[0].Add(new ElementTableOuput() { label = label, prop = prop, width = "80", isEdit = false, ControlType = "textbox" });


                StartDate = StartDate.AddDays(1);
            }
            dt.Columns.Add("Summary", typeof(string));
            ElementColumn[0].Add(new ElementTableOuput() { label = "汇总", prop = "Summary", width = "80", isEdit = false, ControlType = "textbox" });
            dt.Columns.Add("Effective", typeof(string));
            ElementColumn[0].Add(new ElementTableOuput() { label = "有效订单待生产交货金额", prop = "Effective", width = "80", isEdit = false, ControlType = "textbox" });
            dt.Columns.Add("UnEffective", typeof(string));
            ElementColumn[0].Add(new ElementTableOuput() { label = "无效订单待通知生产金额", prop = "UnEffective", width = "80", isEdit = false, ControlType = "textbox" });
            //目标接单和目标产出
            DtDetail = SqlHelper.ExecuteDataTable(string.Format(@"select * From ERP_Inventory 
    where FORMAT(DayTime,'yyyy-MM') = '{0}'
    ", YearMonth));
            //模具接单
            DtDetail1 = SqlHelper.ExecuteDataTable(string.Format(@"
        select FORMAT(OrderDate,'yyyy-MM-dd') as OrderDate,sum(TotalPrice)as TotalPrice from APS_OrderDelivery where OrderType = '模具订单'  
        and FORMAT(OrderDate,'yyyy-MM') = '{0}' group by FORMAT(OrderDate,'yyyy-MM-dd')
    ", YearMonth));
            //产品接单
            DtDetail2 = SqlHelper.ExecuteDataTable(string.Format(@"
        select FORMAT(OrderDate,'yyyy-MM-dd') as OrderDate,sum(TotalPrice)as TotalPrice  from APS_OrderDelivery where OrderType in('销售订单','寄售订单')
        and FORMAT(OrderDate,'yyyy-MM') = '{0}' group by FORMAT(OrderDate,'yyyy-MM-dd')
    ", YearMonth));

            //模具产出
            DtDetail3 = SqlHelper.ExecuteDataTable(string.Format(@"
        select FORMAT(DeliveryDate,'yyyy-MM-dd') as OrderDate,sum(TotalPrice)as TotalPrice from APS_OrdeSales where OrderType = '模具销货单' 
        and FORMAT(DeliveryDate,'yyyy-MM') = '{0}' group by FORMAT(DeliveryDate,'yyyy-MM-dd')
    ", YearMonth));
            //产品产出
            DtDetail4 = SqlHelper.ExecuteDataTable(string.Format(@"
        select FORMAT(DeliveryDate,'yyyy-MM-dd') as OrderDate,sum(TotalPrice)as TotalPrice from APS_OrdeSales where OrderType = '销货单' 
        and FORMAT(DeliveryDate,'yyyy-MM') = '{0}'  group by FORMAT(DeliveryDate,'yyyy-MM-dd')
    ", YearMonth));
            //产品产出
            DtDetail5 = SqlHelper.ExecuteDataTable(string.Format(@"
           select FORMAT(DeliveryDate,'yyyy-MM-dd') as OrderDate,sum(TotalPrice)as TotalPrice from APS_OrderAllot where 
            FORMAT(DeliveryDate,'yyyy-MM') = '{0}' group by FORMAT(DeliveryDate,'yyyy-MM-dd')
    ", YearMonth));

            //产品退货金额--销退单
            DtDetail6 = SqlHelper.ExecuteDataTable(string.Format(@"
           select FORMAT(DeliveryDate,'yyyy-MM-dd') as OrderDate,sum(TotalPrice)as TotalPrice from APS_SalesReturnOrder 
           where FORMAT(DeliveryDate,'yyyy-MM') = '{0}' group by FORMAT(DeliveryDate,'yyyy-MM-dd')
    ", YearMonth));
            //产品退货金额--寄售退回单
            DtDetail7 = SqlHelper.ExecuteDataTable(string.Format(@"
           select FORMAT(DeliveryDate,'yyyy-MM-dd') as OrderDate,sum(TotalPrice)as TotalPrice from APS_OrderReturn 
           where FORMAT(DeliveryDate,'yyyy-MM') = '{0}' group by FORMAT(DeliveryDate,'yyyy-MM-dd')
    ", YearMonth));
            //产品退货金额--寄售发货单
            DtDetail8 = SqlHelper.ExecuteDataTable(string.Format(@"
           select FORMAT(DeliveryDate,'yyyy-MM-dd') as OrderDate,sum(TotalPrice)as TotalPrice from APS_OrderDiscounts 
           where FORMAT(DeliveryDate,'yyyy-MM') = '{0}' group by FORMAT(DeliveryDate,'yyyy-MM-dd')
    ", YearMonth));

            //未结束销售订单
            DtDetail9 = SqlHelper.ExecuteDataTable(string.Format(@"
           select LEFT(SalesOrderID,4) as OrderType,sum(Q1*PeoplePrice) as TotalPrice From V_APS_SalesOrderDetailALL
            where ParamsLabel = '未结束' and FORMAT(OrderDate,'yyyy-MM')= FORMAT(GETDATE(),'yyyy-MM')
            group by LEFT(SalesOrderID,4)
    "));
            DtDetail10 = SqlHelper.ExecuteDataTable(string.Format(@"
           select sum(OweQtyPrice) as TotalPrice From V_APS_SalesOrderDetailDeliver3  
    "));

            dt.Columns.Add("BColors", typeof(Dictionary<string, string>));




        }

