        /// <summary>
        /// 月度接单汇总
        /// </summary>
        /// <param name="dt"></param>
        public void SetDt23364(ref DataTable dt)
        {



            int YearTime = 0;

            DateTime today = DateTime.Now;  // 获取当前日期

            if (jObject.ContainsKey("YearTime") == true)
            {
                if (string.IsNullOrEmpty(jObject["YearTime"].ToString()))
                {
                    YearTime = today.Year;
                }
                else
                {
                    YearTime = int.Parse(jObject["YearTime"].ToString());
                }

            }
            else
            {
                YearTime = today.Year;
            }



            DateTime StartDate = new DateTime(YearTime, 1, 1); // 获取当前月的第一天
