        /// <summary>
        /// 将工单工序转入周计划
        /// </summary>
        /// <returns></returns>
        public string ToXHWeekPlan()
        {
            bool result = true;
            string msg = "操作成功";

            try
            {
                jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;


                foreach (JObject jObject in jArray)
                {
                    if (!string.IsNullOrEmpty(jObject["OrderID"].ToString()) && !string.IsNullOrEmpty(jObject["ProcessPartID"].ToString()))
                    {

                        string ProcessPartID = jObject["ProcessPartID"].ToString();
                        SqlHelper.ExecuteDataTable(string.Format(
                           @"update a set a.ProductionStatus = 21  from APS_ProcessPartPlan a where ProcessPartID = '{0}' ", ProcessPartID));
                        //SqlParameter[] sqlParameters = new SqlParameter[4];
                        //sqlParameters[0] = new SqlParameter("@OrderID", jObject["OrderID"].ToString());//订单ID
                        //sqlParameters[1] = new SqlParameter("@OrderID", jObject["ProcessID"].ToString());//订单ID
                        //sqlParameters[2] = new SqlParameter("@Result", SqlDbType.Bit);//结果ID
                        //sqlParameters[3] = new SqlParameter("@Msg", SqlDbType.Bit);//信息
                        //sqlParameters[2].Direction = sqlParameters[3].Direction = ParameterDirection.Output;
                        //SqlHelper.ExecuteNonQuery(SqlHelper.MSSQLConnectionString, "P_APS_InsertIntoIMByOrderID", sqlParameters);
                    }

                }

            }
            catch (Exception ex)
            {
                result = false;
                msg = "数据操作失败,错误信息:" + ex.Message;
            }
            return JsonConvert.SerializeObject(new
            {

                result,
                msg
            });
        }

