        /// <summary>
        /// 日计划重排
        /// </summary>
        /// <returns></returns>
        public string DayPlanReset()
        {
            bool result = true;
            string msg = "操作成功";

            try
            {
                jObject = JsonConvert.DeserializeObject(BodyJson) as JObject;

                if (jObject == null)
                {
                    jObject = ((JArray)JsonConvert.DeserializeObject(BodyJson))[0] as JObject;
                }
                string ProcessPartName = jObject["ProcessPartName"].ToString();
                string DataSource = jObject["DataSource"].ToString();
                if (!string.IsNullOrEmpty(ProcessPartName))
                {
                    SqlHelper.ExecuteNonQuery($@"EXEC  [dbo].[P_APS_DayPlanReset]
		@ProcessPartName = '{ProcessPartName}',@DataSource = '{DataSource}' ");
                }
                else
                {
                    result = false;
                    msg = "未接收到工段名称";
                }


            }
            catch (Exception ex)
            {
                result = false;
                msg = "数据操作失败,错误信息:" + ex.Message;
            }
            return JsonConvert.SerializeObject(new
            {

                result,
                msg
            });
        }


        /// <summary>
        ///  用户在线统计
        /// </summary>
        /// <param name="dt"></param>
        public void SetDt24366(ref DataTable dt)
        {


            DateTime endDate = DateTime.Now.Date;
            DateTime startDate = endDate.AddDays(-14);








            if (jObject.ContainsKey("DynamicDate1"))
            {
                JArray jArray = jObject["DynamicDate1"] as JArray;
                if (!string.IsNullOrEmpty(jArray[0].ToString()))
                {
                    startDate = DateTime.Parse(jArray[0].ToString());
                    endDate = DateTime.Parse(jArray[1].ToString());
                }
            }



            //  DtDetail3 = SqlHelper.ExecuteDataTable(string.Format(@"
            //            	select DepartmentName,CreatedByName,CreatedBy,COUNT(*) as DayCount
            //             from(
            //             select DepartmentName,CreatedByName,CreatedBy,CreatedOn
            //             from V_PWS_WageTrendReport 
            //                where CreatedOn >= '{0}' and CreatedOn <= '{1}' 
            //             group by DepartmentName,CreatedByName,CreatedBy,CreatedOn
            //             ) as a
            //              where 1=1 {2}
            //             group by DepartmentName,CreatedByName,CreatedBy
            //             Order by DepartmentName

            //", string.Format("{0:yyyy-MM-dd}", startDate), string.Format("{0:yyyy-MM-dd}", endDate), mSSQLCore.ResultWhere));












            //  dt = DtDetail3;

            dt.Columns.Add("BColors", typeof(Dictionary<string, string>));

            DtDetail = SqlHelper.ExecuteDataTable(string.Format(@"

                   select DepartmentName,CreatedByName,CreatedBy,CreatedOn
                      from V_PWS_WageTrendReport 
	
                   where CreatedOn >= '{0}' and CreatedOn <= '{1}'
                   group by DepartmentName,CreatedByName,CreatedBy,CreatedOn
          ", string.Format("{0:yyyy-MM-dd}", startDate), string.Format("{0:yyyy-MM-dd}", endDate)));

            while (endDate >= startDate)
            {
                string prop = string.Format("{0:yyyy-MM-dd}", startDate);





                dt.Columns.Add(prop, typeof(decimal));
                ElementColumn[0].Add(new ElementTableOuput() { label = prop, prop = prop, width = "80", isEdit = false, ControlType = "numberbox" });
                //求和
                mSSQLCore.Dev_DictionaryFields.Add(new Dev_DictionaryField() { FooterType = "SUM", ParameterName = prop, DataType = "decimal", IsVisible = true });


                startDate = startDate.AddDays(1);



            }

        }
        /// <summary>
        /// 用户在线统计
        /// </summary>
        /// <param name="dataRow"></param>
        public void setDetail24366(DataRow dataRow)
        {
            DateTime endDate = DateTime.Now.Date;
            DateTime startDate = endDate.AddDays(-14);
            if (jObject.ContainsKey("DynamicDate1"))
            {
                JArray jArray = jObject["DynamicDate1"] as JArray;
                if (!string.IsNullOrEmpty(jArray[0].ToString()))
                {
                    startDate = DateTime.Parse(jArray[0].ToString());
                    endDate = DateTime.Parse(jArray[1].ToString());
                }
            }

            Dictionary<string, string> bColors = new Dictionary<string, string>(); // 背景颜色




            while (startDate <= endDate)
            {
                string prop = string.Format("{0:yyyy-MM-dd}", startDate);
                DataRow[] dataRows = DtDetail.Select("DepartmentName='" + dataRow["DepartmentName"] + "'" + "and CreatedByName='" + dataRow["CreatedByName"] + "'" +
                    "and CreatedBy='" + dataRow["CreatedBy"] + "'" +
                    " and CreatedOn='" + prop + "'");


                if (dataRows != null && dataRows.Length > 0)
                {
                    dataRow[prop] = 1;

                }


                startDate = startDate.AddDays(1);
            }





            dataRow["BColors"] = bColors;
        }




        /// <summary>
        /// 机台负荷
        /// </summary>
        /// <param name="dt"></param>
        public void SetDt24365(ref DataTable dt)
        {

            DateTime startDate = DateTime.Now.Date;
            DateTime endDate = startDate.AddDays(30);
            if (jObject.ContainsKey("DynamicDate1"))
            {
                JArray jArray = jObject["DynamicDate1"] as JArray;
                if (!string.IsNullOrEmpty(jArray[0].ToString()))
                {
                    startDate = DateTime.Parse(jArray[0].ToString());
                    endDate = DateTime.Parse(jArray[1].ToString());
                }

            }



            DtDetail = SqlHelper.ExecuteDataTable(string.Format(@"
          SELECT PlanDay,Sum(ExpectTime)  AS Hours,LineID
                            FROM   APS_DayPlan 
		              WHERE  ProcessPlanID IN (SELECT ProcessPlanID FROM V_APS_MOPlanStep4V9)
                            AND   PlanDay >= '{0}' and PlanDay<='{1}'
                            GROUP  BY PlanDay,LineID
            ", startDate, endDate));

            DtDetail1 = SqlHelper.ExecuteDataTable(string.Format(@"
          SELECT a.WorkingDate,
                 a.OrganizeID AS LineID,
                 a.TotalHours,
                 a.WorkingTimesID,   
                 A2.OrganizeName AS LineName
          FROM   APS_OrganizeWorkingTimesDetail A
                 INNER JOIN Dev_Organize A2
                         ON A.OrganizeID = A2.OrganizeID
	   	              WHERE A.OrganizeID IN 
             (SELECT A.OrganizeID FROM APS_OrganizeProcessID A 
             INNER JOIN APS_Process B 
             ON A.ProcessID = B.ProcessID 
             AND B.ProcessPartName IN ( '压铸', '冲压','注塑') )  
          AND WorkingDate>='{0}' and WorkingDate<='{1}'", startDate, endDate));
            dt.Columns.Add("BColors", typeof(Dictionary<string, string>));
            while (endDate >= startDate)
            {

                string day = string.Format("{0:MM-dd}", startDate);

                dt.Columns.Add(day);


                ElementColumn[0].Add(new ElementTableOuput() { label = day, prop = day, width = "60", prop2 = day, isEdit = true, ControlType = "datebox" });
                startDate = startDate.AddDays(1);

            }

        }
        /// <summary>
        /// 机台负荷
        /// </summary>
        /// <param name="dataRow"></param>
        public void setDetail24365(DataRow dataRow)
        {
            DateTime startDate = DateTime.Now.Date;
            DateTime endDate = startDate.AddDays(30);
            if (jObject.ContainsKey("DynamicDate1"))
            {
                JArray jArray = jObject["DynamicDate1"] as JArray;
                if (!string.IsNullOrEmpty(jArray[0].ToString()))
                {
                    startDate = DateTime.Parse(jArray[0].ToString());
                    endDate = DateTime.Parse(jArray[1].ToString());
                }

            }
            Dictionary<string, string> bColors = new Dictionary<string, string>();//背景颜色
            while (endDate >= startDate)
            {

                string day = string.Format("{0:MM-dd}", startDate);


                string s1 = DtDetail.Compute("SUM(Hours)", "LineID='" + dataRow["LineID"] + "'AND PlanDay='" + startDate + "'").ToString();
                string s2 = DtDetail1.Compute("SUM(TotalHours)", "LineID='" + dataRow["LineID"] + "'  AND WorkingDate='" + startDate + "'").ToString();

                decimal m1, m2;
                decimal.TryParse(s1, out m1);
                decimal.TryParse(s2, out m2);
                string rowType = dataRow["RowType"].ToString();

                if (m2 > 0)
                {
                    if (rowType == "1计划工时")
                    {
                        dataRow[day] = m1;
                        bColors.Add(day, "#7FAFFC");
                    }
                    else if (rowType == "2出勤工时")
                    {
                        dataRow[day] = m2;
                        bColors.Add(day, "#BBFBB8");
                    }
                    else if (rowType == "3负荷")
                    {

                        dataRow[day] = Math.Round(m1 / m2, 2);

                        if (m2 * 1.1M < m1)
                        {//工时超过
                            bColors.Add(day, "#FF0000");
                        }
                        else if (m2 * 0.8M > m1)
                        {//工时不足
                            bColors.Add(day, "#FEFF00");
                        }


                    }





                }
                else if (!string.IsNullOrEmpty(s1))
                {//有上班，但是没工时

                    //bColors.Add(day, "#F569F3");
                }


                startDate = startDate.AddDays(1);
            }
            dataRow["BColors"] = bColors;
        }





