        /// <summary>
        /// 星河匹配模具机台
        /// </summary>
        /// <returns></returns>
        public string MatchIMMachine1()
        {
            bool result = true;
            string msg = "操作成功";

            try
            {
                jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;
                string sql = "truncate table APS_OrderPlanSheculing;";
                foreach (JObject jObject in jArray)
                {
                    if (!string.IsNullOrEmpty(jObject["OrderID"].ToString()))
                    {

                        sql += "INSERT INTO [APS_OrderPlanSheculing](OrderID,ProcessID,CreatedBy) values(" + jObject["OrderID"].ToString() + ",'" + jObject["ProcessID"].ToString() + "'" + ",'" + dev_Account.Account + "')";
                    }

                }
                if (!string.IsNullOrEmpty(sql))
                {
                    SqlHelper.ExecuteNonQuery(sql);
                    SqlParameter[] sqlParameters = new SqlParameter[3];
                    sqlParameters[0] = new SqlParameter("@Account", dev_Account.Account);//账号
                    sqlParameters[1] = new SqlParameter("@Result", SqlDbType.Bit);//结果ID
                    sqlParameters[2] = new SqlParameter("@Msg", SqlDbType.Bit);//信息
                    sqlParameters[1].Direction = sqlParameters[2].Direction = ParameterDirection.Output;
                    SqlHelper.ExecuteNonQuery(SqlHelper.MSSQLConnectionString, "P_APS_MatchIMMachine", sqlParameters);
                }

            }
            catch (Exception ex)
            {
                result = false;
                msg = "数据操作失败,错误信息:" + ex.Message;
            }
            return JsonConvert.SerializeObject(new
            {

                result,
                msg
            });
        }




