        /// <summary>
        /// 每月按周统计接单/出货金额
        /// </summary>
        /// <param name="dt"></param>
        public void SetDt24443(ref DataTable dt)
        {

            DateTime StartDate;
            DateTime EndDate;
            string YearMonth = null;
            DateTime today = DateTime.Now.AddDays(-10);  // 获取当前日期

            if (jObject.ContainsKey("YearMonth") == true)
            {
                YearMonth = jObject["YearMonth"].ToString();
                StartDate = DateTime.Parse(string.Concat(YearMonth, "-01"));
                EndDate = DateTime.Parse(string.Concat(YearMonth, "-", DateTime.DaysInMonth(StartDate.Year, StartDate.Month)));


            }
            else
            {
                YearMonth = string.Format("yyyy-MM", today);
                StartDate = new DateTime(today.Year, today.Month, 01);
                EndDate = new DateTime(StartDate.Year, StartDate.Month, DateTime.DaysInMonth(StartDate.Year, StartDate.Month));

            }




            while (StartDate <= EndDate)
            {

                DateTime startOfWeek;
                if ((int)StartDate.DayOfWeek != 0)
                {
                    startOfWeek = StartDate.AddDays(-(int)StartDate.DayOfWeek + (int)DayOfWeek.Monday);  // 计算本周周一的日期
                }
                else
                {
                    startOfWeek = StartDate.AddDays(-6);
                }
                DateTime endOfWeek = startOfWeek.AddDays(6);  // 计算本周周日的日期


                DateTime lastDayOfMonth = new DateTime(StartDate.Year, StartDate.Month, DateTime.DaysInMonth(StartDate.Year, StartDate.Month)); //月末日期

                DateTime firstDayOfMonth = new DateTime(StartDate.Year, StartDate.Month, 1); // 获取当前月的第一天
                                                                                             //本周初
                if (startOfWeek < firstDayOfMonth)
                {
                    startOfWeek = firstDayOfMonth;
                }
                //本周末
                if (endOfWeek > lastDayOfMonth)
                {
                    endOfWeek = lastDayOfMonth;
                }



                string label = string.Format("{0:MM/dd}~{1:MM/dd}", startOfWeek, endOfWeek);
                string prop = string.Format("{0:yyyy-MM-dd}", startOfWeek);
                dt.Columns.Add(prop);
                ElementColumn[0].Add(new ElementTableOuput() { label = label, prop = prop, width = "110", isEdit = false, ControlType = "numberbox" });
                //求和
                //mSSQLCore.Dev_DictionaryFields.Add(new Dev_DictionaryField() { FooterType = "SUM", ParameterName = prop, DataType = "decimal", IsVisible = true });


                StartDate = endOfWeek.AddDays(1);
            }





            //dt.Columns.Add("Summary", typeof(string));
            //ElementColumn[0].Add(new ElementTableOuput() { label = "汇总", prop = "Summary", width = "80", isEdit = false, ControlType = "textbox" });


            //接单
            DtDetail = SqlHelper.ExecuteDataTable(string.Format(@"
         select FORMAT(OrderDate,'yyyy-MM-dd') as OrderDate,sum(TotalPrice)as TotalPrice,sum(Qty) as TotalQty from APS_OrderDelivery where
          FORMAT(OrderDate,'yyyy-MM') = '{0}' group by FORMAT(OrderDate,'yyyy-MM-dd')
     ", YearMonth));


            //出货
            DtDetail2 = SqlHelper.ExecuteDataTable(string.Format(@"
     select FORMAT(DeliveryDate,'yyyy-MM-dd') as OrderDate,sum(TotalPrice)as TotalPrice,sum(Qty) as TotalQty 
     from APS_OrdeSales a
    
     where  FORMAT(DeliveryDate,'yyyy-MM') = '{0}' 
     group by FORMAT(a.DeliveryDate,'yyyy-MM-dd')
     ", YearMonth));

            DtDetail3 = SqlHelper.ExecuteDataTable(string.Format(@"
     select FORMAT(DeliveryDate,'yyyy-MM-dd') as OrderDate,sum(TotalPrice)as TotalPrice,sum(Qty) as TotalQty 
     from APS_OrderAllot a
  
     where  FORMAT(DeliveryDate,'yyyy-MM') = '{0}'
     group by FORMAT(DeliveryDate,'yyyy-MM-dd')
     ", YearMonth));


            //退货
            DtDetail4 = SqlHelper.ExecuteDataTable(string.Format(@"
            select FORMAT(DeliveryDate,'yyyy-MM-dd') as OrderDate,sum(TotalPrice)as TotalPrice,sum(Qty) as TotalQty  
            from APS_SalesReturnOrder a
         
            where  FORMAT(DeliveryDate,'yyyy-MM') = '{0}'
            group by FORMAT(DeliveryDate,'yyyy-MM-dd')
            ", YearMonth));

            DtDetail5 = SqlHelper.ExecuteDataTable(string.Format(@"
            select FORMAT(DeliveryDate,'yyyy-MM-dd') as OrderDate,sum(TotalPrice)as TotalPrice ,sum(Qty) as TotalQty  
            from APS_OrderReturn a
         
            where  FORMAT(DeliveryDate,'yyyy-MM') = '{0}'
            group by FORMAT(DeliveryDate,'yyyy-MM-dd')
            ", YearMonth));

            DtDetail6 = SqlHelper.ExecuteDataTable(string.Format(@"
            select FORMAT(DeliveryDate,'yyyy-MM-dd') as OrderDate,sum(TotalPrice)as TotalPrice  ,sum(Qty) as TotalQty  
            from APS_OrderDiscounts a
         
            where  FORMAT(DeliveryDate,'yyyy-MM') = '{0}'
            group by FORMAT(DeliveryDate,'yyyy-MM-dd')
            ", YearMonth));


            dt.Columns.Add("BColors", typeof(Dictionary<string, string>));




        }

