        /// <summary>
        /// 写入产能、主辅线
        /// </summary>
        /// <returns></returns>
        public ApsLegacyJsonResult APSProcessMaterialInsert()
        {
            bool result = true;
            string msg = "";
            ApsLegacyJsonResult ApsLegacyJsonResult = new ApsLegacyJsonResult();
            try
            {

                JArray jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;
                if (jArray == null || jArray.Count == 0)
                {
                    msg = "未接受到数据，请确认是否为JSON格式";
                    result = false;
                }
                else
                {
                    foreach (JObject jObject in jArray)
                    {
                        SqlParameter[] sqlParameters = new SqlParameter[6];
                        sqlParameters[0] = new SqlParameter("@MaterialID", jObject["MaterialID"].ToString());//物料ID
                        sqlParameters[1] = new SqlParameter("@ProcessID", jObject["ProcessID"].ToString());//工序ID
                        sqlParameters[2] = new SqlParameter("@OrganizeID", jObject["OrganizeID"].ToString());//产线ID
                        sqlParameters[3] = new SqlParameter("@IsLineCapacity", Convert.ToBoolean(jObject["IsLineCapacity"]) == true ? 1 : 0); //分线产能  1：分线维护产能，0：工序产能
                        sqlParameters[4] = new SqlParameter("@Result", SqlDbType.Bit);//结果
                        sqlParameters[5] = new SqlParameter("@Msg", SqlDbType.NVarChar, 500);//信息
                        sqlParameters[4].Direction = sqlParameters[5].Direction = ParameterDirection.Output;
                        SqlHelper.ExecuteNonQuery(SqlHelper.MSSQLConnectionString, "P_APS_ProcessMaterialInsert", sqlParameters);
                        result = sqlParameters[4].Value.ToString().ToLower() == "true";
                        msg = sqlParameters[5].Value.ToString();

                    }
                }

            }
            catch (Exception ex)
            {
                result = false;
                msg = "数据操作失败,错误信息:" + ex.Message;

            }
            ApsLegacyJsonResult = base.FormResult(result, msg, null);
            return ApsLegacyJsonResult;
        }
