        public string MultiUpload(string nickName, IEnumerable<HttpPostedFileBase> files, string directoryName)
        {
            List<object> uploadResults = new List<object>();
            ApsLegacyJsonResult json = new ApsLegacyJsonResult();

            try
            {
                if (files != null && files.Any(f => f != null && f.ContentLength > 0))
                {
                    string directoryPath = Server.MapPath($"~/{directoryName}");

                    // Create directory if it doesn't exist
                    if (!Directory.Exists(directoryPath))
                    {
                        Directory.CreateDirectory(directoryPath);
                    }

                    foreach (var file in files)
                    {
                        if (file == null || file.ContentLength == 0)
                            continue;

                        string msg;
                        bool result;
                        string fileName = nickName + "_" + Guid.NewGuid().ToString().Substring(0, 8) + Path.GetExtension(file.FileName);
                        string filePath = Path.Combine(directoryPath, fileName);

                        try
                        {
                            file.SaveAs(filePath);

                            string relativePath = $"/{directoryName}/{fileName}".Replace("\\", "/");

                            uploadResults.Add(new
                            {
                                msg = "上传成功",
                                result = true,
                                nickName,
                                filePath = relativePath,
                                fileName,
                                originalFileName = file.FileName
                            });
                        }
                        catch (Exception ex)
                        {
                            uploadResults.Add(new
                            {
                                msg = $"文件 {file.FileName} 上传失败: {ex.Message}",
                                result = false,
                                nickName,
                                filePath = string.Empty,
                                fileName = string.Empty,
                                originalFileName = file.FileName
                            });
                        }
                    }

                    // Check if any files were successfully processed
                    if (uploadResults.Any(r => (bool)((dynamic)r).result))
                    {
                        json.Data = new
                        {
                            msg = "部分或全部文件上传完成",
                            result = true,
                            uploadResults
                        };
                    }
                    else
                    {
                        json.Data = new
                        {
                            msg = "所有文件上传失败",
                            result = false,
                            uploadResults
                        };
                    }
                }
                else
                {
                    json.Data = new
                    {
                        msg = "没有有效的文件上传",
                        result = false
                    };
                }
            }
            catch (Exception ex)
            {
                json.Data = new
                {
                    msg = $"上传过程中发生错误: {ex.Message}",
                    result = false
                };
            }

            json.JsonRequestBehavior = JsonRequestBehavior.AllowGet;
            return JsonConvert.SerializeObject(json.Data);
        }

        //上传图片和文件
        public string Upload(string nickName, HttpPostedFileBase file, string directoryName)
        {
            string msg;
            bool result;
            ApsLegacyJsonResult json = new ApsLegacyJsonResult();

            try
            {

                if (file != null && file.ContentLength > 0)
                {
                    msg = "上传成功";
                    result = true;
                    //string fileName = Guid.NewGuid().ToString("N").Substring(0, 4) + "_" + Path.GetFileName(file.FileName);
                    string fileName = Path.GetFileNameWithoutExtension(file.FileName) + "_" + Guid.NewGuid().ToString("N").Substring(0, 4) + Path.GetExtension(file.FileName);
                    // 检测并创建 Avatar 文件夹
                    string directoryPath = Server.MapPath($"~/{directoryName}");// 文件夹路径 
                    if (!Directory.Exists(directoryPath)) // 检测文件夹是否存在
                    {
                        // 如果文件夹不存在，创建文件夹
                        Directory.CreateDirectory(directoryPath);
                    }

                    var path = Path.Combine(directoryPath, fileName); // 合并地址
                    file.SaveAs(path);  // 保存图片或文件


                    path = string.Concat("/", directoryName, "/", fileName).Replace("\\", "/");


                    json.Data = new { msg, result, nickName, filePath = path, fileName };
                    json.JsonRequestBehavior = JsonRequestBehavior.AllowGet;
                }
                else
                {
                    msg = "上传失败";
                    result = false;
                    json.Data = new { msg = msg, result = result };
                    json.JsonRequestBehavior = JsonRequestBehavior.AllowGet;
                }

            }
            catch (Exception ex)
            {
                json.Data = new { msg = ex.Message, result = false };
                json.JsonRequestBehavior = JsonRequestBehavior.AllowGet;
            }

            return JsonConvert.SerializeObject(json.Data);
        }
