        /// <summary>
        /// 派工加工记录
        /// </summary>
        /// <returns></returns>
        public string HandleTaskManagement()
        {
            bool result = true;
            string msg = "";
            int id = 0; // 用于存储新增记录的ID
            try
            {
                jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;
                if (jArray.Count == 0)
                {
                    result = false;
                    msg = "未接受到数据";
                }
                else
                {
                    string reportID = jArray[0]["ReportID"].ToString();
                    string names = jArray[0]["Names"].ToString();
                    string submitType = jArray[0]["SubmitType"].ToString();
                    string abnormalReasonId = jArray[0]["AbnormalReasonID"]?.ToString() ?? string.Empty;
                    string abnormalDescription = jArray[0]["AbnormalDescription"]?.ToString() ?? string.Empty;
                    string taskProgress = jArray[0]["TaskProgress"]?.ToString() ?? string.Empty;
                    string childMaterialCode = jArray[0]["ChildMaterialCode"]?.ToString() ?? string.Empty;
                    SqlParameter[] sqlParameters = new SqlParameter[11];
                    sqlParameters[0] = new SqlParameter("@ReportID", reportID);//任务ID
                    sqlParameters[1] = new SqlParameter("@Names", names);//工人
                    sqlParameters[2] = new SqlParameter("@SubmitType", submitType);//按钮类型
                    sqlParameters[3] = new SqlParameter("@AbnormalReasonID", abnormalReasonId);//异常ID
                    sqlParameters[4] = new SqlParameter("@AbnormalDescription", abnormalDescription);//异常描述
                    sqlParameters[5] = new SqlParameter("@TaskProgress", taskProgress);//异常描述
                    sqlParameters[6] = new SqlParameter("@Result", SqlDbType.Bit);//结果
                    sqlParameters[7] = new SqlParameter("@Msg", SqlDbType.NVarChar, 500);//信息
                    sqlParameters[8] = new SqlParameter("@ID", SqlDbType.Int); // 新增记录的ID
                    sqlParameters[9] = new SqlParameter("@CreatedBy", dev_Account.Account); // 新增记录的ID
                    sqlParameters[10] = new SqlParameter("@ChildMaterialCode", childMaterialCode); // 新增记录的ID
                    sqlParameters[6].Direction = sqlParameters[7].Direction = sqlParameters[8].Direction = ParameterDirection.Output;
                    SqlHelper.ExecuteNonQuery(SqlHelper.MSSQLConnectionString, "P_APS_BOMInstallReportRecord", sqlParameters);
                    result = sqlParameters[6].Value.ToString().ToLower() == "true";
                    msg = sqlParameters[7].Value.ToString();
                    // 如果SubmitType为3，并且操作成功，获取新增记录的ID，3为提报异常
                    if (submitType == "3" && result)
                    {
                        if (sqlParameters[8].Value != DBNull.Value)
                        {
                            id = Convert.ToInt32(sqlParameters[8].Value);
                        }
                    }
                }

            }
            catch (Exception ex)
            {
                result = false;
                msg = "数据操作失败,错误信息:" + ex.Message;
            }
            return JsonConvert.SerializeObject(new
            {

                result,
                msg,
                id
            });
        }
        /// <summary>
        /// 异常描述/解决描述上传图片或视频
        /// </summary>
        /// <param name="nickName"></param>
        /// <param name="file"></param>
        /// <param name="id"></param>
        /// <param name="resolutionStatus"></param>
        /// <returns></returns>
        public string UploadAbnomalImages(string nickName, HttpPostedFileBase file, int id, int resolutionStatus, int dicID)
        {
            //后续要对该方法进行优化，优化目的为能处理string类型的id
            string msg;
            bool result;
            ApsLegacyJsonResult json = new ApsLegacyJsonResult();

            // 参数检查
            if (string.IsNullOrEmpty(nickName) || file == null || file.ContentLength == 0 || id == null || id < 0)
            {
                msg = "上传失败: 请检查传参";
                result = false;
                json.Data = new { msg, result };
                HttpContext.Response.StatusCode = 400; // 对于ASP.NET
                return JsonConvert.SerializeObject(json.Data);
            }

            // 检查文件类型
            string ext = Path.GetExtension(file.FileName).ToLower();
            bool isImage = ext == ".jpg" || ext == ".jpeg" || ext == ".png";
            bool isVideo = ext == ".mp4" || ext == ".avi" || ext == ".mov"; // 添加更多视频格式如果需要

            if (!isImage && !isVideo)
            {
                msg = $"文件 {file.FileName} 不是有效的图片或视频格式（图片支持.jpg/.jpeg/.png，视频支持.mp4/.avi/.mov）";
                result = false;
                json.Data = new { msg, result };
                HttpContext.Response.StatusCode = 400; // 对于ASP.NET
                return JsonConvert.SerializeObject(json.Data);
            }

            try
            {
                // 获取表名
                string tableName = "";
                string sqlGetTableName = "SELECT TabelName FROM Dev_Dictionary WHERE DictionaryID = @DictionaryID";
                SqlParameter[] parametersGetTableName = { new SqlParameter("@DictionaryID", dicID) };

                using (SqlDataReader reader = SqlHelper.ExecuteReader(SqlHelper.MSSQLConnectionString, CommandType.Text, sqlGetTableName, parametersGetTableName))
                {
                    if (reader.Read())
                    {
                        tableName = reader["TabelName"]?.ToString();
                    }
                }

                if (string.IsNullOrEmpty(tableName))
                {
                    msg = "上传失败: 未找到对应的表名配置";
                    result = false;
                    json.Data = new { msg, result };
                    HttpContext.Response.StatusCode = 400;
                    return JsonConvert.SerializeObject(json.Data);
                }
                // 查询表的主键
                string primaryKey = "";
                string sqlGetPrimaryKey = @"
                    SELECT ParameterName 
                    FROM Dev_DictionaryField
                    WHERE DictionaryID = @DictionaryID AND IsKey = 1";

                SqlParameter[] parametersGetPK = { new SqlParameter("@DictionaryID", dicID) };

                using (SqlDataReader reader = SqlHelper.ExecuteReader(SqlHelper.MSSQLConnectionString, CommandType.Text, sqlGetPrimaryKey, parametersGetPK))
                {
                    if (reader.Read())
                    {
                        primaryKey = reader["ParameterName"].ToString();
                    }
                }
                // 根据resolutionStatus和文件类型确定存储目录
                string directoryName;
                if (resolutionStatus == 0)
                {
                    directoryName = isImage ? "Abnormal/AbnormalPhoto" : "Abnormal/AbnormalVideo";
                }
                else
                {
                    directoryName = isImage ? "Resolution/ResolutionPhoto" : "Resolution/ResolutionVideo";
                }

                string directoryPath = Server.MapPath($"~/{directoryName}");
                // 目录创建和权限检查
                try
                {
                    if (!Directory.Exists(directoryPath))
                    {
                        Directory.CreateDirectory(directoryPath);
                    }
                }
                catch (UnauthorizedAccessException)
                {
                    msg = "上传失败: 无权限创建目录";
                    result = false;
                    json.Data = new { msg, result };
                    HttpContext.Response.StatusCode = 400; // 对于ASP.NET
                    return JsonConvert.SerializeObject(json.Data);
                }

                // 生成文件名和路径
                string fileName = nickName + "_" + DateTime.Now.ToString("yyyyMMddHHmmssfff") + "_" +
                                 Guid.NewGuid().ToString().Substring(0, 8) + ext;
                string filePath = Path.Combine(directoryPath, fileName);
                string relativePath = $"/{directoryName}/{fileName}".Replace("\\", "/");

                // 保存文件
                file.SaveAs(filePath);

                // 根据resolutionStatus确定更新哪个字段
                string fileNameField = resolutionStatus == 0 ? "FileName" : "FileName2";
                string filePathField = resolutionStatus == 0 ? "FilePath" : "FilePath2";

                //更新数据库
                string sql = $@"UPDATE {tableName}  
                            SET {fileNameField} = CASE 
                                                  WHEN {fileNameField} IS NULL OR {fileNameField} = '' THEN @FileName
                                                  ELSE {fileNameField} + ',' + @FileName
                                                END,
                                {filePathField} = CASE 
                                                 WHEN {filePathField} IS NULL OR {filePathField} = '' THEN @FilePath
                                                 ELSE {filePathField} + ',' + @FilePath
                                               END
                            WHERE {primaryKey} = @ID";

                SqlParameter[] parameters = {
                    new SqlParameter("@FileName", fileName),
                    new SqlParameter("@FilePath", relativePath), // 使用相对路径
                    new SqlParameter("@ID", id)};



                SqlHelper.ExecuteNonQuery(SqlHelper.MSSQLConnectionString, CommandType.Text, sql, parameters);


                msg = "文件成功上传";
                result = true;
                json.Data = new
                {
                    msg,
                    result
                };
            }
            catch (Exception ex)
            {
                msg = "上传失败: " + ex.Message;
                result = false;
                json.Data = new { msg, result };
                HttpContext.Response.StatusCode = 400; // 对于ASP.NET
            }

            return JsonConvert.SerializeObject(json.Data);
        }

        public ActionResult ViewPDF(int id = 0, int down = 0)
        {

            DataTable dt = SqlHelper.ExecuteDataTable(@"select FilePath,Code from [APS_Material]
where MaterialID=" + id);
            string code = "";
            if (dt.Rows.Count > 0 && dev_Account != null)
            {
                string filePath = dt.Rows[0]["FilePath"].ToString();//Server.MapPath("~/App_Data/SimHei.ttf")，使用这个代码，路径写入
                code = dt.Rows[0]["Code"].ToString();
                if (filePath.StartsWith("D:\\") == false)
                {
                    filePath = Server.MapPath(filePath);
                }

                if (!System.IO.File.Exists(filePath))
                {
                    return HttpNotFound("PDF 文件不存在");
                }

                // 读取 PDF 文件并生成水印
                byte[] fileBytes = base.AddWatermarkToPdf(filePath, dev_Account.Name + string.Format("{0:yyyy-MM-dd HH:mm:ss}", DateTime.Now) + "查阅");
                string filename = code + ".pdf";
                // 返回修改后的 PDF 给前端
                if (down == 0)
                {
                    Response.Headers.Add("Content-Disposition", $"inline; filename=\"{filename}\"");
                    systemLog.SaveLog(Licence.SystemLog.SystemLogType.查看PDF, dev_Account.Name + "查看了物料" + dt.Rows[0]["Code"].ToString() + "的PDF文件");
                    return File(fileBytes, "application/pdf");
                }
                else
                {
                    systemLog.SaveLog(Licence.SystemLog.SystemLogType.下载PDF, dev_Account.Name + "下载了物料" + dt.Rows[0]["Code"].ToString() + "的PDF文件");
                    return File(fileBytes, "application/pdf", filename);
                }



            }
            else
            {

                return HttpNotFound("PDF 文件不存在");

            }

        }
