        /// <returns></returns>
        public string DeleteInbountData()
        {
            bool result = true;
            string msg = "";
            JObject jObject = JsonConvert.DeserializeObject(BodyJson) as JObject;

            if (jObject == null)
            {
                msg = "未接收到数据，请确认是否为JSON格式";
                result = false;
                return JsonConvert.SerializeObject(new
                {

                    result,
                    msg
                });
            }
            else
            {
                if (jObject.ContainsKey("ReceiptID") == true && jObject.ContainsKey("Remark") == true)
                {
                    string ReceiptID = jObject["ReceiptID"].ToString();
                    string Remark = jObject["Remark"]?.ToString() ?? string.Empty;
                    string DataType = "入库";
                    SqlParameter[] sqlParameters = new SqlParameter[7];
                    sqlParameters[0] = new SqlParameter("@ReceiptID", ReceiptID);//
                    sqlParameters[1] = new SqlParameter("@Remark", Remark);//
                    sqlParameters[2] = new SqlParameter("@DataType", DataType);
                    sqlParameters[3] = new SqlParameter("@Account", dev_Account.Account);
                    sqlParameters[4] = new SqlParameter("@Name", dev_Account.Name);
                    sqlParameters[5] = new SqlParameter("@Result", SqlDbType.Bit);//结果
                    sqlParameters[6] = new SqlParameter("@Msg", SqlDbType.NVarChar, 500);//信息
                    sqlParameters[6].Direction = sqlParameters[5].Direction = ParameterDirection.Output;
                    SqlHelper.ExecuteNonQuery(SqlHelper.MSSQLConnectionString, "P_APS_DeleteInbountData", sqlParameters);
                    result = sqlParameters[5].Value.ToString().ToLower() == "true";
                    msg = sqlParameters[6].Value.ToString();
                    return JsonConvert.SerializeObject(new
                    {

                        result,
                        msg
                    });

                }
                else
                {
                    msg = "没有传ReceiptID或者Remark";
                    result = false;
                    return JsonConvert.SerializeObject(new
                    {

                        result,
                        msg
                    });
                }





            }
        }
