        /// <summary>
        /// 欧赛计划审批
        /// </summary>
        /// <returns></returns>
        public string ApprovalImportOSPlanData()
        {
            bool result = true;
            string msg = "";
            try
            {
                JArray jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;

                if (jArray == null || jArray.Count == 0)
                {
                    result = false;
                    msg = "未接受到数据";
                }
                else
                {
                    //现在待审批和审批退回不是一个页签，按道理不需要用到事务，但是考虑到A用户退回，B用户没刷新页面，以下代码保留
                    Entities.Configuration.ValidateOnSaveEnabled = false;

                    using (SqlConnection connection = new SqlConnection(SqlHelper.MSSQLConnectionString))
                    {
                        connection.Open();
                        using (SqlTransaction tran = connection.BeginTransaction())
                        {
                            try
                            {
                                // 去重
                                //var approvalKeys = jArray
                                //    .Where(j => j["CustomerID"] != null && !string.IsNullOrWhiteSpace(j["CustomerID"].ToString())
                                //             && j["POTracker"] != null && !string.IsNullOrWhiteSpace(j["POTracker"].ToString()))
                                //    .Select(j => new
                                //    {
                                //        CustomerID = j["CustomerID"].ToString(),
                                //        POTracker = j["POTracker"].ToString()
                                //    })
                                //    .Distinct()
                                //    .ToList();
                                var approvalKeys = jArray
                                    .Where(j => j["CustomerID"] != null && !string.IsNullOrWhiteSpace(j["CustomerID"].ToString())
                                             && j["MaterialID"] != null && !string.IsNullOrWhiteSpace(j["MaterialID"].ToString()))
                                    .Select(j => new
                                    {
                                        CustomerID = j["CustomerID"].ToString(),
                                        MaterialID = j["MaterialID"].ToString()
                                    })
                                    .Distinct()
                                    .ToList();


                                foreach (var item in approvalKeys)
                                {
                                    SqlParameter[] sqlParameters = new SqlParameter[5];
                                    sqlParameters[0] = new SqlParameter("@Result", SqlDbType.Bit);
                                    sqlParameters[1] = new SqlParameter("@Msg", SqlDbType.NVarChar, 500);
                                    sqlParameters[2] = new SqlParameter("@Account", dev_Account.Account);  // 审批账号
                                    sqlParameters[3] = new SqlParameter("@CustomerID", item.CustomerID);
                                    sqlParameters[4] = new SqlParameter("@MaterialID", item.MaterialID);

                                    sqlParameters[0].Direction = sqlParameters[1].Direction = ParameterDirection.Output;

                                    SqlHelper.ExecuteNonQuery(tran, "P_需求计划审批", sqlParameters);

                                    result = sqlParameters[0].Value.ToString().ToLower() == "true";
                                    msg = sqlParameters[1].Value.ToString();

                                    if (!result)
                                    {
                                        tran.Rollback();
                                        break;
                                    }
                                }

                                // 如果都通过，再执行后续两个分配过程
                                if (result)
                                {
                                    using (SqlCommand cmd = new SqlCommand("P_需求计划行分配库存", connection, tran))
                                    {
                                        cmd.CommandType = CommandType.StoredProcedure;
                                        cmd.ExecuteNonQuery();
                                    }

                                    using (SqlCommand cmd = new SqlCommand("P_需求计划行分配销售订单", connection, tran))
                                    {
                                        cmd.CommandType = CommandType.StoredProcedure;
                                        cmd.ExecuteNonQuery();
                                    }

                                    tran.Commit();
                                    msg = "操作成功，已审批通过所选客户数据";
                                }
                            }
                            catch (Exception ex)
                            {
                                result = false;
                                msg = $"操作失败，错误信息: {ex.Message}";
                                tran.Rollback();
                            }
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                result = false;
                msg = "数据操作失败, 错误信息:" + ex.Message;
            }

            return JsonConvert.SerializeObject(new { result, msg });
        }
