        public void setDetail25486(DataRow dataRow)
        {
            DateTime endDate = DateTime.Now.Date;
            DateTime startDate = endDate.AddDays(-30);
            if (jObject.ContainsKey("DynamicDate1"))
            {
                JArray jArray = jObject["DynamicDate1"] as JArray;
                if (!string.IsNullOrEmpty(jArray[0].ToString()))
                {
                    startDate = DateTime.Parse(jArray[0].ToString());
                    endDate = DateTime.Parse(jArray[1].ToString());
                }
            }
            Dictionary<string, string> bColors = new Dictionary<string, string>();
            DateTime currentDate = startDate;

            string dataType = dataRow["DataType"]?.ToString() ?? "";
            decimal totalQty = 0;
            while (currentDate <= endDate)
            {
                string day = currentDate.ToString("yyyy-MM-dd");
                string filter1 = $"DataType = '{dataType}' AND CustomerID = {dataRow["CustomerID"]} AND MaterialID = {dataRow["MaterialID"]} AND PlanDay = '{day}'";
                string filter2 = $"DataType <> '{dataType}' AND CustomerID = {dataRow["CustomerID"]} AND MaterialID = {dataRow["MaterialID"]} AND PlanDay = '{day}'";

                string s1 = DtDetail.Compute("SUM(Qty)", filter1).ToString();
                string s2 = DtDetail.Compute("SUM(Qty)", filter2).ToString();

                decimal m1 = 0, m2 = 0;
                decimal.TryParse(s1, out m1);
                decimal.TryParse(s2, out m2);

                var col = ElementColumn[0].FirstOrDefault(c => c.prop == day);
                if (col != null && m1 > 0)
                {
                    dataRow[day] = m1;
                    col.visible = true;
                    totalQty += m1;
                }

                if (dataType == "出货" && m1 < m2)
                {
                    bColors.Add(day, "#FFA5E5");
                }
                currentDate = currentDate.AddDays(1);
            }
            dataRow["BColors"] = bColors;
            dataRow["TotalQty"] = totalQty;
        }

