            string msg = "操作成功";

            try
            {
                jArray = JsonConvert.DeserializeObject(BodyJson) as JArray;
                string sql = "truncate table APS_OrderPlanSheculing;";
                foreach (JObject jObject in jArray)
                {
                    if (!string.IsNullOrEmpty(jObject["OrderID"].ToString()))
                    {

                        sql += "INSERT INTO [APS_OrderPlanSheculing](OrderID,ProcessID,CreatedBy) values(" + jObject["OrderID"].ToString() + ",'" + jObject["ProcessID"].ToString() + "'" + ",'" + dev_Account.Account + "')";
                    }

                }
                if (!string.IsNullOrEmpty(sql))
                {
                    SqlHelper.ExecuteNonQuery(sql);
                    SqlHelper.ExecuteNonQuery("exec [P_根据工序计划ID自动分配线] 'ERP工单',1");
                }

            }
            catch (Exception ex)
            {
                result = false;
                msg = "数据操作失败,错误信息:" + ex.Message;
            }
            return JsonConvert.SerializeObject(new
