                {
                    if (!string.IsNullOrEmpty(jObject["MaterialID"].ToString()))
                    {

                        sql += "UPDATE APS_SalesPlanProcessMaterial SET IsTodo=1 WHERE MaterialID=" + jObject["MaterialID"] + ";";
