       a.ToolingCode,
       a.ToolingName,
       c.PlanDay,
       c.ProcessPlanID,
       -- 同一天内，不同 ToolingCode 的序号（同工装多行序号相同）
        DENSE_RANK() OVER (
           PARTITION BY c.PlanDay
           ORDER BY a.ToolingCode
       ) AS ToolingSeq_OnDay,
       -- 同一天 + 同一 ToolingCode 内，每条明细的序号（不去重）
  
