WHERE  a.Status = 1
       AND c.PlanDay >= CAST(GETDATE() AS DATE)
       AND c.ProcessPlanID IN (
               SELECT ProcessPlanID
               FROM   dbo.V_APS_MOPlanStep4 WITH (NOLOCK)
           );

 ");
