        List<string> lstPDF = new List<string>();
        Dictionary<string, int> lstPDFExt = new Dictionary<string, int>();
        Dictionary<string, int> lstPDFExt有逗号 = new Dictionary<string, int>();
        void TraverseDirectory(string path)
        {
            try
            {
                // 获取当前目录下所有文件
                string[] files = Directory.GetFiles(path);
                foreach (string file in files)
                {
                    FileInfo fileInfo = new FileInfo(file);
                    if (lstPDFExt.ContainsKey(fileInfo.Extension) == false)
                    {
                        lstPDFExt.Add(fileInfo.Extension, 1);
                    }
                    else
                    {
                        lstPDFExt[fileInfo.Extension] += 1;
                    }
                    if (file.Contains(' '))
                    {
                        if (lstPDFExt有逗号.ContainsKey(fileInfo.Extension) == false)
                        {
                            lstPDFExt有逗号.Add(fileInfo.Extension, 1);
                        }
                        else
                        {
                            lstPDFExt有逗号[fileInfo.Extension] += 1;
                        }
                    }

                    lstPDF.Add(file);
                }

                // 获取所有子目录，并递归调用
                string[] directories = Directory.GetDirectories(path);
                foreach (string directory in directories)
                {
                    TraverseDirectory(directory);
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("发生错误：" + ex.Message);
            }
        }
