                string msg = "";
                //string username = "APSUSER";
                //string password = "123456";
                string loginUrl = AppInfo.WMSUrl + "/api/login?username=APSUSER&password=123456";

                using (var client = new HttpClient())
                {
                    // 登录
                    var loginResponse = client.PostAsync(loginUrl, null).Result;
                    string loginResponseString = loginResponse.Content.ReadAsStringAsync().Result;

                    if (!loginResponse.IsSuccessStatusCode)
                        return JsonConvert.SerializeObject(new
                        {
                            result = false,
