                    var stockResponse = client.PostAsync(url, null).Result;
                    string stockResponseString = stockResponse.Content.ReadAsStringAsync().Result;

                    if (!stockResponse.IsSuccessStatusCode)
                        return JsonConvert.SerializeObject(new
                        {
                            result = false,
                            msg = $"库存请求失败，状态码：{(int)loginResponse.StatusCode}，响应：{loginResponseString}"
                        });

                    JObject json = JObject.Parse(stockResponseString);
                    if (json["success"]?.ToObject<bool>() != true)
                        return JsonConvert.SerializeObject(new
                        {
                            result = false,
                            msg = "库存接口返回 success!=true"
                        });


                    // 先清空表
                    StringBuilder sql = new StringBuilder();
                    sql.Append($@"TRUNCATE TABLE WMS_StockTemp;");
                    JArray results = JsonConvert.DeserializeObject(json["result"].ToString()) as JArray;
                    foreach (JObject obj in results)
