                        string wareHouseCode = obj["genWarehouse"]?["refCode"]?.ToString() ?? "";
                        string code = obj["genMaterial"]?["codeNo"]?.ToString() ?? "";
                        string materialName = obj["genMaterial"]?["name"]?.ToString() ?? "";
                        string rackCode = obj["rackNo"]?.ToString() ?? "";
                        string unit = obj["uom"]?.ToString() ?? "";
                        //string status = obj["grade"]?.ToString() ?? "";


