                        INSERT INTO [APS].[dbo].WMS_StockTemp 
                        (WareHouseName, WareHouseCode, Code, MaterialName, Qty, RackCode, Unit, Status)
                        SELECT '{wareHouseName}', '{wareHouseCode}', '{code}', '{materialName}', {qty}, '{rackCode}', '{unit}', 1;");

                    }
                    sql.Append($@"  EXEC [P_DownStock];
                                    DELETE FROM  [WMS_Stock] WHERE DataSource = 'WMS' OR Code1 IN (SELECT Code FROM WMS_StockTemp);

                                    INSERT INTO [APS].[dbo].[WMS_Stock]
                                                ([StockID],
                                                 [WarehouseID],
                                                 [MaterialID],
                                                 [MaterialName],
                                                 [StockQty],
                                                 [CreatedBy],
                                                 [CreatedByName],
                                                 [CreatedOn],
                                                 [ModifyedOn],
                                                 [Status],
                                                 [Code1],
                                                 StatusName,
                                                 WarehouseCode,
			                                     RackCode,
                                                 DataSource)
                                    SELECT Format(Getdate(), 'PyyMMddhhMMss')
                                                    + Cast(Row_number() OVER(ORDER BY C.MaterialID) AS VARCHAR(10)),
                                           B.WarehouseID,
                                           C.MaterialID,
                                           C.MaterialName,
                                           A.Qty,
                                           'system',
                                           'system',
                                           A.CreatedOn,
                                           A.ModifyedOn,
                                           1,
                                           C.Code,
                                           '可用',
                                           B.Code,
	                                       RackCode,
                                           'WMS'
                                    FROM   WMS_StockTemp A
                                           INNER JOIN WMS_Warehouse B
                                                   ON A.WareHouseCode = B.Code
                                           INNER JOIN APS_Material C
                                                   ON A.Code = C.Code 
                                    WHERE A.Qty>0;");

                    SqlHelper.ExecuteNonQuery(sql.ToString());

                    return JsonConvert.SerializeObject(new
                    {
                        result = true,
                        msg = "WMS数据处理完成"
                    });
                }
            }
            catch (Exception ex)
            {
                return JsonConvert.SerializeObject(new
                {
                    result = false,
                    msg = "处理过程中发生异常：" + ex.Message
                });
            }
        }
