        /// <summary>
        /// 易事特推送账号接口
        /// </summary>
        /// <returns></returns>
        public string PushAPSAccout()
        {
            JObject jObject = JsonConvert.DeserializeObject(BodyJson) as JObject;
            if (jObject == null || jObject.Count == 0)
            {
                return JsonConvert.SerializeObject(new
                {
                    code = 400,
                    msg = "未接受到数据，请确认是否为JSON格式"
                });
            }
            //从 JSON 中提取参数
            string dataType = jObject["dataType"]?.ToString() ?? string.Empty;
            string timestamp = jObject["timestamp"]?.ToString() ?? string.Empty;
            string sign = jObject["sign"]?.ToString() ?? string.Empty;
            string salt = jObject["salt"]?.ToString() ?? string.Empty;// 可选
            string syncData = jObject["syncData"]?.ToString() ?? string.Empty;



            // 参数校验
            if (string.IsNullOrEmpty(dataType) || dataType != "2" ||
                string.IsNullOrEmpty(timestamp) ||
                string.IsNullOrEmpty(sign) ||
                string.IsNullOrEmpty(syncData))
            {
                return JsonConvert.SerializeObject(new
                {
                    code = 400,
                    msg = "参数不合法"
                });
            }

            string[] parts = AppInfo.SSOUrl.Split('‖').Select(p => p.Trim()).ToArray();

            //string appId = "378c6c515d0949e9b33388dfddea7f9b";


            //string requestPath = "/APSAPI/PushAPSAccout"; 
            //string method = "POST";
            string appSecret = parts[6];

            //string raw = appId + (string.IsNullOrEmpty(salt) ? "" : salt) + timestamp + requestPath + method + appSecret;
            //// 计算 MD5 签名
            //string expectedSign;
            //using (var md5 = MD5.Create())
            //{
            //    byte[] inputBytes = Encoding.UTF8.GetBytes(raw);
            //    byte[] hashBytes = md5.ComputeHash(inputBytes);
            //    expectedSign = BitConverter.ToString(hashBytes).Replace("-", "").ToUpper();
            //} 
            //(!string.Equals(sign, expectedSign, StringComparison.OrdinalIgnoreCase))
            //{
            //    return JsonConvert.SerializeObject(new
            //    {
            //        code = 401,
            //        msg = "签名校验失败"
            //    });
            //}

            // 解密 syncData
            string syncDataResult;
            try
            {
                syncDataResult = DecryptToken(syncData, appSecret);
            }
            catch
            {
                return JsonConvert.SerializeObject(new
                {
                    code = 402,
                    msg = "syncData 解密失败"
                });
            }

            // 解析并处理账号数据
            try
            {
                var accountArray = JArray.Parse(syncDataResult);
                StringBuilder sql = new StringBuilder();

                foreach (var a in accountArray)
                {
                    string pwd = a["password"]?.ToString();
                    string account = a["principalId"]?.ToString();
                    string status = (a["status"]?.ToString() == "1") ? "0" : "1";
                    string name = a["attributes"]?["realName"]?.ToString();


                    // 若密码为空，设为默认密码123456
                    if (string.IsNullOrWhiteSpace(pwd))
                    {
                        pwd = "123456";
                    }

                    if (string.IsNullOrWhiteSpace(account))
                    {
                        return JsonConvert.SerializeObject(new
                        {
                            code = 403,
                            msg = "存在账号为空的数据"
                        });
                    }


                    //SQL拼接逻辑：判断账号是否存在，存在则更新，不存在则插入
                    sql.Append($@"
                                IF EXISTS(SELECT 1 FROM Dev_Account WHERE Account = '{account}')
                                BEGIN
                                    UPDATE Dev_Account
                                    SET Pwd = '{pwd}', Status = '{status}', ModifiedBy = 'East', ModifiedByName = '易事特', ModifyedOn = GetDate(),Name = '{name}'
                                    WHERE Account = '{account}';
                                                END
                                                ELSE
                                BEGIN
                                    INSERT INTO Dev_Account(Account, Pwd, Status, CreatedBy, CreatedByName, CreatedOn,OrganizeID,Name)
                                    SELECT '{account}', '{pwd}', '{status}', 'East', '易事特', GetDate(),160,'{name}';

                                    INSERT INTO Dev_RoleMap(RoleID,Account,CreatedBy,CreatedByName,CreatedOn,Status)
                                    SELECT                  RoleID,'{account}','East', '易事特',GetDate(),1
                                    FROM   Dev_Role
                                    WHERE  RoleName = '默认角色' AND '{status}' = 1;
                                    END
                            ");
                }
                SqlHelper.ExecuteNonQuery(sql.ToString());
                systemLog.SaveLog(SystemLog.SystemLogType.接口推送, "插入成功", null, null);
            }
            catch (Exception ex)
            {
                systemLog.SaveLog(SystemLog.SystemLogType.接口推送失败, ex.Message, null, null);
                return JsonConvert.SerializeObject(new
                {
                    code = 402,
                    msg = ex.Message
                });
            }

            // 成功响应
            return JsonConvert.SerializeObject(new
            {
                code = 1000,
                msg = "成功",
                data = sign
            });
        }
        /// <summary>
        /// 企业微信机器人推送接口
        /// </summary>
        /// <returns></returns> 
        public async Task<string> PostQyWeiXinAsync()
        {
            int currentHour = DateTime.Now.Hour;//获取当前时间的小时数
            string msg = "企业微信机器人消息推送开始";
            try
            {
                systemLog.SaveLog(SystemLog.SystemLogType.接口推送, msg, null, null);
                // 1. 获取所有机器人配置
                DataTable dtWebhooks = SqlHelper.ExecuteDataTable(@"SELECT * FROM V_Dev_Webhook WHERE Status = 1 AND WebhookType = '企业微信机器人' Order by PushSort");
                if (dtWebhooks.Rows.Count == 0)
                {
                    msg = "未找到有效的企业微信机器人配置";
                    systemLog.SaveLog(SystemLog.SystemLogType.接口推送失败, msg, null, null);
                    return msg;
                }
                //处理每条配置
                foreach (DataRow configRow in dtWebhooks.Rows)
                {
                    //2. 获取数据
                    string info = configRow["Info"]?.ToString();
                    string keys = configRow["Keys"]?.ToString();
                    string pushTime = configRow["PushTime"]?.ToString();
                    string pushTable = configRow["PushTable"]?.ToString();
                    int maxPushCount = configRow["MaxPushCount"] != DBNull.Value ? Convert.ToInt32(configRow["MaxPushCount"]) : 1000;
                    int pushInterval = configRow["PushInterval"] != DBNull.Value ? Convert.ToInt32(configRow["PushInterval"]) * 1000 : 1000;
                    string pushType = configRow["PushType"]?.ToString();
                    int id = Convert.ToInt32(configRow["ID"]);
                    int pushTimes = configRow["PushTimes"] != DBNull.Value ? Convert.ToInt32(configRow["PushTimes"]) : 0;
                    int remainPushTimes = configRow["RemainPushTimes"] != DBNull.Value ? Convert.ToInt32(configRow["RemainPushTimes"]) : 0;
                    int lastPushHour = configRow["LastPushHour"] != DBNull.Value ? Convert.ToInt32(configRow["LastPushHour"]) : -1;

                    if (string.IsNullOrEmpty(info) || string.IsNullOrEmpty(keys) || string.IsNullOrEmpty(pushTime) || string.IsNullOrEmpty(pushTable) || string.IsNullOrEmpty(pushType))
                    {
                        msg = $"{pushTable}的数据推送数据配置缺失，跳过该表的数据推送";
                        systemLog.SaveLog(SystemLog.SystemLogType.接口推送失败, msg, null, null);
                        continue;
                    }
                    //3. 检查推送时间
                    bool shouldPush = true;
                    var pushHours = pushTime.Split(',')
                            .Select(x => x.Trim())
                            .Where(x => !string.IsNullOrEmpty(x))
                            .Select(x => int.TryParse(x, out int hour) ? hour : -1)
                            .Where(x => x >= 0 && x <= 23);
                    shouldPush = pushHours.Contains(currentHour) ? true : false;
                    if (!shouldPush) continue;
                    // 3.1 判断是否还允许推送（防止重复执行）
                    if (lastPushHour == currentHour)
                    {
                        // 该时间点已经推送过
                        msg = $"{pushTable} 的 {currentHour} 点已经推送过，跳过该时间点重复推送";
                        systemLog.SaveLog(SystemLog.SystemLogType.接口推送失败, msg, null, null);
                        continue;
                    }
                    if (remainPushTimes <= 0 || remainPushTimes > pushTimes)
                    {
                        // 推送次数异常，不推送
                        msg = $"{pushTable} 的推送次数状态异常，RemainPushTimes = {remainPushTimes}, PushTimes = {pushTimes}，跳过";
                        systemLog.SaveLog(SystemLog.SystemLogType.接口推送失败, msg, null, null);
                        continue;
                    }

                    // 3.2 执行到这里说明应该推送，更新数据库中的 RemainPushTimes - 1
                    int affectRows = SqlHelper.ExecuteNonQuery($@"
                        UPDATE Dev_Webhook
                        SET RemainPushTimes = RemainPushTimes - 1,
                            LastPushHour = {currentHour},
                            ModifyedOn = Getdate()
                        WHERE ID = {id}
                    ");

                    // 3.3 如果更新失败（并发情况），则跳过推送
                    if (affectRows == 0)
                    {
                        msg = $"{pushTable} 的推送存在并发竞争，RemainPushTimes 未成功更新，跳过此次推送";
                        systemLog.SaveLog(SystemLog.SystemLogType.接口推送失败, msg, null, null);
                        continue;
                    }

                    //4. 获取表数据
                    DataTable dtData;
                    dtData = SqlHelper.ExecuteDataTable($"SELECT * FROM {pushTable}");
                    if (dtData.Rows.Count == 0)
                    {
                        msg = $"{pushTable}无数据可推送";
                        systemLog.SaveLog(SystemLog.SystemLogType.接口推送, msg, null, null);
                        continue;
                    }
                    //5. 拆分keys
                    var keyList = keys?.Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries)
                                    .Select(k => k.Trim())
                                    .Where(k => !string.IsNullOrEmpty(k))
                                    .ToList() ?? new List<string>();

                    if (!keyList.Any())
                    {
                        msg = $"{pushTable}的数据推送接口解析失败";
                        systemLog.SaveLog(SystemLog.SystemLogType.接口推送失败, msg, null, null);
                        continue;
                    }

                    //绘制数据
                    //string pushTitle = configRow["PushTitle"]?.ToString();
                    string pushTitle = dtData.Rows[0]["PushTitle"]?.ToString();//改成从数据表获取标题
                    string pushMessage = configRow["PushMessage"]?.ToString();

                    int totalCount = dtData.Rows.Count;//数据总量
                    int sendTimes = (int)Math.Ceiling((double)totalCount / maxPushCount);//计算发送的次数
                    Dictionary<string, int> successCounts = new Dictionary<string, int>(); // 记录每个key的成功次数
                    foreach (var key in keyList)
                    {
                        successCounts[key] = 0;
                    }

                    for (int i = 0; i < sendTimes; i++)
                    {
                        int startIndex = i * maxPushCount;
                        int endIndex = Math.Min((i + 1) * maxPushCount, totalCount);
                        // 构建 markdown_v2 内容
                        StringBuilder markdownContent = new StringBuilder();
                        if (pushType == "卡片")
                        {
                            // 添加标题
                            string titleLine = sendTimes == 1
                                ? $"# {pushTitle}\n"
                                : $"# {pushTitle}{i + 1}\n";

                            markdownContent.AppendLine(titleLine);

                            // 添加说明提示
                            //markdownContent.AppendLine("> 数据如下所示：\n");

                            // 构建数据行（每条数据为一块）
                            for (int j = startIndex; j < endIndex; j++)
                            {
                                foreach (DataColumn col in dtData.Columns)
                                {

                                    string colName = col.ColumnName;
                                    // 跳过 PushTitle 字段
                                    if (colName.Equals("PushTitle", StringComparison.OrdinalIgnoreCase))
                                        continue;
                                    string value = dtData.Rows[j][col]?.ToString()?.Replace("\n", " ").Replace("|", "｜") ?? ""; // 防止 markdown 字符冲突
                                    markdownContent.AppendLine($"**{colName}：** {value} \n");
                                }

                                markdownContent.AppendLine("\n---\n"); // 分隔线
                            }
                        }
                        else if (pushType == "表格")
                        {
                            // 添加标题（使用markdown_v2的标题语法）
                            markdownContent.AppendLine($"# {pushTitle}\n");
                            // 构建表头
                            List<string> headers = new List<string>();

                            // 添加序号列
                            //headers.Add("序号");

                            // 添加数据列
                            foreach (DataColumn Col in dtData.Columns)
                            {
                                string colName = Col.ColumnName;
                                // 跳过 PushTitle 字段
                                if (colName.Equals("PushTitle", StringComparison.OrdinalIgnoreCase))
                                    continue;
                                headers.Add(colName);
                            }

                            // 输出表头行
                            markdownContent.AppendLine("| " + string.Join(" | ", headers) + " |");

                            // 输出对齐行
                            markdownContent.AppendLine("|" + string.Join("|", headers.Select(h =>
                            {
                                if (h == "序号") return " :----: ";// 序号居中
                                return " :---- ";// 其他列左对齐
                            })) + "|");

                            // 构建表格数据行
                            for (int j = startIndex; j < endIndex; j++)
                            {
                                List<string> rowData = new List<string>();
                                //rowData.Add((j + 1).ToString());  // 序号

                                foreach (DataColumn col in dtData.Columns)
                                {
                                    if (col.ColumnName.Equals("PushTitle", StringComparison.OrdinalIgnoreCase))
                                        continue;
                                    rowData.Add(dtData.Rows[j][col.ColumnName]?.ToString() ?? "");
                                }

                                markdownContent.AppendLine("| " + string.Join(" | ", rowData) + " |");
                            }
                        }

                        // 构建请求体
                        var contentJson = new
                        {
                            msgtype = "markdown_v2",
                            markdown_v2 = new
                            {
                                content = markdownContent.ToString()
                            }
                        };
                        //开始推送
                        try
                        {
                            var json = JsonConvert.SerializeObject(contentJson);
                            // 对每个key进行推送
                            foreach (var key in keyList)
                            {
                                var fullUrl = $"{info}{key}";
                                var content = new StringContent(json, Encoding.UTF8, "application/json");

                                using (HttpClient client = new HttpClient())
                                {
                                    var response = await client.PostAsync(fullUrl, content);
                                    string result = await response.Content.ReadAsStringAsync();

                                    if (response.IsSuccessStatusCode)
                                    {
                                        successCounts[key]++;
                                        systemLog.SaveLog(SystemLog.SystemLogType.接口推送, $"信息推送(key:{key})成功(第{i + 1}批)，共{endIndex - startIndex}条", null, null);
                                    }
                                    else
                                    {
                                        systemLog.SaveLog(SystemLog.SystemLogType.接口推送失败, $"信息推送(key:{key})失败(第{i + 1}批)，错误: {result}", null, null);
                                    }
                                }
                            }
                        }
                        catch (Exception ex)
                        {
                            systemLog.SaveLog(SystemLog.SystemLogType.接口推送失败, $"请求异常(第{i + 1}批)：{ex.Message}", null, null);
                        }

                        if (i < sendTimes - 1 && pushInterval > 0)
                        {
                            await Task.Delay(pushInterval);
                        }
                    }

                    string successSummary = string.Join("，", successCounts.Select(kv => $"key:{kv.Key}成功{kv.Value}批"));
                    systemLog.SaveLog(SystemLog.SystemLogType.接口推送, $"消息推送完成，共{sendTimes}批，{successSummary}", null, null);
                }

                // 添加默认返回值
                msg = "全部数据推送完成";
                systemLog.SaveLog(SystemLog.SystemLogType.接口推送, msg, null, null);
                return msg;
            }
            catch (Exception ex)
            {
                msg = $"获取消息内容失败：{ex.Message}";
                systemLog.SaveLog(SystemLog.SystemLogType.接口推送失败, msg, null, null);
                return msg;
            }
        }









        /// <summary>
        /// 存储过程逻辑接口（数据库版本是2016之后）
        /// </summary>
        /// <returns></returns> 
        /// 
        public ApsLegacyJsonResult StoredProcedureInterfaces()

        {
            bool result = true;
            string msg = "";
            string ReponseData = null;
            ApsLegacyJsonResult ApsLegacyJsonResult = new ApsLegacyJsonResult();
            try
            {


                JObject jObject = JsonConvert.DeserializeObject(BodyJson) as JObject;
                if (jObject == null)
                {
                    msg = "未接收到数据，请确认是否为JSON格式";
                    result = false;
                }
                else
                {

                    if (jObject.ContainsKey("ButtonMenuMapID") == false)
                    {
                        msg = "请配置按钮";
                        result = false;
                        ApsLegacyJsonResult = base.FormResult(result, msg, ReponseData);
                        return ApsLegacyJsonResult;

                    }
                    else if (dev_Account == null)
                    {
                        msg = "请配置Token";
                        result = false;
                        ApsLegacyJsonResult = base.FormResult(result, msg, ReponseData);
                        return ApsLegacyJsonResult;
                    }
                    string ButtonMenuMapID = jObject["ButtonMenuMapID"].ToString();

                    string UserName = dev_Account.Name;
                    string UserAccount = dev_Account.Account;
                    DataTable dtDetail1 = SqlHelper.ExecuteDataTable(string.Format(
                    @"select top(1) StoreProcedure 
                    from Dev_ButtonMenuMap a

                    where  a.ButtonMenuMapID = '{0}' and exists(select 1 
                    from Dev_RoleMap t 
                    left join [dbo].[Dev_ButtonMenuRoleMap] t1
                    on t.RoleID = t1.RoleID
                    where t.Account = '{1}' and t1.ButtonMenuMapID = a.ButtonMenuMapID
                    ) ", ButtonMenuMapID, UserAccount));

                    // 添加空值检查
                    if (dtDetail1 == null || dtDetail1.Rows.Count == 0)
                    {
                        msg = "未找到对应的菜单按钮配置或用户无权限";
                        result = false;
                        ApsLegacyJsonResult = base.FormResult(result, msg, null);
                        return ApsLegacyJsonResult; // 记得返回，避免继续执行
                    }
                    DataRow firstRow = dtDetail1.AsEnumerable().FirstOrDefault();
                    string StoredProcedure = firstRow["StoreProcedure"].ToString();
                    string jsonData = null;
                    if (jObject.ContainsKey("data") == true)
                    {
                        jsonData = jObject["data"].ToString();
                    }

                    if (string.IsNullOrEmpty(StoredProcedure))
                    {
                        msg = "存储过程名称为空，请检查菜单按钮配置";
                        result = false;
                        ApsLegacyJsonResult = base.FormResult(result, msg, null);
                    }
                    else
                    {

                        if (UserAccount != null)
                        {
                            SqlParameter[] sqlParameters = new SqlParameter[6];
                            sqlParameters[0] = new SqlParameter("@jsonData", jsonData);//传数据
                            sqlParameters[1] = new SqlParameter("@UserName", UserName);//用户名
                            sqlParameters[2] = new SqlParameter("@UserAccount", UserAccount);//用户账号
                            sqlParameters[3] = new SqlParameter("@Result", SqlDbType.Bit);//结果
                            sqlParameters[4] = new SqlParameter("@Msg", SqlDbType.NVarChar, 500);//返回消息
                            sqlParameters[5] = new SqlParameter("@ReponseData", SqlDbType.NVarChar, -1);//返回数据
                            sqlParameters[3].Direction = sqlParameters[4].Direction = sqlParameters[5].Direction = ParameterDirection.Output;
                            SqlHelper.ExecuteNonQuery(SqlHelper.MSSQLConnectionString, StoredProcedure, sqlParameters);
                            result = sqlParameters[3].Value.ToString().ToLower() == "true";
                            msg = sqlParameters[4].Value.ToString();
                            ReponseData = sqlParameters[5].Value.ToString();


                        }
                    }
                }
            }
            catch (Exception ex)
            {
                result = false;
                msg = ex.Message;

            }
            ApsLegacyJsonResult = base.FormResult(result, msg, ReponseData);
            return ApsLegacyJsonResult;
        }



