        /// <summary>
        /// 锁定计划，会传每一行的默认锁定日期
        /// </summary>
        /// <returns></returns>
        public string LockPlan()
        {
            bool result = true;
            string msg = "操作成功";

            try
            {
                // 前端传的是对象，不是数组，直接反序列化为 JObject
                JObject jObject = JsonConvert.DeserializeObject<JObject>(BodyJson);

                // 读取 expiryDate 和 apsType 参数
                string expiryDate = "";
                string apsType = "";

                // 直接读取对象属性
                if (jObject != null)
                {
                    // 读取参数
                    if (jObject["expiryDate"] != null && !string.IsNullOrEmpty(jObject["expiryDate"].ToString()))
                    {
                        expiryDate = jObject["expiryDate"].ToString();
                    }
                    if (jObject["APSType"] != null && !string.IsNullOrEmpty(jObject["APSType"].ToString()))
                    {
                        apsType = jObject["APSType"].ToString();
                    }
                }

                if (!string.IsNullOrEmpty(expiryDate) && !string.IsNullOrEmpty(apsType))
                {
                    // 调用 P_锁定计划 存储过程，传入 expiryDate 和 APSType 参数
                    SqlParameter[] sqlParameters = new SqlParameter[4];
                    sqlParameters[0] = new SqlParameter("@ExpiryDate", DateTime.Parse(expiryDate));
                    sqlParameters[1] = new SqlParameter("@APSType", apsType);
                    sqlParameters[2] = new SqlParameter("@Account", dev_Account.Account);

                    SqlHelper.ExecuteNonQuery(SqlHelper.MSSQLConnectionString, "P_锁定计划", sqlParameters);
                }
                else
                {
                    result = false;
                    msg = "参数不完整，缺少 截止日期 或 工单类型";
                }
            }
            catch (Exception ex)
            {
                result = false;
                msg = "数据操作失败,错误信息:" + ex.Message;
            }
            return JsonConvert.SerializeObject(new
            {
                result,
                msg
            });
        }
        /// <summary>
        /// 解锁计划，会传解锁的原因
        /// </summary>
        /// <returns></returns>
        public string UnLockPlan()
        {
            bool result = true;
            string msg = "操作成功";

            try
            {
                JObject jObject = JsonConvert.DeserializeObject<JObject>(BodyJson);

                // 读取 expiryDate 和 APSType 参数
                int abnormalReasonID = 0;
