                    // 读取参数
                    if (jObject["AbnormalReasonID"] != null && !string.IsNullOrEmpty(jObject["AbnormalReasonID"].ToString()))
                    {
                        int.TryParse(jObject["AbnormalReasonID"].ToString(), out abnormalReasonID);
                    }
                    if (jObject["APSType"] != null && !string.IsNullOrEmpty(jObject["APSType"].ToString()))
                    {
                        apsType = jObject["APSType"].ToString();
                    }
                }

                if (abnormalReasonID > 0 && !string.IsNullOrEmpty(apsType))
                {
                    // 调用 P_锁定计划 存储过程，传入 expiryDate 和 APSType 参数
                    SqlParameter[] sqlParameters = new SqlParameter[3];
                    sqlParameters[0] = new SqlParameter("@AbnormalReasonID", abnormalReasonID);
                    sqlParameters[1] = new SqlParameter("@APSType", apsType);
                    sqlParameters[2] = new SqlParameter("@Account", dev_Account.Account);

                    SqlHelper.ExecuteNonQuery(SqlHelper.MSSQLConnectionString, "P_解锁计划", sqlParameters);
